function parseRecord(record) {
  if (!Array.isArray(record) || record.length !== 4) {
    throw new TypeError('each record must be [name, initial, sold, threshold]');
  }
  const [name, initial, sold, threshold] = record;
  if (typeof name !== 'string' || name.trim() === '') {
    throw new TypeError('product name must be a non-empty string');
  }
  const quantities = [initial, sold, threshold];
  if (!quantities.every((value) => Number.isInteger(value) && value >= 0)) {
    throw new TypeError(`quantities for "${name}" must be non-negative integers`);
  }
  if (sold > initial) {
    throw new RangeError(`sold quantity for "${name}" exceeds the initial quantity`);
  }
  return { name: name.trim(), initial, sold, threshold };
}

function reorderAmount(remaining, threshold) {
  if (remaining >= threshold) {
    return 0;
  }
  const target = threshold * 2;
  return target - remaining;
}

function inventory(records) {
  if (!Array.isArray(records)) {
    throw new TypeError('records must be a list of lists');
  }
  const result = [];
  for (const record of records) {
    const item = parseRecord(record);
    const remaining = item.initial - item.sold;
    const amount = reorderAmount(remaining, item.threshold);
    if (amount > 0) {
      result.push([item.name, amount]);
    }
  }
  return result;
}

function formatReport(orders) {
  if (orders.length === 0) {
    return 'All products are at or above their thresholds.';
  }
  const widest = orders.reduce((max, [name]) => Math.max(max, name.length), 0);
  const lines = orders.map(([name, amount]) => `${name.padEnd(widest)}  ${String(amount).padStart(5)}`);
  const total = orders.reduce((sum, [, amount]) => sum + amount, 0);
  lines.push(`${'TOTAL'.padEnd(widest)}  ${String(total).padStart(5)}`);
  return lines.join('\n');
}

function main() {
  const stock = [
    ['apple', 50, 45, 10],
    ['banana', 120, 30, 25],
    ['cherry', 80, 79, 12],
    ['date', 40, 40, 5],
    ['elderberry', 15, 3, 10],
  ];
  const orders = inventory(stock);
  console.log(JSON.stringify(orders));
  console.log(formatReport(orders));
}

main();

module.exports = { inventory, reorderAmount, formatReport };

