function validateInput(prices, window) {
  if (!Array.isArray(prices)) {
    throw new TypeError('prices must be an array of numbers');
  }
  const hasInvalidValue = prices.some((price) => typeof price !== 'number' || Number.isNaN(price));
  if (hasInvalidValue) {
    throw new TypeError('prices must contain only finite numbers');
  }
  if (!Number.isInteger(window) || window < 1) {
    throw new RangeError('window must be a positive integer');
  }
}

function roundToCents(value) {
  const scaled = Math.round(value * 100);
  return scaled / 100;
}

function smooth(prices, window) {
  validateInput(prices, window);
  const averages = [];
  if (window > prices.length) {
    return averages;
  }
  let runningSum = 0;
  for (let i = 0; i < window; i += 1) {
    runningSum += prices[i];
  }
  averages.push(roundToCents(runningSum / window));
  for (let end = window; end < prices.length; end += 1) {
    const leaving = prices[end - window];
    runningSum += prices[end] - leaving;
    averages.push(roundToCents(runningSum / window));
  }
  return averages;
}

function trendOf(averages) {
  if (averages.length < 2) {
    return 'flat';
  }
  const first = averages[0];
  const last = averages[averages.length - 1];
  if (last > first) {
    return 'rising';
  }
  return last < first ? 'falling' : 'flat';
}

function describeSeries(label, prices, window) {
  const averages = smooth(prices, window);
  const body = averages.length > 0 ? averages.join(', ') : '(no full window)';
  const trend = trendOf(averages);
  return `${label}: window=${window} -> [${body}] (${trend})`;
}

function main() {
  const dailyClose = [1, 2, 3, 4];
  const weeklyClose = [10.25, 9.5, 11, 12.75, 12, 11.5, 13.25];
  const shortSeries = [5, 6];
  const reports = [
    describeSeries('daily', dailyClose, 2),
    describeSeries('weekly', weeklyClose, 3),
    describeSeries('short', shortSeries, 5),
  ];
  for (const line of reports) {
    console.log(line);
  }
}

main();

module.exports = { smooth, describeSeries, trendOf };

