const ROMAN_VALUES = {
  I: 1,
  V: 5,
  X: 10,
  L: 50,
  C: 100,
  D: 500,
  M: 1000
};

const ROMAN_NUMERALS = [
  ['M', 1000],
  ['CM', 900],
  ['D', 500],
  ['CD', 400],
  ['C', 100],
  ['XC', 90],
  ['L', 50],
  ['XL', 40],
  ['X', 10],
  ['IX', 9],
  ['V', 5],
  ['IV', 4],
  ['I', 1]
];

function parseRoman(numeral) {
  const cleaned = String(numeral).trim().toUpperCase();
  if (cleaned.length === 0) {
    throw new Error('Empty Roman numeral');
  }
  let total = 0;
  let previous = 0;
  for (let i = cleaned.length - 1; i >= 0; i -= 1) {
    const symbol = cleaned[i];
    const value = ROMAN_VALUES[symbol];
    if (value === undefined) {
      throw new Error(`Invalid Roman symbol: ${symbol}`);
    }
    if (value < previous) {
      total -= value;
    } else {
      total += value;
      previous = value;
    }
  }
  return total;
}

function toRoman(number) {
  if (!Number.isInteger(number) || number < 1) {
    throw new Error('Only positive integers can be written as Roman numerals');
  }
  let remaining = number;
  const parts = [];
  for (const [symbol, value] of ROMAN_NUMERALS) {
    while (remaining >= value) {
      parts.push(symbol);
      remaining -= value;
    }
  }
  return parts.join('');
}

function calculate(numerals) {
  const [first, second] = numerals;
  const sum = parseRoman(first) + parseRoman(second);
  return toRoman(sum);
}

function main() {
  const pairs = [['XIV', 'LX'], ['MCMXC', 'IX'], ['III', 'IV']];
  for (const pair of pairs) {
    const result = calculate(pair);
    const total = parseRoman(result);
    console.log(`${pair[0]} + ${pair[1]} = ${result} (${total})`);
  }
}

main();

