const SENTENCE_END = /[.!?]/;

function normalizeWhitespace(text) {
  const collapsed = text.replace(/[ \t]+/g, ' ');
  return collapsed.trim();
}

function splitSentences(text) {
  const fragments = [];
  let start = 0;
  let index = 0;
  while (index < text.length) {
    if (SENTENCE_END.test(text[index])) {
      let end = index + 1;
      while (end < text.length && SENTENCE_END.test(text[end])) {
        end += 1;
      }
      fragments.push(text.slice(start, end));
      start = end;
      index = end;
    } else {
      index += 1;
    }
  }
  if (start < text.length) {
    fragments.push(text.slice(start));
  }
  return fragments;
}

function capitalizeFragment(fragment) {
  const position = fragment.search(/[a-z]/i);
  if (position === -1) {
    return fragment;
  }
  const prefix = fragment.slice(0, position);
  const initial = fragment[position].toUpperCase();
  return prefix + initial + fragment.slice(position + 1);
}

function capitalize(text) {
  if (typeof text !== 'string') {
    throw new TypeError('capitalize expects a string');
  }
  const normalized = normalizeWhitespace(text);
  const fragments = splitSentences(normalized);
  return fragments.map(capitalizeFragment).join('');
}

function describe(original) {
  const corrected = capitalize(original);
  const sentenceCount = splitSentences(normalizeWhitespace(original)).length;
  const changed = corrected !== original;
  const status = changed ? 'corrected' : 'unchanged';
  return `[${sentenceCount} sentence(s), ${status}] ${corrected}`;
}

function main() {
  const samples = [
    'hello world.  how are you? fine.',
    '   this\thas   messy spacing!   really?! yes.',
    'Already Fine. No Changes Needed.',
  ];
  for (const sample of samples) {
    console.log(describe(sample));
  }
}

main();

module.exports = { capitalize, normalizeWhitespace, splitSentences, describe };

