const OCTET_COUNT = 4;
const MASK_BITS = 24;

function parseOctets(address) {
  const parts = String(address).trim().split('.');
  if (parts.length !== OCTET_COUNT) {
    throw new Error(`"${address}" does not have ${OCTET_COUNT} octets`);
  }
  return parts.map((part) => {
    if (!/^\d{1,3}$/.test(part)) {
      throw new Error(`"${address}" contains a non-numeric octet "${part}"`);
    }
    const value = Number(part);
    if (value > 255) {
      throw new Error(`"${address}" has an octet out of range: ${part}`);
    }
    return value;
  });
}

function toInt(address) {
  const octets = parseOctets(address);
  let result = 0;
  for (const octet of octets) {
    result = (result << 8) | octet;
  }
  return result >>> 0;
}

function toDotted(value) {
  const octets = [];
  for (let shift = 24; shift >= 0; shift -= 8) {
    octets.push((value >>> shift) & 0xff);
  }
  return octets.join('.');
}

function maskOf(bits) {
  return bits === 0 ? 0 : (0xffffffff << (32 - bits)) >>> 0;
}

function subnet(addresses) {
  if (!Array.isArray(addresses) || addresses.length === 0) {
    throw new Error('subnet requires a non-empty list of addresses');
  }
  const mask = maskOf(MASK_BITS);
  const networks = addresses.map((address) => (toInt(address) & mask) >>> 0);
  const base = networks[0];
  const shared = networks.every((network) => network === base);
  return [shared, toDotted(base)];
}

function report(addresses) {
  const [shared, network] = subnet(addresses);
  const verb = shared ? 'share' : 'do not share';
  return `${addresses.join(', ')} ${verb} the /${MASK_BITS} network ${network}`;
}

const samples = [
  ['192.168.1.5', '192.168.1.12'],
  ['10.0.0.1', '10.0.1.1'],
  ['172.16.34.200', '172.16.34.1', '172.16.34.255'],
];

for (const sample of samples) {
  console.log(report(sample));
}

module.exports = { subnet, toInt, toDotted, report };

