const DOOR_TIME = 2;
const START_FLOOR = 0;

function normalizeRequests(requests) {
  if (!Array.isArray(requests)) {
    throw new TypeError('requests must be an array of floor numbers');
  }
  const floors = [];
  for (const raw of requests) {
    const floor = Number(raw);
    if (!Number.isInteger(floor)) {
      throw new TypeError(`invalid floor request: ${String(raw)}`);
    }
    floors.push(floor);
  }
  return floors;
}

function simulate(requests) {
  const floors = normalizeRequests(requests);
  let current = START_FLOOR;
  let total = 0;
  for (const target of floors) {
    const travel = Math.abs(target - current);
    total += travel + DOOR_TIME;
    current = target;
  }
  return total;
}

function buildItinerary(requests) {
  const floors = normalizeRequests(requests);
  const legs = [];
  let current = START_FLOOR;
  let elapsed = 0;
  for (const target of floors) {
    const travel = Math.abs(target - current);
    const arrival = elapsed + travel;
    legs.push({
      from: current,
      to: target,
      travel,
      arrival,
      departure: arrival + DOOR_TIME,
    });
    elapsed = arrival + DOOR_TIME;
    current = target;
  }
  return legs;
}

function describeItinerary(requests) {
  const legs = buildItinerary(requests);
  const lines = legs.map((leg, index) => {
    const step = index + 1;
    const direction = leg.to >= leg.from ? 'up' : 'down';
    return `${step}. floor ${leg.from} -> ${leg.to} (${direction}, ${leg.travel} units), ` +
      `doors open at t=${leg.arrival}, closed at t=${leg.departure}`;
  });
  const total = legs.length === 0 ? 0 : legs[legs.length - 1].departure;
  lines.push(`Total time: ${total} units`);
  return lines.join('\n');
}

function main() {
  const scenarios = [[3, 1], [0, 0, 5], [-2, 4, 4, 1]];
  for (const scenario of scenarios) {
    const label = `[${scenario.join(', ')}]`;
    console.log(`Requests ${label} -> ${simulate(scenario)} units`);
    console.log(describeItinerary(scenario));
    console.log('');
  }
}

main();

module.exports = { simulate, buildItinerary, describeItinerary };

