  if (shape[0] === 3 && shape[1] === 2) return 6;
  if (flush) return 5;
  if (straight) return 4;
  if (shape[0] === 3) return 3;
  if (shape[0] === 2 && shape[1] === 2) return 2;
  if (shape[0] === 2) return 1;
  return 0;
}

