const COIN_VALUES = [25, 10, 5, 1];
const COIN_NAMES = ["quarter", "dime", "nickel", "penny"];
const PLURAL_NAMES = ["quarters", "dimes", "nickels", "pennies"];

function change(amount) {
  if (!Number.isInteger(amount)) {
    throw new TypeError(`amount must be an integer, got ${amount}`);
  }
  if (amount < 0) {
    throw new RangeError(`amount must not be negative, got ${amount}`);
  }

  const counts = [];
  let remaining = amount;

  for (const value of COIN_VALUES) {
    const count = Math.floor(remaining / value);
    counts.push(count);
    remaining -= count * value;
  }

  return counts;
}

function totalCoins(counts) {
  return counts.reduce((sum, count) => sum + count, 0);
}

function valueOf(counts) {
  let cents = 0;
  for (let i = 0; i < counts.length; i += 1) {
    cents += counts[i] * COIN_VALUES[i];
  }
  return cents;
}

function describe(counts) {
  const parts = [];

  counts.forEach((count, index) => {
    if (count > 0) {
      const name = count === 1 ? COIN_NAMES[index] : PLURAL_NAMES[index];
      parts.push(`${count} ${name}`);
    }
  });

  if (parts.length === 0) {
    return "no coins";
  }
  if (parts.length === 1) {
    return parts[0];
  }

  const last = parts.pop();
  return `${parts.join(", ")} and ${last}`;
}

function report(amount) {
  const counts = change(amount);
  const formatted = `[${counts.join(", ")}]`;
  const coins = totalCoins(counts);
  const unit = coins === 1 ? "coin" : "coins";
  return `${amount}c -> ${formatted}  (${coins} ${unit}: ${describe(counts)})`;
}

function main() {
  const amounts = [68, 0, 4, 99, 137, 250];

  for (const amount of amounts) {
    console.log(report(amount));
  }

  const checked = amounts.every((amount) => valueOf(change(amount)) === amount);
  console.log(checked ? "All amounts reproduce exactly." : "Mismatch detected.");
}

main();

