function validatePagination(parameters) {
  if (!Array.isArray(parameters) || parameters.length !== 3) {
    throw new TypeError('paginate expects a list of exactly three integers');
  }
  const [current, total, siblings] = parameters;
  for (const value of parameters) {
    if (!Number.isInteger(value)) {
      throw new TypeError(`expected integers, received ${value}`);
    }
  }
  if (total < 1) {
    throw new RangeError('total number of pages must be at least 1');
  }
  if (current < 1 || current > total) {
    throw new RangeError(`current page ${current} is outside 1..${total}`);
  }
  if (siblings < 0) {
    throw new RangeError('sibling count cannot be negative');
  }
  return { current, total, siblings };
}

function paginate(parameters) {
  const { current, total, siblings } = validatePagination(parameters);
  const windowStart = Math.max(1, current - siblings);
  const windowEnd = Math.min(total, current + siblings);
  const pages = new Set([1, total]);
  for (let page = windowStart; page <= windowEnd; page += 1) {
    pages.add(page);
  }
  const ordered = [...pages].sort((a, b) => a - b);
  const result = [];
  let previous = 0;
  for (const page of ordered) {
    if (previous !== 0 && page - previous > 1) {
      result.push(-1);
    }
    result.push(page);
    previous = page;
  }
  return result;
}

function renderPagination(parameters) {
  const sequence = paginate(parameters);
  const [current] = parameters;
  const cells = sequence.map((page) => {
    if (page === -1) {
      return '...';
    }
    return page === current ? `[${page}]` : String(page);
  });
  return cells.join(' ');
}

function main() {
  const cases = [
    [4, 10, 1],
    [1, 10, 2],
    [10, 10, 2],
    [6, 7, 3],
    [1, 1, 0],
  ];
  for (const parameters of cases) {
    const pages = paginate(parameters);
    const label = parameters.join(', ');
    console.log(`(${label}) -> ${JSON.stringify(pages)}   ${renderPagination(parameters)}`);
  }
}

main();

