function signature(word) {
  const letters = word.split('');
  letters.sort();
  return letters.join('');
}

function validateWords(words) {
  if (!Array.isArray(words)) {
    throw new TypeError('anagrams expects an array of words');
  }
  const cleaned = [];
  for (const word of words) {
    if (typeof word !== 'string') {
      throw new TypeError(`expected a string, received ${typeof word}`);
    }
    const trimmed = word.trim().toLowerCase();
    if (trimmed.length > 0) {
      cleaned.push(trimmed);
    }
  }
  return cleaned;
}

function buildGroups(words) {
  const buckets = new Map();
  for (const word of words) {
    const key = signature(word);
    const bucket = buckets.get(key);
    if (bucket) {
      bucket.add(word);
    } else {
      buckets.set(key, new Set([word]));
    }
  }
  return buckets;
}

function anagrams(words) {
  const cleaned = validateWords(words);
  const buckets = buildGroups(cleaned);
  const groups = [];
  for (const bucket of buckets.values()) {
    const group = Array.from(bucket);
    group.sort();
    groups.push(group);
  }
  groups.sort((left, right) => {
    const bySize = right.length - left.length;
    if (bySize !== 0) {
      return bySize;
    }
    return left[0].localeCompare(right[0]);
  });
  return groups;
}

function formatGroups(groups) {
  const lines = groups.map((group) => {
    const label = group.length === 1 ? 'word' : 'words';
    return `${group.length} ${label}: ${group.join(', ')}`;
  });
  return lines.join('\n');
}

function main() {
  const sample = ['tar', 'rat', 'art', 'bat', 'Tab', 'abt', ' tab '];
  const grouped = anagrams(sample);
  console.log(JSON.stringify(grouped));
  console.log(formatGroups(grouped));
}

main();

module.exports = { anagrams, signature, formatGroups };

