function validateColor(color, label) {
  if (!Array.isArray(color) || color.length !== 3) {
    throw new TypeError(`${label} must be an array of three channel values`);
  }
  for (const channel of color) {
    if (!Number.isInteger(channel) || channel < 0 || channel > 255) {
      throw new RangeError(`${label} has an invalid channel value: ${channel}`);
    }
  }
  return color;
}

function gradient(colors, steps) {
  if (!Array.isArray(colors) || colors.length !== 2) {
    throw new TypeError('colors must contain exactly two color arrays');
  }
  if (!Number.isInteger(steps) || steps < 0) {
    throw new RangeError('steps must be a non-negative integer');
  }
  const start = validateColor(colors[0], 'start color');
  const end = validateColor(colors[1], 'end color');
  const intervals = steps + 1;
  const deltas = end.map((channel, index) => (channel - start[index]) / intervals);
  const sequence = [];
  for (let step = 0; step <= intervals; step += 1) {
    const shade = start.map((channel, index) => Math.round(channel + deltas[index] * step));
    sequence.push(shade);
  }
  return sequence;
}

function toHex(color) {
  const digits = color.map((channel) => channel.toString(16).padStart(2, '0'));
  return `#${digits.join('')}`;
}

function describeGradient(colors, steps) {
  const sequence = gradient(colors, steps);
  const width = String(sequence.length - 1).length;
  const lines = sequence.map((shade, index) => {
    const position = String(index).padStart(width, ' ');
    const channels = shade.map((channel) => String(channel).padStart(3, ' '));
    return `${position}: rgb(${channels.join(', ')})  ${toHex(shade)}`;
  });
  return lines.join('\n');
}

function main() {
  const demo = gradient([[0, 0, 0], [10, 20, 30]], 1);
  console.log(JSON.stringify(demo));

  const ramps = [
    { colors: [[255, 0, 0], [0, 0, 255]], steps: 3 },
    { colors: [[16, 16, 16], [240, 200, 120]], steps: 5 },
    { colors: [[100, 100, 100], [100, 100, 100]], steps: 0 },
  ];
  for (const ramp of ramps) {
    const header = `${toHex(ramp.colors[0])} -> ${toHex(ramp.colors[1])} (${ramp.steps} steps)`;
    console.log(`\n${header}`);
    console.log(describeGradient(ramp.colors, ramp.steps));
  }

  try {
    gradient([[0, 0, 0], [256, 0, 0]], 2);
  } catch (error) {
    console.log(`\nrejected: ${error.message}`);
  }
}

main();

module.exports = { gradient, describeGradient, toHex };

