const GREEN_DURATION = 30;
const RED_DURATION = 30;
const CYCLE_LENGTH = GREEN_DURATION + RED_DURATION;
const PASS_INTERVAL = 2;

function isGreen(time) {
  const phase = time % CYCLE_LENGTH;
  return phase < GREEN_DURATION;
}

function nextGreenStart(time) {
  const cyclesElapsed = Math.floor(time / CYCLE_LENGTH);
  return (cyclesElapsed + 1) * CYCLE_LENGTH;
}

function normalizeEvents(events) {
  if (!Array.isArray(events)) {
    throw new TypeError('events must be an array of arrival times');
  }
  const arrivals = events.slice();
  for (const arrival of arrivals) {
    if (!Number.isInteger(arrival) || arrival < 0) {
      throw new RangeError(`invalid arrival time: ${arrival}`);
    }
  }
  arrivals.sort((a, b) => a - b);
  return arrivals;
}

function traffic(events) {
  const arrivals = normalizeEvents(events);
  const departures = [];
  let lastDeparture = -PASS_INTERVAL;
  for (const arrival of arrivals) {
    let ready = Math.max(arrival, lastDeparture);
    if (!isGreen(ready)) {
      ready = nextGreenStart(ready);
    }
    const departure = Math.max(ready, lastDeparture + PASS_INTERVAL);
    departures.push(departure);
    lastDeparture = departure;
  }
  return departures;
}

function formatClock(time) {
  const minutes = Math.floor(time / 60);
  const seconds = time % 60;
  return `${minutes}:${String(seconds).padStart(2, '0')}`;
}

function formatReport(events, departures) {
  const arrivals = normalizeEvents(events);
  if (arrivals.length === 0) {
    return 'no cars';
  }
  const lines = arrivals.map((arrival, index) => {
    const departure = departures[index];
    const waited = departure - arrival;
    const cycle = Math.floor(departure / CYCLE_LENGTH) + 1;
    return `car ${index + 1}: arrived ${formatClock(arrival)}, left ${formatClock(departure)} `
      + `(waited ${waited}s, cycle ${cycle})`;
  });
  const totalWait = arrivals.reduce((sum, arrival, index) => sum + (departures[index] - arrival), 0);
  lines.push(`total wait: ${totalWait}s, last car cleared at ${formatClock(departures[departures.length - 1])}`);
  return lines.join('\n');
}

function main() {
  const sample = [28, 29, 30];
  const departures = traffic(sample);
  console.log(`input:  [${sample.join(', ')}]`);
  console.log(`output: [${departures.join(', ')}]`);
  console.log(formatReport(sample, departures));

  const rush = [0, 1, 2, 3, 25, 26, 27, 31, 45, 61, 62, 95];
  const rushDepartures = traffic(rush);
  console.log(`\ninput:  [${rush.join(', ')}]`);
  console.log(`output: [${rushDepartures.join(', ')}]`);
  console.log(formatReport(rush, rushDepartures));
}

main();

