const BASES = {
  single: 1,
  double: 2,
  triple: 3,
  homerun: 4,
  out: 0
};

const WALK = 'walk';

function normalize(event) {
  const cleaned = String(event).trim().toLowerCase();
  if (cleaned !== WALK && !Object.prototype.hasOwnProperty.call(BASES, cleaned)) {
    throw new Error(`unknown at bat outcome: ${event}`);
  }
  return cleaned;
}

function round3(value) {
  const scaled = Math.round(value * 1000);
  return scaled / 1000;
}

function tally(events) {
  let atBats = 0;
  let hits = 0;
  let bases = 0;
  for (const event of events) {
    const outcome = normalize(event);
    if (outcome === WALK) {
      continue;
    }
    atBats += 1;
    const value = BASES[outcome];
    if (value > 0) {
      hits += 1;
      bases += value;
    }
  }
  return { atBats, hits, bases };
}

function baseball(events) {
  const { atBats, hits, bases } = tally(events);
  if (atBats === 0) {
    return [0, 0];
  }
  const average = round3(hits / atBats);
  const slugging = round3(bases / atBats);
  return [average, slugging];
}

function report(events) {
  const [average, slugging] = baseball(events);
  const line = events.join(', ');
  return `${line} -> AVG ${average.toFixed(3)}, SLG ${slugging.toFixed(3)}`;
}

function main() {
  const seasons = [
    ['single', 'out', 'walk', 'homerun'],
    ['walk', 'walk', 'walk'],
    ['double', 'triple', 'out', 'out', 'single', 'walk', 'out']
  ];
  for (const season of seasons) {
    console.log(report(season));
  }
}

main();

module.exports = { baseball, report };

