const RNA_LETTERS = new Set(['A', 'U', 'G', 'C']);
const START_CODON = 'AUG';
const STOP_CODONS = new Set(['UAA', 'UAG', 'UGA']);

function transcribe(sequence) {
  const upper = sequence.toUpperCase();
  let rna = '';
  for (const base of upper) {
    rna += base === 'T' ? 'U' : base;
  }
  return rna;
}

function chunkCodons(rna) {
  const codons = [];
  for (let i = 0; i + 3 <= rna.length; i += 3) {
    codons.push(rna.slice(i, i + 3));
  }
  return codons;
}

function isValidCodon(codon) {
  if (codon.length !== 3) {
    return false;
  }
  for (const letter of codon) {
    if (!RNA_LETTERS.has(letter)) {
      return false;
    }
  }
  return true;
}

function translate(sequence) {
  if (typeof sequence !== 'string') {
    throw new TypeError('translate expects a DNA sequence string');
  }
  const rna = transcribe(sequence);
  const codons = chunkCodons(rna);
  let starts = 0;
  let stops = 0;
  for (const codon of codons) {
    if (!isValidCodon(codon)) {
      continue;
    }
    if (codon === START_CODON) {
      starts += 1;
    } else if (STOP_CODONS.has(codon)) {
      stops += 1;
    }
  }
  return [starts, stops];
}

function describe(sequence) {
  const [starts, stops] = translate(sequence);
  const leftover = transcribe(sequence).length % 3;
  const tail = leftover === 0 ? '' : ` (${leftover} trailing base(s) ignored)`;
  return `${sequence}: ${starts} start, ${stops} stop${tail}`;
}

function main() {
  const samples = ['ATGTAATAG', 'ATGGCCATTGTAATGGGCCGC', 'ATGNNNTAAAT'];
  for (const sample of samples) {
    console.log(describe(sample));
  }
}

main();

