const LOG_PATTERN = /^\[(\d{4})\] ([A-Z]+) (.*)$/;
const SEVERITIES = new Set(['ERROR', 'FATAL']);
const MIN_YEAR = 2000;
const MAX_YEAR = 2010;

function parseEntry(line) {
  const match = LOG_PATTERN.exec(line);
  if (!match) {
    return null;
  }
  const [, yearText, severity, message] = match;
  return { year: Number(yearText), severity, message };
}

function isRelevant(entry) {
  const inRange = entry.year >= MIN_YEAR && entry.year <= MAX_YEAR;
  return inRange && SEVERITIES.has(entry.severity);
}

function filter(logs) {
  const messages = [];
  for (const line of logs) {
    const entry = parseEntry(line);
    if (entry && isRelevant(entry)) {
      messages.push(entry.message);
    }
  }
  return messages;
}

function summarize(logs) {
  const counts = new Map();
  let malformed = 0;
  for (const line of logs) {
    const entry = parseEntry(line);
    if (!entry) {
      malformed += 1;
      continue;
    }
    const previous = counts.get(entry.severity) || 0;
    counts.set(entry.severity, previous + 1);
  }
  return { counts, malformed };
}

function formatReport(logs) {
  const selected = filter(logs);
  const { counts, malformed } = summarize(logs);
  const lines = [`matched ${selected.length} of ${logs.length} entries`];
  const severities = [...counts.keys()].sort();
  for (const severity of severities) {
    lines.push(`  ${severity}: ${counts.get(severity)}`);
  }
  if (malformed > 0) {
    lines.push(`  unparsable: ${malformed}`);
  }
  for (const message of selected) {
    lines.push(`  -> ${message}`);
  }
  return lines.join('\n');
}

const sampleLogs = [
  '[2004] ERROR disk full',
  '[2012] ERROR timeout',
  '[2000] FATAL kernel panic',
  '[2010] WARN temperature high',
  '[1999] FATAL power loss',
  '[2007] ERROR checksum mismatch',
  'not a log line'
];

console.log(filter(sampleLogs).join(', '));
console.log(formatReport(sampleLogs));

