const TIER_ONE_THRESHOLD = 1000;
const TIER_TWO_THRESHOLD = 5000;
const TIER_ONE_RATE = 0.05;
const TIER_TWO_RATE = 0.10;

function validateItem(item, index) {
  if (!Array.isArray(item) || item.length !== 3) {
    throw new TypeError(`item ${index} must be [name, price, quantity]`);
  }
  const [name, price, quantity] = item;
  if (typeof name !== 'string' || name.length === 0) {
    throw new TypeError(`item ${index} has an invalid name`);
  }
  if (!Number.isInteger(price) || price < 0) {
    throw new TypeError(`item ${index} (${name}) has an invalid price`);
  }
  if (!Number.isInteger(quantity) || quantity < 0) {
    throw new TypeError(`item ${index} (${name}) has an invalid quantity`);
  }
  return { name, price, quantity };
}

function subtotal(items) {
  let sum = 0;
  items.forEach((item, index) => {
    const entry = validateItem(item, index);
    sum += entry.price * entry.quantity;
  });
  return sum;
}

function discountFor(amount) {
  const tierOnePortion = Math.max(0, Math.min(amount, TIER_TWO_THRESHOLD) - TIER_ONE_THRESHOLD);
  const tierTwoPortion = Math.max(0, amount - TIER_TWO_THRESHOLD);
  const upperTierBase = tierOnePortion + tierTwoPortion;
  return upperTierBase * TIER_ONE_RATE + tierTwoPortion * TIER_TWO_RATE;
}

function checkout(items) {
  if (!Array.isArray(items)) {
    throw new TypeError('items must be a list of lists');
  }
  const gross = subtotal(items);
  const discount = discountFor(gross);
  return Math.floor(gross - discount);
}

function formatCents(cents) {
  const dollars = Math.floor(cents / 100);
  const remainder = String(cents % 100).padStart(2, '0');
  return `$${dollars}.${remainder}`;
}

function receipt(items) {
  const lines = items.map(([name, price, quantity]) => {
    const lineTotal = price * quantity;
    return `${quantity} x ${name} @ ${formatCents(price)} = ${formatCents(lineTotal)}`;
  });
  const gross = subtotal(items);
  const net = checkout(items);
  lines.push(`Subtotal: ${formatCents(gross)}`);
  lines.push(`Discount: ${formatCents(gross - net)}`);
  lines.push(`Total: ${formatCents(net)}`);
  return lines.join('\n');
}

function main() {
  const basket = [['book', 1000, 3], ['pen', 250, 8], ['lamp', 4500, 1]];
  console.log(receipt(basket));
  const single = [['book', 1000, 3]];
  console.log(checkout(single));
}

main();

module.exports = { checkout, receipt, formatCents };

