function validateReadings(temperatures) {
  if (!Array.isArray(temperatures)) {
    throw new TypeError('temperatures must be an array of integers');
  }
  const cleaned = [];
  for (const reading of temperatures) {
    if (typeof reading !== 'number' || !Number.isInteger(reading)) {
      throw new TypeError(`invalid temperature reading: ${String(reading)}`);
    }
    cleaned.push(reading);
  }
  return cleaned;
}

function findWarmingStreaks(readings) {
  const streaks = [];
  let start = 0;
  for (let day = 1; day < readings.length; day += 1) {
    if (readings[day] <= readings[day - 1]) {
      if (day - start > 1) {
        streaks.push({ start, end: day - 1 });
      }
      start = day;
    }
  }
  const lastDay = readings.length - 1;
  if (lastDay > start) {
    streaks.push({ start, end: lastDay });
