const SIZE = 9;
const BOX = 3;

function hasAllDigits(values) {
  if (values.length !== SIZE) {
    return false;
  }
  const seen = new Set();
  for (const value of values) {
    if (!Number.isInteger(value) || value < 1 || value > SIZE) {
      return false;
    }
    if (seen.has(value)) {
      return false;
    }
    seen.add(value);
  }
  return true;
}

function getColumn(grid, index) {
  const column = [];
  for (let row = 0; row < SIZE; row += 1) {
    column.push(grid[row][index]);
  }
  return column;
}

function getSubgrid(grid, boxRow, boxCol) {
  const cells = [];
  const startRow = boxRow * BOX;
  const startCol = boxCol * BOX;
  for (let row = startRow; row < startRow + BOX; row += 1) {
    for (let col = startCol; col < startCol + BOX; col += 1) {
      cells.push(grid[row][col]);
    }
  }
  return cells;
}

function validate(grid) {
  if (!Array.isArray(grid) || grid.length !== SIZE) {
    return false;
  }
  for (const row of grid) {
    if (!Array.isArray(row) || !hasAllDigits(row)) {
      return false;
    }
  }
  for (let col = 0; col < SIZE; col += 1) {
    if (!hasAllDigits(getColumn(grid, col))) {
      return false;
    }
  }
  for (let boxRow = 0; boxRow < BOX; boxRow += 1) {
    for (let boxCol = 0; boxCol < BOX; boxCol += 1) {
      if (!hasAllDigits(getSubgrid(grid, boxRow, boxCol))) {
        return false;
      }
    }
  }
  return true;
}

function report(label, grid) {
  const verdict = validate(grid) ? 'valid' : 'invalid';
  return `${label}: ${verdict}`;
}

