function spans(prices) {
  if (!Array.isArray(prices)) {
    throw new TypeError('spans() expects an array of prices');
  }
  const result = [];
  const stack = [];
  for (let day = 0; day < prices.length; day += 1) {
    const price = prices[day];
    if (!Number.isInteger(price)) {
      throw new TypeError(`price at index ${day} is not an integer: ${price}`);
    }
    while (stack.length > 0 && prices[stack[stack.length - 1]] <= price) {
      stack.pop();
    }
    const previousGreaterDay = stack.length === 0 ? -1 : stack[stack.length - 1];
    result.push(day - previousGreaterDay);
    stack.push(day);
  }
  return result;
}

function parsePrices(text) {
  const tokens = text.split(/[\s,]+/).filter((token) => token.length > 0);
  return tokens.map((token) => {
    const value = Number(token);
    if (!Number.isInteger(value)) {
      throw new TypeError(`cannot read "${token}" as an integer price`);
    }
    return value;
  });
}

function longestSpan(prices) {
  const values = spans(prices);
  let bestDay = 0;
  for (let day = 1; day < values.length; day += 1) {
    if (values[day] > values[bestDay]) {
      bestDay = day;
    }
  }
  return { day: bestDay, span: values[bestDay] };
}

function formatReport(prices) {
  const values = spans(prices);
  const width = String(prices.length).length;
  const lines = ['day  price  span'];
  for (let day = 0; day < prices.length; day += 1) {
    const label = String(day + 1).padStart(width + 2);
    const price = String(prices[day]).padStart(6);
    const span = String(values[day]).padStart(5);
    lines.push(`${label}${price}${span}`);
  }
  const peak = longestSpan(prices);
  lines.push(`longest span: ${peak.span} day(s), ending on day ${peak.day + 1}`);
  return lines.join('\n');
}

function main(argv) {
  const args = argv.slice(2);
  const source = args.length > 0 ? args.join(' ') : '100 80 60 70 60 75 85';
  const prices = parsePrices(source);
  console.log(formatReport(prices));
  console.log(`spans: [${spans(prices).join(', ')}]`);
}

main(process.argv);

module.exports = { spans, parsePrices, longestSpan, formatReport };

