function editDistance(a, b) {
  const rows = a.length + 1;
  const cols = b.length + 1;
  let previous = new Array(cols);
  for (let j = 0; j < cols; j += 1) {
    previous[j] = j;
  }
  for (let i = 1; i < rows; i += 1) {
    const current = new Array(cols);
    current[0] = i;
    for (let j = 1; j < cols; j += 1) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      const substitution = previous[j - 1] + cost;
      const deletion = previous[j] + 1;
      const insertion = current[j - 1] + 1;
      current[j] = Math.min(substitution, deletion, insertion);
    }
    previous = current;
  }
  return previous[cols - 1];
}

function suggest(word, dictionary) {
  if (!Array.isArray(dictionary) || dictionary.length === 0) {
    return null;
  }
  let best = dictionary[0];
  let bestDistance = editDistance(word, best);
  for (let i = 1; i < dictionary.length; i += 1) {
    const candidate = dictionary[i];
    const distance = editDistance(word, candidate);
    if (distance < bestDistance) {
      best = candidate;
      bestDistance = distance;
    }
  }
  return best;
}

function rankCandidates(word, dictionary) {
  const scored = dictionary.map((term) => ({ term, distance: editDistance(word, term) }));
  return scored.sort((left, right) => left.distance - right.distance);
}

function formatReport(word, dictionary) {
  const choice = suggest(word, dictionary);
  if (choice === null) {
    return `${word}: no candidates available`;
  }
  const ranking = rankCandidates(word, dictionary);
  const details = ranking.map(({ term, distance }) => `${term}(${distance})`).join(', ');
  return `${word} -> ${choice} [${details}]`;
}

function main() {
  const dictionary = ['sitting', 'mitten', 'fitting'];
  const queries = ['kitten', 'sittin', 'fitten'];
  for (const query of queries) {
    console.log(formatReport(query, dictionary));
  }
  const empty = suggest('kitten', []);
  console.log(`empty dictionary result: ${empty}`);
}

main();

module.exports = { suggest, editDistance, rankCandidates, formatReport };

