function validateKernel(kernel) {
  const rows = kernel.length;
  if (rows !== 3) {
    throw new Error(`kernel must have 3 rows, got ${rows}`);
  }
  for (const row of kernel) {
    if (row.length !== 3) {
      throw new Error(`every kernel row must have 3 columns, got ${row.length}`);
    }
  }
}

function validateImage(image) {
  const height = image.length;
  if (height === 0) {
    throw new Error('image must contain at least one row');
  }
  const width = image[0].length;
  for (const row of image) {
    if (row.length !== width) {
      throw new Error('image rows must all have the same length');
    }
  }
  return { height, width };
}

function sampleAt(image, y, x) {
  if (y < 0 || y >= image.length || x < 0 || x >= image[y].length) {
    return 0;
  }
  return image[y][x];
}

function apply(image, kernel) {
  validateKernel(kernel);
  const { height, width } = validateImage(image);
  const radius = 1;
  const output = [];
  for (let y = 0; y < height; y += 1) {
    const line = [];
    for (let x = 0; x < width; x += 1) {
      let total = 0;
      for (let ky = -radius; ky <= radius; ky += 1) {
        for (let kx = -radius; kx <= radius; kx += 1) {
          const weight = kernel[ky + radius][kx + radius];
          total += weight * sampleAt(image, y + ky, x + kx);
        }
      }
      line.push(total);
    }
    output.push(line);
  }
  return output;
}

function formatImage(image) {
  let widest = 1;
  for (const row of image) {
    for (const value of row) {
      widest = Math.max(widest, String(value).length);
    }
  }
  const lines = image.map((row) => row.map((value) => String(value).padStart(widest)).join(' '));
  return lines.join('\n');
}

const pointImage = [
  [0, 0, 0],
  [0, 10, 0],
  [0, 0, 0],
];
const boxKernel = [
  [1, 1, 1],
  [1, 1, 1],
  [1, 1, 1],
];
const sharpenKernel = [
  [0, -1, 0],
  [-1, 5, -1],
  [0, -1, 0],
];

console.log('box blur of a single point:');
console.log(formatImage(apply(pointImage, boxKernel)));
const gradient = [
  [10, 20, 30, 40],
  [20, 30, 40, 50],
  [30, 40, 50, 60],
];
console.log('sharpened gradient:');
console.log(formatImage(apply(gradient, sharpenKernel)));

