const LEVELS = 256;
const MAX_INTENSITY = LEVELS - 1;

function histogram(pixels) {
  const counts = new Array(LEVELS).fill(0);
  for (const value of pixels) {
    counts[value] += 1;
  }
  return counts;
}

function cumulative(counts) {
  const sums = new Array(LEVELS).fill(0);
  let running = 0;
  for (let level = 0; level < LEVELS; level += 1) {
    running += counts[level];
    sums[level] = running;
  }
  return sums;
}

function buildLookup(pixels) {
  const counts = histogram(pixels);
  const cdf = cumulative(counts);
  let firstNonZero = 0;
  while (firstNonZero < LEVELS && cdf[firstNonZero] === 0) {
    firstNonZero += 1;
  }
  const floor = cdf[firstNonZero];
  const span = pixels.length - floor;
  const lookup = new Array(LEVELS).fill(0);
  for (let level = firstNonZero; level < LEVELS; level += 1) {
    if (span === 0) {
      lookup[level] = level;
    } else {
      const scaled = ((cdf[level] - floor) / span) * MAX_INTENSITY;
