var LEVELS = 256;
var MAX_INTENSITY = LEVELS - 1;

function histogram(pixels) {
  var counts = new Array(LEVELS).fill(0);
  for (var value of pixels) {
    counts[value] += 1;
  }
  return counts;
}

function cumulative(counts) {
  var sums = new Array(LEVELS).fill(0);
  var running = 0;
  for (var level = 0; level < LEVELS; level += 1) {
    running += counts[level];
    sums[level] = running;
  }
  return sums;
}

function buildLookup(pixels) {
  var counts = histogram(pixels);
  var cdf = cumulative(counts);
  var firstNonZero = 0;
  while (firstNonZero < LEVELS && cdf[firstNonZero] === 0) {
    firstNonZero += 1;
  }
  var floor = cdf[firstNonZero];
  var span = pixels.length - floor;
  var lookup = new Array(LEVELS).fill(0);
  for (var level = firstNonZero; level < LEVELS; level += 1) {
    if (span === 0) {
      lookup[level] = level;
    } else {
      var scaled = ((cdf[level] - floor) / span) * MAX_INTENSITY;
      lookup[level] = Math.round(scaled);
    }
  }
  return lookup;
}

