function countLiveNeighbours(grid, row, col) {
  const height = grid.length;
  const width = grid[0].length;
  let total = 0;
  for (let dr = -1; dr <= 1; dr += 1) {
    for (let dc = -1; dc <= 1; dc += 1) {
      if (dr === 0 && dc === 0) continue;
      const r = row + dr;
      const c = col + dc;
      if (r >= 0 && r < height && c >= 0 && c < width) {
        total += grid[r][c];
      }
    }
  }
  return total;
}

function nextGeneration(grid) {
  const width = grid[0].length;
  return grid.map((rowCells, row) => {
    const nextRow = new Array(width);
    for (let col = 0; col < width; col += 1) {
      const neighbours = countLiveNeighbours(grid, row, col);
      const alive = rowCells[col] === 1;
      nextRow[col] = (alive && (neighbours === 2 || neighbours === 3)) || (!alive && neighbours === 3) ? 1 : 0;
    }
    return nextRow;
  });
}

function validateGrid(grid) {
  if (!Array.isArray(grid) || grid.length === 0 || !Array.isArray(grid[0])) {
    throw new TypeError('grid must be a non-empty list of lists');
  }
  const width = grid[0].length;
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== width) {
      throw new TypeError('all grid rows must have the same length');
    }
    for (const cell of row) {
      if (cell !== 0 && cell !== 1) {
        throw new RangeError('cells must be 0 or 1');
      }
    }
  }
}

function evolve(grid, steps) {
  validateGrid(grid);
  if (!Number.isInteger(steps) || steps < 0) {
    throw new RangeError('steps must be a non-negative integer');
  }
  let current = grid.map((row) => row.slice());
  for (let generation = 0; generation < steps; generation += 1) {
    current = nextGeneration(current);
  }
  return current;
}

function renderGrid(grid) {
  return grid.map((row) => row.map((cell) => (cell === 1 ? '#' : '.')).join('')).join('\n');
}

const blinker = [
  [0, 0, 0],
  [1, 1, 1],
  [0, 0, 0],
];

for (let step = 0; step <= 2; step += 1) {
  const state = evolve(blinker, step);
  console.log(`Generation ${step}:`);
  console.log(renderGrid(state));
  console.log('');
}

