const BASE = 256;
const MODULUS = 1000003;

function charValue(char) {
  return char.charCodeAt(0);
}

function computeHash(str, length) {
  let hash = 0;
  for (let i = 0; i < length; i += 1) {
    hash = (hash * BASE + charValue(str[i])) % MODULUS;
  }
  return hash;
}

function highestPower(length) {
  let power = 1;
  for (let i = 1; i < length; i += 1) {
    power = (power * BASE) % MODULUS;
  }
  return power;
}

function matchesAt(text, pattern, start) {
  const m = pattern.length;
  for (let i = 0; i < m; i += 1) {
    if (text[start + i] !== pattern[i]) {
      return false;
    }
  }
  return true;
}

function search(text, pattern) {
  if (typeof text !== 'string' || typeof pattern !== 'string') {
    throw new TypeError('search expects two strings');
  }

  const matches = [];
  const m = pattern.length;
  const n = text.length;
  if (m === 0 || m > n) {
    return matches;
  }

  const patternHash = computeHash(pattern, m);
  const leadFactor = highestPower(m);
  let windowHash = computeHash(text, m);
  const lastStart = n - m;

  for (let start = 0; start <= lastStart; start += 1) {
    if (windowHash === patternHash && matchesAt(text, pattern, start)) {
      matches.push(start);
    }
    if (start < lastStart) {
      const leaving = (charValue(text[start]) * leadFactor) % MODULUS;
      const entering = charValue(text[start + m]);
      const shrunk = (windowHash - leaving + MODULUS) % MODULUS;
      windowHash = (shrunk * BASE + entering) % MODULUS;
    }
  }

  return matches;
}

module.exports = { search };

