const BRANCH_ANGLE = Math.PI / 6;
const SCALE_FACTOR = 0.7;
const TRUNK_LENGTH = 1.0;

function generate(iterations) {
  const count = Number(iterations);
  if (!Number.isInteger(count) || count < 0) {
    throw new RangeError('iterations must be a non-negative integer');
  }

  const trunk = [0.0, 0.0, 0.0, TRUNK_LENGTH];
  const segments = [trunk];
  let frontier = [{ x: trunk[2], y: trunk[3], angle: Math.PI / 2, length: TRUNK_LENGTH }];

  for (let step = 0; step < count; step += 1) {
    const nextFrontier = [];
    for (const tip of frontier) {
      const length = tip.length * SCALE_FACTOR;
      for (const turn of [BRANCH_ANGLE, -BRANCH_ANGLE]) {
        const angle = tip.angle + turn;
        const endX = tip.x + length * Math.cos(angle);
        const endY = tip.y + length * Math.sin(angle);
        segments.push([tip.x, tip.y, endX, endY]);
        nextFrontier.push({ x: endX, y: endY, angle, length });
      }
    }
    frontier = nextFrontier;
  }

  return segments;
}

function boundingBox(segments) {
  let minX = Infinity;
  let maxX = -Infinity;
  let minY = Infinity;
  let maxY = -Infinity;

  for (const [x1, y1, x2, y2] of segments) {
    minX = Math.min(minX, x1, x2);
    maxX = Math.max(maxX, x1, x2);
    minY = Math.min(minY, y1, y2);
    maxY = Math.max(maxY, y1, y2);
  }

  return { minX, maxX, minY, maxY };
}

function formatSegment(segment) {
  return segment.map((value) => value.toFixed(4)).join(', ');
}

function report(iterations) {
  const segments = generate(iterations);
  const box = boundingBox(segments);
  const lines = [`iterations=${iterations} segments=${segments.length}`];
  const width = box.maxX - box.minX;
  const height = box.maxY - box.minY;

  lines.push(`extent: width=${width.toFixed(4)} height=${height.toFixed(4)}`);
  for (const segment of segments) {
    lines.push(`  [${formatSegment(segment)}]`);
  }

  return lines.join('\n');
}

console.log(report(0));
console.log(report(2));

module.exports = { generate, boundingBox, report };

