function isPowerOfTwo(n) {
  return n > 0 && (n & (n - 1)) === 0;
}

function validateImage(image) {
  if (!Array.isArray(image) || image.length === 0) {
    throw new TypeError('image must be a non-empty array of rows');
  }
  const size = image.length;
  if (!isPowerOfTwo(size)) {
    throw new RangeError(`image side ${size} is not a power of two`);
  }
  for (const row of image) {
    if (!Array.isArray(row) || row.length !== size) {
      throw new RangeError('image must be square');
    }
    for (const pixel of row) {
      if (!Number.isInteger(pixel)) {
        throw new TypeError(`pixel ${pixel} is not an integer`);
      }
    }
  }
  return size;
}

function isUniform(image, top, left, size) {
  const first = image[top][left];
  for (let y = top; y < top + size; y += 1) {
    const row = image[y];
    for (let x = left; x < left + size; x += 1) {
      if (row[x] !== first) {
        return false;
      }
    }
  }
  return true;
}

function compressRegion(image, top, left, size) {
  if (isUniform(image, top, left, size)) {
    return [image[top][left]];
  }
  const half = size / 2;
  const midY = top + half;
  const midX = left + half;
  return [
    compressRegion(image, top, left, half),
    compressRegion(image, top, midX, half),
    compressRegion(image, midY, left, half),
    compressRegion(image, midY, midX, half),
  ];
}

function compress(image) {
  const size = validateImage(image);
  return compressRegion(image, 0, 0, size);
}

function countLeaves(region) {
  if (region.length === 1) {
    return 1;
  }
  let total = 0;
  for (const child of region) {
    total += countLeaves(child);
  }
  return total;
}

function report(name, image) {
  const tree = compress(image);
  const leaves = countLeaves(tree);
  const pixels = image.length * image.length;
  console.log(`${name}: ${JSON.stringify(tree)} (${leaves} regions for ${pixels} pixels)`);
}

const flat = [
  [1, 1],
  [1, 1],
];
const mixed = [
  [0, 0, 1, 1],
  [0, 0, 1, 2],
  [3, 3, 4, 4],
  [3, 3, 4, 4],
];
report('flat 2x2', flat);
report('mixed 4x4', mixed);

