function validateMatrix(rates) {
  if (!Array.isArray(rates) || rates.length === 0) {
    throw new TypeError('rates must be a non-empty matrix');
  }
  const size = rates.length;
  for (let i = 0; i < size; i += 1) {
    const row = rates[i];
    if (!Array.isArray(row) || row.length !== size) {
      throw new TypeError(`row ${i} must have exactly ${size} entries`);
    }
    for (const value of row) {
      if (typeof value !== 'number' || !Number.isFinite(value) || value <= 0) {
        throw new RangeError(`rate ${value} in row ${i} is not a positive number`);
      }
    }
  }
  return size;
}

function cycleProduct(rates, a, b, c) {
  return rates[a][b] * rates[b][c] * rates[c][a];
}

function detect(rates) {
  const size = validateMatrix(rates);
  for (let a = 0; a < size; a += 1) {
    for (let b = 0; b < size; b += 1) {
      if (b === a) continue;
      for (let c = 0; c < size; c += 1) {
        if (c === a || c === b) continue;
        const product = cycleProduct(rates, a, b, c);
        if (product > 1) {
          return [a, b, c];
        }
      }
    }
  }
  return [];
}

function describe(rates, names) {
  const cycle = detect(rates);
  if (cycle.length === 0) {
    return 'no arbitrage opportunity';
  }
  const [a, b, c] = cycle;
  const labels = cycle.map((index) => names[index] ?? `#${index}`);
  const gain = (cycleProduct(rates, a, b, c) - 1) * 100;
  const path = [...labels, labels[0]].join(' -> ');
  return `${path}: ${gain.toFixed(2)}% profit (indices ${cycle.join(', ')})`;
}

const currencies = ['USD', 'EUR', 'GBP', 'JPY'];
const balancedMarket = [
  [1, 0.9, 0.8, 140],
  [1 / 0.9, 1, 0.888888888888889, 155.555555555556],
  [1.25, 1.125, 1, 175],
  [1 / 140, 1 / 155.555555555556, 1 / 175, 1],
];
const skewedMarket = balancedMarket.map((row) => row.slice());
skewedMarket[0][1] = 0.945;

for (const [title, market] of [['balanced', balancedMarket], ['skewed', skewedMarket]]) {
  console.log(`${title}: ${describe(market, currencies)}`);
}

module.exports = { detect, describe, cycleProduct, validateMatrix };

