function buildGraph(flights) {
  const graph = new Map();
  for (const [origin, target, price] of flights) {
    if (!graph.has(origin)) {
      graph.set(origin, []);
    }
    const departures = graph.get(origin);
    departures.push({ target, price });
  }
  return graph;
}

function validate(flights, source, destination, limit) {
  const problems = [];
  if (!Array.isArray(flights)) {
    problems.push("flights must be a list of [origin, destination, price] entries");
  } else {
    flights.forEach((flight, index) => {
      const isTriple = Array.isArray(flight) && flight.length === 3;
      if (!isTriple || flight.some((value) => !Number.isInteger(value))) {
        problems.push(`flight ${index} must hold three integers`);
      }
    });
  }
  if (!Number.isInteger(source) || !Number.isInteger(destination)) {
    problems.push("source and destination must be integers");
  }
  if (!Number.isInteger(limit) || limit < 0) {
    problems.push("limit must be a non-negative integer");
  }
  return problems;
}

function route(flights, source, destination, limit) {
  const problems = validate(flights, source, destination, limit);
  if (problems.length > 0) {
    throw new TypeError(problems.join("; "));
  }
  if (source === destination) {
    return 0;
  }
  const graph = buildGraph(flights);
  const cheapest = new Map([[source, 0]]);
  let frontier = [{ city: source, cost: 0 }];
  let best = -1;
  for (let hop = 0; hop <= limit && frontier.length > 0; hop += 1) {
    const nextFrontier = [];
    for (const { city, cost } of frontier) {
      const departures = graph.get(city) || [];
      for (const { target, price } of departures) {
        const total = cost + price;
        if (target === destination) {
          if (best === -1 || total < best) {
            best = total;
          }
          continue;
        }
        const known = cheapest.get(target);
        if (known === undefined || total < known) {
          cheapest.set(target, total);
          nextFrontier.push({ city: target, cost: total });
        }
      }
    }
    frontier = nextFrontier;
  }
  return best;
}

function describe(flights, source, destination, limit) {
  const price = route(flights, source, destination, limit);
  const verdict = price === -1 ? "no route" : `${price}`;
  return `${source} -> ${destination} with up to ${limit} stops: ${verdict}`;
}

function main() {
  const network = [[0, 1, 100], [1, 2, 100], [0, 2, 500]];
  const twoLeggedBargain = [[0, 1, 50], [1, 3, 0], [0, 3, 100]];
  const reports = [
    describe(network, 0, 2, 1),
    describe(network, 0, 2, 0),
    describe(twoLeggedBargain, 0, 3, 0),
    describe(network, 2, 0, 3),
  ];
  for (const line of reports) {
    console.log(line);
  }
}

main();

module.exports = { route, buildGraph, describe };

