function radiusAt(text, left, right) {
  let l = left;
  let r = right;
  while (l >= 0 && r < text.length && text[l] === text[r]) {
    l -= 1;
    r += 1;
  }
  return { start: l + 1, length: r - l - 1 };
}

function expand(text) {
  if (typeof text !== 'string') {
    throw new TypeError('expand expects a string');
  }
  let bestStart = 0;
  let bestLength = text.length > 0 ? 1 : 0;
  for (let center = 0; center < text.length; center += 1) {
    const odd = radiusAt(text, center, center);
    if (odd.length > bestLength) {
      bestStart = odd.start;
      bestLength = odd.length;
    }
    const even = radiusAt(text, center, center + 1);
    if (even.length > bestLength) {
      bestStart = even.start;
      bestLength = even.length;
    }
  }
  return text.slice(bestStart, bestStart + bestLength);
}

function normalize(raw) {
  const lowered = raw.toLowerCase();
  const letters = lowered.replace(/[^a-z]/g, '');
  return letters;
}

function report(raw) {
  const cleaned = normalize(raw);
  const longest = expand(cleaned);
  const ratio = cleaned.length === 0 ? 0 : longest.length / cleaned.length;
  const percent = (ratio * 100).toFixed(1);
  return `${raw} -> ${longest} (${longest.length} chars, ${percent}% of input)`;
}

function main() {
  const samples = ['racecar', 'abababaa', 'Never odd or even', 'forgetfulness', 'aabbaabb', ''];
  const lines = samples.map(report);
  for (const line of lines) {
    console.log(line);
  }
  const widest = samples.reduce((best, candidate) => {
    const bestRun = expand(normalize(best));
    const candidateRun = expand(normalize(candidate));
    return candidateRun.length > bestRun.length ? candidate : best;
  }, samples[0]);
  console.log(`widest palindrome comes from: ${widest}`);
}

main();

module.exports = { expand, normalize, report };

