const DIGIT_LETTERS = {
  '2': 'abc',
  '3': 'def',
  '4': 'ghi',
  '5': 'jkl',
  '6': 'mno',
  '7': 'pqrs',
  '8': 'tuv',
  '9': 'wxyz'
};

function validateDigits(digits) {
  if (typeof digits !== 'string') {
    throw new TypeError('digits must be a string');
  }
  const bad = [...digits].filter((ch) => !(ch in DIGIT_LETTERS));
  if (bad.length > 0) {
    const listed = bad.join(', ');
    throw new RangeError(`unsupported keypad digits: ${listed}`);
  }
  return digits;
}

function combinations(digits) {
  validateDigits(digits);
  if (digits.length === 0) {
    return [];
  }
  const results = [];
  const current = [];
  const backtrack = (index) => {
    if (index === digits.length) {
      results.push(current.join(''));
      return;
    }
    const letters = DIGIT_LETTERS[digits[index]];
    for (const letter of letters) {
      current.push(letter);
      backtrack(index + 1);
      current.pop();
    }
  };
  backtrack(0);
  return results;
}

function combinationsIterative(digits) {
  validateDigits(digits);
  let prefixes = digits.length === 0 ? [] : [''];
  for (const digit of digits) {
    const letters = DIGIT_LETTERS[digit];
    const expanded = [];
    for (const prefix of prefixes) {
      for (const letter of letters) {
        expanded.push(prefix + letter);
      }
    }
    prefixes = expanded;
  }
  return prefixes;
}

function report(digits) {
  const words = combinations(digits);
  const iterative = combinationsIterative(digits);
  const agree = words.length === iterative.length &&
    words.every((word, i) => word === iterative[i]);
  const preview = words.slice(0, 8).join(' ');
  const suffix = words.length > 8 ? ' ...' : '';
  return `${digits || '(empty)'} -> ${words.length} messages [${preview}${suffix}] consistent=${agree}`;
}

for (const sample of ['23', '7', '456', '']) {
  console.log(report(sample));
}

try {
  combinations('12');
} catch (err) {
  console.log(`rejected: ${err.message}`);
}

