const TEASPOON_ALIASES = ['tsp', 'teaspoon', 'teaspoons'];
const TABLESPOON_ALIASES = ['tbsp', 'tablespoon', 'tablespoons'];

function normalizeUnit(unit) {
  const key = String(unit).trim().toLowerCase();
  if (TEASPOON_ALIASES.includes(key)) return 'tsp';
  if (TABLESPOON_ALIASES.includes(key)) return 'tbsp';
  return key;
}

function convertUpwards(quantity, unit) {
  let amount = quantity;
  let measure = normalizeUnit(unit);
  if (measure === 'tsp' && amount >= 3) {
    amount = amount / 3;
    measure = 'tbsp';
  }
  if (measure === 'tbsp' && amount >= 4) {
    amount = amount / 4;
    measure = 'cup';
  }
  return [amount, measure];
}

function formatQuantity(quantity) {
  const rounded = Math.round(quantity * 100) / 100;
  return String(rounded);
}

function scale(recipe, factor) {
  let originalTotal = 0;
  let scaledTotal = 0;
  const lines = [];
  for (const entry of recipe) {
    const [name, quantity, unit] = entry;
    if (typeof quantity !== 'number' || Number.isNaN(quantity)) {
      throw new TypeError(`quantity for "${name}" must be a number`);
    }
    const [amount, measure] = convertUpwards(quantity * factor, unit);
    originalTotal += quantity;
    scaledTotal += amount;
    lines.push(`${formatQuantity(amount)} ${measure} ${name}`);
  }
  return [originalTotal, scaledTotal, ...lines];
}

function report(recipe, factor) {
  const scaled = scale(recipe, factor);
  const [originalTotal, scaledTotal] = scaled;
  const ingredients = scaled.slice(2);
  const header = `Recipe scaled by ${factor} (totals: ${formatQuantity(originalTotal)} -> ${formatQuantity(scaledTotal)})`;
  const body = ingredients.map((line) => `  - ${line}`).join('\n');
  return `${header}\n${body}`;
}

const pancakes = [
  ['flour', 2, 'cup'],
  ['baking powder', 1.5, 'tsp'],
  ['salt', 0.5, 'tsp'],
  ['sugar', 1, 'tbsp'],
  ['milk', 1.25, 'cup'],
  ['butter', 3, 'tbsp'],
];

console.log(report(pancakes, 1));
console.log(report(pancakes, 2));
console.log(report(pancakes, 6));

module.exports = { scale, report, convertUpwards, formatQuantity };

