const STARTING_SCORE = 501;
const THROWS_PER_TURN = 3;
const MAX_THROW = 60;

function validateTurn(turn, index) {
  if (!Array.isArray(turn)) {
    throw new TypeError(`turn ${index} is not an array`);
  }
  if (turn.length !== THROWS_PER_TURN) {
    throw new RangeError(`turn ${index} must contain ${THROWS_PER_TURN} throws`);
  }
  for (const value of turn) {
    const isWholeNumber = Number.isInteger(value);
    if (!isWholeNumber || value < 0 || value > MAX_THROW) {
      throw new RangeError(`turn ${index} contains an illegal throw: ${value}`);
    }
  }
}

function turnTotal(turn) {
  let sum = 0;
  for (const value of turn) {
    sum += value;
  }
  return sum;
}

function isBust(remaining, lastThrow) {
  if (remaining < 0 || remaining === 1) {
    return true;
  }
  return remaining === 0 && lastThrow % 2 !== 0;
}

function playTurn(total, turn) {
  const remaining = total - turnTotal(turn);
  const lastThrow = turn[turn.length - 1];
  return isBust(remaining, lastThrow) ? total : remaining;
}

function score(throws) {
  if (!Array.isArray(throws)) {
    throw new TypeError('throws must be an array of turns');
  }
  let total = STARTING_SCORE;
  throws.forEach((turn, index) => {
    validateTurn(turn, index);
    total = playTurn(total, turn);
  });
  return total;
}

function describeGame(throws) {
  const lines = [];
  let total = STARTING_SCORE;
  throws.forEach((turn, index) => {
    validateTurn(turn, index);
    const after = playTurn(total, turn);
    const outcome = after === total ? 'bust' : `${after} left`;
    lines.push(`turn ${index + 1}: ${turn.join(' + ')} -> ${outcome}`);
    total = after;
  });
  lines.push(`final score: ${total}`);
  return lines.join('\n');
}

function main() {
  const game = [
    [60, 60, 60],
    [60, 60, 60],
    [20, 20, 20],
    [60, 20, 1],
    [30, 30, 20],
    [1, 20, 20],
  ];
  console.log(describeGame(game));
  const finalScore = score(game);
  console.log(`score(throws) === ${finalScore}`);
}

main();

module.exports = { score, describeGame };

