function score(throws) {
  if (!Array.isArray(throws)) {
    throw new TypeError('throws must be an array of turns');
  }
  var total = STARTING_SCORE;
  throws.forEach((turn, index) => {
    validateTurn(turn, index);
    total = playTurn(total, turn);
  });
  return total;
}

function describeGame(throws) {
  var lines = [];
  var total = STARTING_SCORE;
  throws.forEach((turn, index) => {
    validateTurn(turn, index);
    var after = playTurn(total, turn);
    var outcome = after === total ? 'bust' : `${after} left`;
    lines.push(`turn ${index + 1}: ${turn.join(' + ')} -> ${outcome}`);
    total = after;
  });
  lines.push(`final score: ${total}`);
  return lines.join('\n');
}

function main() {
  var game = [
    [60, 60, 60],
    [60, 60, 60],
    [20, 20, 20],
    [60, 20, 1],
    [30, 30, 20],
    [1, 20, 20],
  ];
  console.log(describeGame(game));
  var finalScore = score(game);
  console.log(`score(throws) === ${finalScore}`);
}

main();

module.exports = { score, describeGame };

