const EXPECTED_FIELDS = 5;

function validateBall(ball, index) {
  if (!Array.isArray(ball) || ball.length !== EXPECTED_FIELDS) {
    throw new TypeError(`ball ${index} must be an array of ${EXPECTED_FIELDS} numbers`);
  }
  for (const value of ball) {
    if (typeof value !== 'number' || !Number.isFinite(value)) {
      throw new TypeError(`ball ${index} contains a non-finite value`);
    }
  }
  const radius = ball[4];
  if (radius < 0) {
    throw new RangeError(`ball ${index} has a negative radius`);
  }
}

function quadraticCoefficients(first, second) {
  const [x1, y1, vx1, vy1, r1] = first;
  const [x2, y2, vx2, vy2, r2] = second;
  const dx = x2 - x1;
  const dy = y2 - y1;
  const dvx = vx2 - vx1;
  const dvy = vy2 - vy1;
  const contact = r1 + r2;
  return {
    a: dvx * dvx + dvy * dvy,
    b: 2 * (dx * dvx + dy * dvy),
    c: dx * dx + dy * dy - contact * contact
  };
}

function simulate(balls) {
  if (!Array.isArray(balls) || balls.length !== 2) {
    throw new TypeError('simulate expects an array of exactly two balls');
  }
  balls.forEach(validateBall);

  const { a, b, c } = quadraticCoefficients(balls[0], balls[1]);
  if (a === 0) {
    return -1;
  }

  const discriminant = b * b - 4 * a * c;
  if (discriminant < 0) {
    return -1;
  }

  const time = (-b - Math.sqrt(discriminant)) / (2 * a);
  if (time < 0) {
    return -1;
  }
  return Math.round(time * 1000) / 1000;
}

function describeCollision(balls) {
  const time = simulate(balls);
  if (time < 0) {
    return 'no collision';
  }
  const positions = balls.map(([x, y, vx, vy]) => {
    const px = (x + vx * time).toFixed(3);
    const py = (y + vy * time).toFixed(3);
    return `(${px}, ${py})`;
  });
  return `collision at t = ${time.toFixed(3)} near ${positions.join(' and ')}`;
}

const scenarios = [
  [[0, 0, 1, 0, 1], [10, 0, -1, 0, 1]],
  [[0, 0, 1, 0, 1], [10, 5, -1, 0, 1]],
  [[0, 0, 0, 0, 2], [6, 8, -3, -4, 3]]
];

for (const scenario of scenarios) {
  console.log(describeCollision(scenario));
}

