function columnWidths(rows) {
  const widths = [];
  for (const row of rows) {
    row.forEach((cell, index) => {
      const current = widths[index] === undefined ? 0 : widths[index];
      widths[index] = Math.max(current, cell.length);
    });
  }
  return widths;
}

function padCell(cell, width) {
  const missing = width - cell.length;
  return cell + ' '.repeat(missing);
}

function formatRow(row, widths) {
  const cells = widths.map((width, index) => {
    const cell = index < row.length ? row[index] : '';
    return padCell(cell, width);
  });
  return cells.join(' | ');
}

function separatorRow(widths) {
  return widths.map((width) => '-'.repeat(width));
}

function format(rows) {
  if (rows.length === 0) {
    return '';
  }
  const widths = columnWidths(rows);
  const lines = [formatRow(rows[0], widths)];
  if (rows.length > 1) {
    lines.push(formatRow(separatorRow(widths), widths));
  }
  for (let index = 1; index < rows.length; index += 1) {
    lines.push(formatRow(rows[index], widths));
  }
  return lines.join('\n');
}

function parseTable(text) {
  const lines = text.split('\n').filter((line) => line.trim().length > 0);
  return lines.map((line) => line.split(',').map((cell) => cell.trim()));
}

function main() {
  const source = [
    'Name, Language, Year',
    'Brendan Eich, JavaScript, 1995',
    'Guido van Rossum, Python, 1991',
    'Yukihiro Matsumoto, Ruby, 1995',
  ].join('\n');
  const rows = parseTable(source);
  console.log(format(rows));

  const literal = [
    ['id', 'status'],
    ['1', 'ok'],
    ['27', 'pending'],
  ];
  const table = format(literal);
  console.log('');
  console.log(table);
}

main();

