function validatePolygon(vertices) {
  if (!Array.isArray(vertices) || vertices.length < 3) {
    throw new TypeError('a polygon needs at least three vertices');
  }
  vertices.forEach((vertex, index) => {
    if (!Array.isArray(vertex) || vertex.length !== 2) {
      throw new TypeError(`vertex ${index} must be an [x, y] pair`);
    }
    const [x, y] = vertex;
    if (!Number.isFinite(x) || !Number.isFinite(y)) {
      throw new TypeError(`vertex ${index} has non-numeric coordinates`);
    }
  });
}

function round2(value) {
  return Math.round(value * 100) / 100;
}

function metrics(vertices) {
  validatePolygon(vertices);
  const count = vertices.length;
  let crossSum = 0;
  let perimeter = 0;
  for (let i = 0; i < count; i += 1) {
    const [x1, y1] = vertices[i];
    const [x2, y2] = vertices[(i + 1) % count];
    crossSum += x1 * y2 - x2 * y1;
    const dx = x2 - x1;
    const dy = y2 - y1;
    perimeter += Math.sqrt(dx * dx + dy * dy);
  }
  const area = Math.abs(crossSum) / 2;
  return [round2(area), round2(perimeter)];
}

function describe(name, vertices) {
  const [area, perimeter] = metrics(vertices);
  const shape = `${name} (${vertices.length} vertices)`;
  return `${shape}: area = ${area.toFixed(2)}, perimeter = ${perimeter.toFixed(2)}`;
}

function regularPolygon(sides, radius) {
  const step = (2 * Math.PI) / sides;
  const points = [];
  for (let i = 0; i < sides; i += 1) {
    const angle = i * step;
    points.push([radius * Math.cos(angle), radius * Math.sin(angle)]);
  }
  return points;
}

function main() {
  const square = [[0, 0], [4, 0], [4, 4], [0, 4]];
  const triangle = [[0, 0], [5, 0], [0, 12]];
  const arrowhead = [[1, 1], [6, 2], [3, 5], [6, 8], [1, 9]];
  const hexagon = regularPolygon(6, 3);
  const report = [
    describe('square', square),
    describe('right triangle', triangle),
    describe('arrowhead', arrowhead),
    describe('regular hexagon', hexagon),
  ];
  report.forEach((line) => console.log(line));

  try {
    metrics([[0, 0], [1, 1]]);
  } catch (error) {
    console.log(`rejected: ${error.message}`);
  }
}

main();

module.exports = { metrics, describe, regularPolygon };

