const TAX_RATE = 0.08;
const LINE_WIDTH = 30;

function formatMoney(amount) {
  return amount.toFixed(2);
}

function formatLine(label, amount) {
  const price = formatMoney(amount);
  const fillCount = LINE_WIDTH - label.length - price.length;
  if (fillCount < 1) {
    const room = LINE_WIDTH - price.length - 1;
    const clipped = label.slice(0, Math.max(room, 0));
    return clipped + '.'.repeat(LINE_WIDTH - clipped.length - price.length) + price;
  }
  return label + '.'.repeat(fillCount) + price;
}

function validateItem(item, index) {
  if (!Array.isArray(item) || item.length < 3) {
    throw new TypeError(`item ${index} must be [name, price, taxable]`);
  }
  const [name, price, taxable] = item;
  if (typeof name !== 'string') {
    throw new TypeError(`item ${index}: name must be a string`);
  }
  if (typeof price !== 'number' || !Number.isFinite(price)) {
    throw new TypeError(`item ${index}: price must be a finite number`);
  }
  return { name, price, taxable: Boolean(taxable) };
}

function summarize(items) {
  let subtotal = 0;
  let taxableTotal = 0;
  for (let i = 0; i < items.length; i += 1) {
    const entry = validateItem(items[i], i);
    subtotal += entry.price;
    if (entry.taxable) {
      taxableTotal += entry.price;
    }
  }
  const tax = taxableTotal * TAX_RATE;
  return { subtotal, tax, total: subtotal + tax };
}

function print(items) {
  if (!Array.isArray(items)) {
    throw new TypeError('items must be an array');
  }
  const lines = items.map((item, index) => {
    const entry = validateItem(item, index);
    return formatLine(entry.name, entry.price);
  });
  const { subtotal, tax, total } = summarize(items);
  lines.push(formatLine('SUBTOTAL', subtotal));
  lines.push(formatLine('TAX', tax));
  lines.push(formatLine('TOTAL', total));
  return lines;
}

const receipt = print([
  ['Rice', 4.75, false],
  ['Dish Soap', 3.99, true],
  ['Coffee Beans', 12.5, true],
  ['Bananas', 1.2, false],
]);

for (const line of receipt) {
  console.log(line);
}

module.exports = { print, summarize, formatLine };

