const LIST_NAMES = ['backlog', 'active', 'completed'];

function createBoard() {
  const board = {
    backlog: [1, 2, 3, 4, 5],
    active: [],
    completed: [],
  };
  return board;
}

function locate(board, task) {
  for (const name of LIST_NAMES) {
    const index = board[name].indexOf(task);
    if (index !== -1) {
      return { name, index };
    }
  }
  return null;
}

function move(board, task, target) {
  const location = locate(board, task);
  if (location === null) {
    return false;
  }
  const source = board[location.name];
  const [removed] = source.splice(location.index, 1);
  board[target].push(removed);
  return true;
}

function process(actions) {
  const board = createBoard();
  let errors = 0;
  for (const [task, target] of actions) {
    if (!LIST_NAMES.includes(target)) {
      throw new Error(`unknown target list: ${target}`);
    }
    const moved = move(board, task, target);
    if (!moved) {
      errors += 1;
    }
  }
  return [board.backlog.length, board.active.length, board.completed.length, errors];
}

function formatReport(counts) {
  const labels = [...LIST_NAMES, 'errors'];
  const parts = counts.map((count, i) => `${labels[i]}=${count}`);
  return parts.join(' ');
}

function main() {
  const script = [
    [1, 'active'],
    [2, 'active'],
    [1, 'completed'],
    [3, 'completed'],
    [9, 'active'],
    [4, 'active'],
    [2, 'completed'],
    [7, 'completed'],
  ];
  const counts = process(script);
  console.log(formatReport(counts));
  console.log(counts.join(','));
}

main();

