const OPCODE_NAMES = ['load', 'add', 'store', 'branch'];
const WORD_SIZE = 16;
const MAX_WORD = (1 << WORD_SIZE) - 1;

function splitFields(word) {
  const operation = (word >> 12) & 0xf;
  const register = (word >> 8) & 0xf;
  const immediate = word & 0xff;
  return { operation, register, immediate };
}

function checkWord(word, index) {
  if (!Number.isInteger(word)) {
    throw new TypeError(`instruction at index ${index} is not an integer: ${word}`);
  }
  if (word < 0 || word > MAX_WORD) {
    throw new RangeError(`instruction at index ${index} does not fit in sixteen bits: ${word}`);
  }
}

function describe(fields) {
  const { operation, register, immediate } = fields;
  const mnemonic = OPCODE_NAMES[operation];
  if (mnemonic === undefined) {
    return `unknown operation ${operation} with register ${register} and value ${immediate}`;
  }
  switch (mnemonic) {
    case 'load':
      return `load register ${register} with ${immediate}`;
    case 'add':
      return `add ${immediate} to register ${register}`;
    case 'store':
      return `store register ${register} at address ${immediate}`;
    default:
      return `branch to address ${immediate} if register ${register} is set`;
  }
}

function decode(instructions) {
