const GRID_SIZE = 10;
const RAMP = [' ', '.', '-', '#'];

function validatePoint(point, index) {
  if (!Array.isArray(point) || point.length !== 3) {
    throw new TypeError(`point ${index} must be an array of [x, y, intensity]`);
  }
  const [x, y, intensity] = point;
  for (const coord of [x, y]) {
    if (!Number.isInteger(coord) || coord < 0 || coord >= GRID_SIZE) {
      throw new RangeError(`point ${index} has a coordinate outside 0..${GRID_SIZE - 1}`);
    }
  }
  if (typeof intensity !== 'number' || !Number.isFinite(intensity)) {
    throw new TypeError(`point ${index} has a non-numeric intensity`);
  }
  return { x, y, intensity };
}

function accumulate(points) {
  const grid = Array.from({ length: GRID_SIZE }, () => new Array(GRID_SIZE).fill(0));
  points.forEach((point, index) => {
    const { x, y, intensity } = validatePoint(point, index);
    grid[y][x] += intensity;
  });
  return grid;
}

function gridMaximum(grid) {
  let max = 0;
  for (const row of grid) {
    for (const value of row) {
      if (value > max) {
        max = value;
      }
    }
  }
  return max;
}

function shadeOf(value, max) {
  if (value === 0) {
    return RAMP[0];
  }
  const ratio = value / max;
  if (ratio < 1 / 3) {
    return RAMP[1];
  }
  if (ratio < 2 / 3) {
    return RAMP[2];
  }
  return RAMP[3];
}

function render(points) {
  if (!Array.isArray(points)) {
    throw new TypeError('points must be an array');
  }
  const grid = accumulate(points);
  const max = gridMaximum(grid);
  return grid.map((row) => row.map((value) => shadeOf(value, max)).join(''));
}

function frame(rows) {
  const border = `+${'-'.repeat(GRID_SIZE)}+`;
  return [border, ...rows.map((row) => `|${row}|`), border].join('\n');
}

