function parseChord(spec) {
  const tokens = spec.trim().split(/\s+/);
  if (tokens.length !== 6) {
    throw new Error(`a chord needs exactly six strings, got ${tokens.length}`);
  }
  return tokens.map((token) => {
    const fret = token === 'x' || token === 'X' ? -1 : Number(token);
    if (!Number.isInteger(fret) || fret < -1) {
      throw new Error(`invalid fret value: ${token}`);
    }
    return fret;
  });
}

function validate(frets) {
  if (!Array.isArray(frets) || frets.length !== 6) {
    throw new Error('validate expects an array of six fret values');
  }
  const played = frets.filter((fret) => fret > 0);
  const unique = new Set(played);
  let stretch = 0;
  if (played.length > 0) {
    const lowest = Math.min(...played);
    const highest = Math.max(...played);
    stretch = highest - lowest;
  }
  const fingers = unique.size;
  const playable = stretch <= 4 && fingers <= 4;
  return [stretch, fingers, playable];
}

function describe(name, frets) {
  const [stretch, fingers, playable] = validate(frets);
  const shape = frets.map((fret) => (fret < 0 ? 'x' : String(fret))).join(' ');
  const verdict = playable ? 'playable' : 'not playable';
  return `${name.padEnd(6)} ${shape.padEnd(14)} stretch=${stretch} fingers=${fingers} ${verdict}`;
}

function report(library) {
  const lines = [];
  let unreachable = 0;
  for (const [name, spec] of library) {
    const frets = parseChord(spec);
    lines.push(describe(name, frets));
    if (!validate(frets)[2]) {
      unreachable += 1;
    }
  }
  lines.push(`${unreachable} of ${library.length} shapes are out of reach.`);
  return lines.join('\n');
}

const library = [
  ['E', '0 2 2 1 0 0'],
  ['Am', 'x 0 2 2 1 0'],
  ['C', 'x 3 2 0 1 0'],
  ['F#m7', '2 4 2 2 2 2'],
  ['Bb9', 'x 1 0 1 1 3'],
  ['wide', '1 3 5 7 9 11'],
  ['open', 'x x x x x x'],
];

console.log(report(library));

