const POINTS = [6, 4, 3, 2, 1];

function scoreRace(race) {
  const scores = new Map();
  const places = Math.min(race.length, POINTS.length);
  for (let place = 0; place < places; place += 1) {
    const team = race[place];
    const earned = POINTS[place];
    scores.set(team, (scores.get(team) || 0) + earned);
  }
  return scores;
}

function accumulate(results) {
  const totals = new Map();
  for (const race of results) {
    const raceScores = scoreRace(race);
    for (const [team, earned] of raceScores) {
      const running = totals.get(team) || 0;
      totals.set(team, running + earned);
    }
  }
  return totals;
}

function tally(results) {
  if (!Array.isArray(results) || results.length === 0) {
    return ['', 0];
  }
  const totals = accumulate(results);
  let bestTeam = '';
  let bestPoints = 0;
  for (const [team, points] of totals) {
    if (points > bestPoints) {
      bestTeam = team;
      bestPoints = points;
    }
  }
  return [bestTeam, bestPoints];
}

function formatStandings(results) {
  const totals = accumulate(results);
  const ranked = [...totals.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
  const lines = ranked.map(([team, points], index) => {
    const rank = String(index + 1).padStart(2, ' ');
    const padded = team.padEnd(12, ' ');
    return `${rank}. ${padded} ${points}`;
  });
  return lines.join('\n');
}

const season = [
  ['Hawks', 'Ravens', 'Falcons', 'Owls', 'Kites', 'Wrens'],
  ['Ravens', 'Hawks', 'Owls', 'Falcons', 'Wrens'],
  ['Falcons', 'Ravens', 'Hawks', 'Kites'],
  ['Ravens', 'Owls', 'Hawks']
];

const [winner, winningPoints] = tally(season);
console.log(formatStandings(season));
console.log(`Winner: ${winner} with ${winningPoints} points`);

