function countCharacters(words) {
  let total = 0;
  for (const entry of words) {
    total += entry[0].length;
  }
  return total;
}

function countErrors(words) {
  let errors = 0;
  for (const entry of words) {
    const target = entry[0];
    const typed = entry[1];
    if (target !== typed) {
      errors += 1;
    }
  }
  return errors;
}

function totalSeconds(words) {
  let seconds = 0;
  for (const entry of words) {
    seconds += entry[2];
  }
  return seconds;
}

function evaluate(words) {
  if (!Array.isArray(words) || words.length === 0) {
    throw new Error('evaluate requires a non-empty array of typed words');
  }
  const characters = countCharacters(words);
  const errors = countErrors(words);
  const seconds = totalSeconds(words);
  if (seconds <= 0) {
    throw new Error('total typing time must be positive');
  }
  const minutes = seconds / 60;
  const gross = characters / 5 / minutes;
  const net = gross - errors / minutes;
  const accuracy = ((words.length - errors) / words.length) * 100;
  return [gross, net, accuracy];
}

function formatReport(words) {
  const [gross, net, accuracy] = evaluate(words);
  const lines = [
    `Gross WPM: ${gross.toFixed(2)}`,
    `Net WPM:   ${net.toFixed(2)}`,
    `Accuracy:  ${accuracy.toFixed(1)}%`
  ];
  return lines.join('\n');
}

const session = [
  ['reference', 'reference', 2.1],
  ['keyboard', 'keybaord', 1.8],
  ['typing', 'typing', 1.2],
  ['accuracy', 'accuracy', 2.4],
  ['measure', 'measuer', 1.9]
];

console.log(formatReport(session));

