const ATTACK_FRACTION = 0.1;
const DECAY_FRACTION = 0.2;
const RELEASE_FRACTION = 0.2;

function validateNote(note, index) {
  if (!Array.isArray(note) || note.length !== 3) {
    throw new TypeError(`note ${index} must be [frequency, amplitude, duration]`);
  }
  const [frequency, amplitude, duration] = note;
  if (![frequency, amplitude, duration].every(Number.isFinite)) {
    throw new TypeError(`note ${index} contains a non-numeric value`);
  }
  if (frequency <= 0) {
    throw new RangeError(`note ${index} has a non-positive frequency`);
  }
  if (amplitude < 0) {
    throw new RangeError(`note ${index} has a negative amplitude`);
  }
  if (duration < 0) {
    throw new RangeError(`note ${index} has a negative duration`);
  }
  return { frequency, amplitude, duration };
}

function envelope(amplitude, duration) {
  const attack = duration * ATTACK_FRACTION;
  const decay = duration * DECAY_FRACTION;
  const release = duration * RELEASE_FRACTION;
  const sustain = duration - attack - decay - release;
  const sustainAmplitude = amplitude / 2;
  return [attack, decay, sustain, release, sustainAmplitude];
}

function synthesize(notes) {
  if (!Array.isArray(notes)) {
    throw new TypeError('notes must be an array');
  }
  return notes.map((note, index) => {
    const { amplitude, duration } = validateNote(note, index);
    return envelope(amplitude, duration);
  });
}

function totalDuration(notes) {
  return notes.reduce((sum, note) => sum + note[2], 0);
}

function describe(notes) {
  const envelopes = synthesize(notes);
  const lines = envelopes.map((stages, index) => {
    const [attack, decay, sustain, release, sustainAmplitude] = stages;
    const frequency = notes[index][0];
    const timings = [attack, decay, sustain, release]
      .map((ms) => `${ms.toFixed(1)}ms`)
      .join(' / ');
    return `${frequency.toFixed(2)} Hz  A/D/S/R ${timings}  sustain@${sustainAmplitude.toFixed(3)}`;
  });
  const footer = `total: ${totalDuration(notes).toFixed(1)}ms across ${notes.length} note(s)`;
  return lines.concat(footer).join('\n');
}

const melody = [
  [440.0, 1.0, 500],
  [523.25, 0.8, 250],
  [659.25, 0.6, 1000],
];
console.log(describe(melody));
console.log(JSON.stringify(synthesize(melody)));

