const DOT = '.';
const DASH = '-';
const SPACE = ' ';
const DOT_UNITS = 1;
const DASH_UNITS = 3;
const SYMBOL_GAP_UNITS = 1;
const LETTER_GAP_UNITS = 3;
const WORD_GAP_UNITS = 7;

function validate(message) {
  if (typeof message !== 'string') {
    throw new TypeError('message must be a string');
  }
  const allowed = new Set([DOT, DASH, SPACE]);
  for (const ch of message) {
    if (!allowed.has(ch)) {
      throw new Error(`invalid character in message: ${JSON.stringify(ch)}`);
    }
  }
  return message.trim();
}

function tokenize(message) {
  const tokens = [];
  let index = 0;
  while (index < message.length) {
    const ch = message[index];
    if (ch === SPACE) {
      let spaces = 0;
      while (index < message.length && message[index] === SPACE) {
        spaces += 1;
        index += 1;
      }
      tokens.push({ type: 'gap', spaces });
    } else {
      tokens.push({ type: 'symbol', ch });
      index += 1;
    }
  }
  return tokens;
}

function gapUnits(spaces) {
  return spaces >= 2 ? WORD_GAP_UNITS : LETTER_GAP_UNITS;
}

function measure(message) {
  const tokens = tokenize(validate(message));
  let dots = 0;
  let dashes = 0;
  let units = 0;
  let previousWasSymbol = false;
  for (const token of tokens) {
    if (token.type === 'gap') {
      units += gapUnits(token.spaces);
      previousWasSymbol = false;
    } else {
      if (previousWasSymbol) {
        units += SYMBOL_GAP_UNITS;
      }
      if (token.ch === DOT) {
        dots += 1;
        units += DOT_UNITS;
      } else {
        dashes += 1;
        units += DASH_UNITS;
      }
      previousWasSymbol = true;
    }
  }
  return [dots, dashes, units];
}

module.exports = { measure };

