function axialToCube(axial) {
  const [q, r] = axial;
  const x = q;
  const z = r;
  const y = -q - r;
  return { x, y, z };
}

function cubeDistance(a, b) {
  const dx = Math.abs(a.x - b.x);
  const dy = Math.abs(a.y - b.y);
  const dz = Math.abs(a.z - b.z);
  return Math.max(dx, dy, dz);
}

function validatePath(coords) {
  if (!Array.isArray(coords)) {
    throw new TypeError('distance expects an array of [q, r] pairs');
  }
  coords.forEach((pair, index) => {
    const isPair = Array.isArray(pair) && pair.length === 2;
    if (!isPair || !pair.every(Number.isFinite)) {
      throw new TypeError(`coordinate at index ${index} is not a numeric [q, r] pair`);
    }
  });
}

function distance(coords) {
  validatePath(coords);
  const cubes = coords.map(axialToCube);
  let total = 0;
  for (let i = 1; i < cubes.length; i += 1) {
    total += cubeDistance(cubes[i - 1], cubes[i]);
  }
  return total;
}

function describePath(coords) {
  const cubes = coords.map(axialToCube);
  const legs = [];
  for (let i = 1; i < cubes.length; i += 1) {
    const from = coords[i - 1];
    const to = coords[i];
    const steps = cubeDistance(cubes[i - 1], cubes[i]);
    legs.push(`(${from[0]},${from[1]}) -> (${to[0]},${to[1]}): ${steps}`);
  }
  return legs.concat(`total: ${distance(coords)}`).join('\n');
}

module.exports = { distance, describePath, axialToCube, cubeDistance };

if (require.main === module) {
  const routes = [
    [[0, 0], [1, -1], [2, -2]],
    [[3, 4], [-2, 1], [0, 0], [5, -5]],
    [[7, 7]]
  ];
  routes.forEach((route, index) => {
    const label = `route ${index + 1}`;
    console.log(`${label}:`);
    console.log(describePath(route));
  });
}

