function validateWidth(width) {
  if (!Number.isInteger(width) || width <= 0) {
    throw new RangeError('width must be a positive integer');
  }
}

function validateWords(words, width) {
  if (!Array.isArray(words)) {
    throw new TypeError('words must be an array');
  }
  for (const word of words) {
    if (typeof word !== 'string' || word.length === 0) {
      throw new TypeError('each word must be a non-empty string');
    }
    if (word.length > width) {
      throw new RangeError(`word longer than width: "${word}" > ${width}`);
    }
  }
}

function groupLines(words, width) {
  const lines = [];
  let current = [];
  let length = 0;
  for (const word of words) {
    const projected = length === 0 ? word.length : length + 1 + word.length;
    if (projected > width && current.length > 0) {
      lines.push(current);
      current = [word];
      length = word.length;
    } else {
      current.push(word);
      length = projected;
    }
  }
  if (current.length > 0) {
    lines.push(current);
  }
  return lines;
}

function spreadLine(line, width) {
  if (line.length === 1) {
    return line[0].padEnd(width, ' ');
  }
  const letters = line.reduce((sum, word) => sum + word.length, 0);
  const gaps = line.length - 1;
  const totalSpaces = width - letters;
  const base = Math.floor(totalSpaces / gaps);
  const extra = totalSpaces % gaps;
  let out = line[0];
  for (let i = 1; i < line.length; i += 1) {
    const size = base + (i <= extra ? 1 : 0);
    out += ' '.repeat(size) + line[i];
  }
  return out;
}

function justify(words, width) {
  validateWidth(width);
  validateWords(words, width);
  const groups = groupLines(words, width);
  const lastIndex = groups.length - 1;
  return groups.map((group, index) => (
    index === lastIndex
      ? group.join(' ').padEnd(width, ' ')
      : spreadLine(group, width)
  ));
}

module.exports = { justify, groupLines, spreadLine };

