function distanceFromOrigin(x, y) {
  return Math.hypot(x, y);
}

function validatePlant(plant, index) {
  if (!Array.isArray(plant) || plant.length !== 3) {
    throw new TypeError(`plant at index ${index} must be [x, y, water]`);
  }
  const [x, y, water] = plant;
  const numbers = [x, y, water];
  if (!numbers.every((value) => typeof value === 'number' && Number.isFinite(value))) {
    throw new TypeError(`plant at index ${index} must contain finite numbers`);
  }
  if (water < 0) {
    throw new RangeError(`plant at index ${index} has a negative water requirement`);
  }
  return { x, y, water };
}

function normalizePlants(plants) {
  if (!Array.isArray(plants)) {
    throw new TypeError('plants must be an array');
  }
  return plants.map((plant, index) => validatePlant(plant, index));
}

function sprinklerRadius(entries) {
  let radius = 0;
  for (const entry of entries) {
    const distance = distanceFromOrigin(entry.x, entry.y);
    if (distance > radius) {
      radius = distance;
    }
  }
  return radius;
}

function totalWaterRequired(entries) {
  let total = 0;
  for (const entry of entries) {
    total += entry.water;
  }
  return total;
}

function circleArea(radius) {
  return Math.PI * radius * radius;
}

function plan(plants) {
  const entries = normalizePlants(plants);
  const radius = sprinklerRadius(entries);
  const totalWater = totalWaterRequired(entries);
  const area = circleArea(radius);
  return [Math.round(radius), Math.round(totalWater), Math.round(area)];
}

module.exports = { plan, distanceFromOrigin, sprinklerRadius, totalWaterRequired, circleArea };

