const POINTS_TO_WIN_GAME = 4;
const POINTS_TO_WIN_TIEBREAK = 7;
const GAMES_TO_WIN_SET = 6;
const WINNING_MARGIN = 2;

function parsePoints(points) {
  if (typeof points !== 'string') {
    throw new TypeError('points must be a string of the characters 1 and 2');
  }
  const winners = [];
  for (const character of points) {
    const index = PLAYER_INDEX[character];
    if (index === undefined) {
      throw new Error(`invalid point winner: ${character}`);
    }
    winners.push(index);
  }
  return winners;
}

function rallyWinner(first, second, target) {
  const leader = first - second;
  const reached = Math.max(first, second) >= target;
  if (reached && Math.abs(leader) >= WINNING_MARGIN) {
    return leader > 0 ? 0 : 1;
  }
  return null;
}

function setDecided(games) {
  const first = games[0];
  const second = games[1];
  return Math.max(first, second) >= GAMES_TO_WIN_SET
    && Math.abs(first - second) >= WINNING_MARGIN;
}

function playSet(winners) {
  const games = [0, 0];
  let rally = [0, 0];
  for (const winner of winners) {
    const tiebreak = games[0] === GAMES_TO_WIN_SET && games[1] === GAMES_TO_WIN_SET;
    const target = tiebreak ? POINTS_TO_WIN_TIEBREAK : POINTS_TO_WIN_GAME;
    rally[winner] += 1;
    const gameWinner = rallyWinner(rally[0], rally[1], target);
    if (gameWinner !== null) {
      games[gameWinner] += 1;
      rally = [0, 0];
      if (setDecided(games)) {
        return games;
      }
    }
  }
  return games;
}

function score(points) {
  return playSet(parsePoints(points));
}

module.exports = { score };

