'use strict';

const QUANTITY_PRECISION = 3;
const WEIGHT_TOLERANCE = 1e-6;

function roundTo(value, places) {
  const factor = 10 ** places;
  return Math.round(value * factor) / factor;
}

function validatePortfolio(portfolio) {
  if (!Array.isArray(portfolio) || portfolio.length === 0) {
    throw new TypeError('portfolio must be a non-empty list of asset rows');
  }
  let weightSum = 0;
  for (const row of portfolio) {
    if (!Array.isArray(row) || row.length !== 4) {
      throw new TypeError('each asset row must be [ticker, amount, price, targetPct]');
    }
    const [ticker, amount, price, targetPct] = row;
    if (typeof ticker !== 'string' || ticker.trim() === '') {
      throw new TypeError('ticker symbol must be a non-empty string');
    }
    const numbers = [amount, price, targetPct];
    if (!numbers.every((n) => typeof n === 'number' && Number.isFinite(n))) {
      throw new TypeError(`amount, price and target for ${ticker} must be finite numbers`);
    }
    if (price <= 0) {
      throw new RangeError(`price for ${ticker} must be greater than zero`);
    }
    weightSum += targetPct;
  }
  if (Math.abs(weightSum - 1) > WEIGHT_TOLERANCE) {
    throw new RangeError(`target percentages must sum to 1, received ${weightSum}`);
  }
}

function totalPortfolioValue(portfolio) {
  return portfolio.reduce((sum, [, amount, price]) => sum + amount * price, 0);
}

function rebalance(portfolio) {
  validatePortfolio(portfolio);
  const totalValue = totalPortfolioValue(portfolio);
  const orders = [];
  for (const [ticker, amount, price, targetPct] of portfolio) {
    const currentValue = amount * price;
    const targetValue = totalValue * targetPct;
    const valueDelta = targetValue - currentValue;
    orders.push([ticker, roundTo(valueDelta / price, QUANTITY_PRECISION)]);
  }
  return orders;
}

function formatOrder([ticker, quantity]) {
  const action = quantity > 0 ? 'BUY ' : 'SELL';
  const magnitude = Math.abs(quantity).toFixed(QUANTITY_PRECISION);
  return `${action} ${magnitude} ${ticker}`;
}

function rebalanceReport(portfolio) {
  const trades = rebalance(portfolio).filter(([, quantity]) => quantity !== 0);
  if (trades.length === 0) {
    return 'portfolio is already balanced';
  }
  return trades.map(formatOrder).join('\n');
}

const holdings = [['bitcoin', 1, 50000, 0.6], ['ethereum', 10, 3000, 0.4]];
console.log(JSON.stringify(rebalance(holdings)));
console.log(rebalanceReport(holdings));

const spread = [
  ['bitcoin', 0.5, 62000, 0.5],
  ['ethereum', 4, 3400, 0.3],
  ['solana', 100, 145, 0.2],
];
console.log(`total value: ${totalPortfolioValue(spread).toFixed(2)}`);
console.log(rebalanceReport(spread));

