function formatTime(minutes) {
  const hours = Math.floor(minutes / 60) % 24;
  const rest = minutes % 60;
  return `${String(hours).padStart(2, '0')}:${String(rest).padStart(2, '0')}`;
}

function validateMeetings(meetings) {
  if (!Array.isArray(meetings)) {
    throw new TypeError('meetings must be an array of [start, end] pairs');
  }
  meetings.forEach((pair, index) => {
    if (!Array.isArray(pair) || pair.length !== 2) {
      throw new TypeError(`meeting ${index} must be a pair of integers`);
    }
    const [start, end] = pair;
    if (!Number.isInteger(start) || !Number.isInteger(end)) {
      throw new TypeError(`meeting ${index} has non-integer times`);
    }
    if (end < start) {
      throw new RangeError(`meeting ${index} ends before it starts`);
    }
  });
}

function assignRooms(meetings) {
  validateMeetings(meetings);
  const ordered = meetings
    .map(([start, end]) => [start, end])
    .sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const rooms = [];
  for (const [start, end] of ordered) {
    let target = null;
    for (const busyPeriods of rooms) {
      const last = busyPeriods[busyPeriods.length - 1];
      if (last[1] <= start) {
        target = busyPeriods;
        break;
      }
    }
    if (target === null) {
      target = [];
      rooms.push(target);
    }
    target.push([start, end]);
  }
  return rooms;
}

function allocate(meetings) {
  return assignRooms(meetings).length;
}

function describeAllocation(meetings) {
  const rooms = assignRooms(meetings);
  const lines = rooms.map((busyPeriods, index) => {
    const slots = busyPeriods
      .map(([start, end]) => `${formatTime(start)}-${formatTime(end)}`)
      .join(', ');
    return `Room ${index + 1}: ${slots}`;
  });
  lines.push(`Rooms required: ${rooms.length}`);
  return lines.join('\n');
}

module.exports = { allocate, assignRooms, describeAllocation, formatTime };

