function validateTiles(tiles) {
  if (!Array.isArray(tiles)) {
    throw new TypeError('tiles must be an array of pairs');
  }
  const deck = [];
  for (const tile of tiles) {
    if (!Array.isArray(tile) || tile.length !== 2) {
      throw new TypeError('each domino must be a pair of two numbers');
    }
    const [left, right] = tile;
    if (!Number.isInteger(left) || !Number.isInteger(right)) {
      throw new TypeError(`domino ${JSON.stringify(tile)} must hold integers`);
    }
    deck.push([left, right]);
  }
  return deck;
}

function extend(deck, used, tail) {
  let bestLength = 0;
  let bestPath = [];
  for (let i = 0; i < deck.length; i += 1) {
    if (used[i]) {
      continue;
    }
    const [left, right] = deck[i];
    const orientations = [];
    if (left === tail) {
      orientations.push([left, right]);
    }
    if (right === tail && right !== left) {
      orientations.push([right, left]);
    }
    for (const [head, next] of orientations) {
      used[i] = true;
      const rest = extend(deck, used, next);
      used[i] = false;
      if (1 + rest.length > bestLength) {
        bestLength = 1 + rest.length;
        bestPath = [[head, next], ...rest.path];
      }
    }
  }
  return { length: bestLength, path: bestPath };
}

function longestChain(tiles) {
  const deck = validateTiles(tiles);
  const used = new Array(deck.length).fill(false);
  let best = { length: 0, path: [] };
  for (let i = 0; i < deck.length; i += 1) {
    const [left, right] = deck[i];
    const starts = left === right ? [[left, right]] : [[left, right], [right, left]];
    for (const [head, next] of starts) {
      used[i] = true;
      const rest = extend(deck, used, next);
      used[i] = false;
      if (1 + rest.length > best.length) {
        best = { length: 1 + rest.length, path: [[head, next], ...rest.path] };
      }
    }
  }
  return best;
}

function chain(tiles) {
  return longestChain(tiles).length;
}

function formatChain(path) {
  return path.length === 0 ? '(empty)' : path.map(([head, next]) => `${head}-${next}`).join(' ');
}

const hands = [
  [[1, 2], [3, 4], [2, 3], [5, 6]],
  [[2, 2], [2, 5], [5, 2], [1, 3]],
  [[4, 7], [8, 9]],
];
for (const hand of hands) {
  const result = longestChain(hand);
  console.log(`${JSON.stringify(hand)} -> ${result.length} [${formatChain(result.path)}]`);
}

