const DAY_LENGTH = 1440;
const BASE_FARE = 3;
const DAILY_CAP = 12;

function dayIndex(timestamp) {
  return Math.floor(timestamp / DAY_LENGTH);
}

function parseTap(event) {
  if (!Array.isArray(event) || event.length !== 3) {
    throw new TypeError('each tap must be [minutes, station, zone]');
  }
  const [timestamp, station, zone] = event;
  if (!Number.isInteger(timestamp) || timestamp < 0) {
    throw new RangeError('tap timestamp must be a non-negative integer number of minutes');
  }
  if (typeof station !== 'string' || station.length === 0) {
    throw new TypeError('tap station must be a non-empty string');
  }
  if (!Number.isInteger(zone) || zone < 1) {
    throw new RangeError('tap zone must be a positive integer');
  }
  return { timestamp, station, zone };
}

function buildJourneys(taps) {
  if (!Array.isArray(taps)) {
    throw new TypeError('taps must be a list of tap events');
  }
  const journeys = [];
  for (let i = 0; i + 1 < taps.length; i += 2) {
    const entry = parseTap(taps[i]);
    const exit = parseTap(taps[i + 1]);
    if (exit.timestamp < entry.timestamp) {
      throw new RangeError(`journey from ${entry.station} ends before it starts`);
    }
    journeys.push({ entry, exit });
  }
  return journeys;
}

function journeyFare(journey) {
  const boundaries = Math.abs(journey.exit.zone - journey.entry.zone);
  return BASE_FARE + boundaries;
}

function chargeAgainstCap(accumulated, fare) {
  const remaining = Math.max(0, DAILY_CAP - accumulated);
  return Math.min(fare, remaining);
}

function journeyCharges(taps) {
  const journeys = buildJourneys(taps);
  const dailyTotals = new Map();
  const charges = [];
  for (const journey of journeys) {
    const day = dayIndex(journey.entry.timestamp);
    const accumulated = dailyTotals.get(day) || 0;
    const charged = chargeAgainstCap(accumulated, journeyFare(journey));
    dailyTotals.set(day, accumulated + charged);
    charges.push(charged);
  }
  return charges;
}

function calculate(taps) {
  let total = 0;
  for (const charged of journeyCharges(taps)) {
    total += charged;
  }
  return total;
}

