const BYE = "bye";

function nextPowerOfTwo(count) {
  const exponent = Math.ceil(Math.log2(Math.max(2, count)));
  return 2 ** exponent;
}

function normalizeNames(players) {
  if (!Array.isArray(players)) {
    throw new TypeError("players must be an array of strings");
  }
  const cleaned = [];
  for (const entry of players) {
    if (typeof entry !== "string") {
      throw new TypeError(`player names must be strings, got ${typeof entry}`);
    }
    const name = entry.trim();
    if (name.length > 0) {
      cleaned.push(name);
    }
  }
  return cleaned;
}

function padWithByes(names) {
  const size = nextPowerOfTwo(names.length);
  const field = names.slice();
  for (let slot = names.length; slot < size; slot += 1) {
    field.push(BYE);
  }
  return field;
}

function bracket(players) {
  const names = normalizeNames(players);
  if (names.length === 0) {
    return [];
  }
  const field = padWithByes(names);
  const half = field.length / 2;
  const pairs = [];
  for (let i = 0; i < half; i += 1) {
    const home = field[i];
    const away = field[field.length - 1 - i];
