const LOAN_PERIOD_DAYS = 14;
const DAILY_FEE = 2;
const WEEK_LENGTH = 7;

function isWeekend(dayOffset) {
  const positionInWeek = dayOffset % WEEK_LENGTH;
  return positionInWeek === 0 || positionInWeek === 1;
}

function readRecord(record, index) {
  if (!Array.isArray(record) || record.length !== 3) {
    throw new TypeError(`Record ${index} must hold three integers`);
  }
  const [checkoutDay, returnDay, baseValue] = record;
  for (const value of record) {
    if (!Number.isInteger(value)) {
      throw new TypeError(`Record ${index} contains a non-integer value: ${value}`);
    }
  }
  if (returnDay < checkoutDay) {
    throw new RangeError(`Record ${index} returns the item before checkout`);
  }
  if (baseValue < 0) {
    throw new RangeError(`Record ${index} has a negative base value`);
  }
  return { checkoutDay, returnDay, baseValue };
}

function lateFee(loan) {
  const dueDay = loan.checkoutDay + LOAN_PERIOD_DAYS;
  const daysLate = loan.returnDay - dueDay;
  let fee = 0;
  for (let dayOffset = 1; dayOffset <= daysLate; dayOffset += 1) {
    if (!isWeekend(dayOffset)) {
      fee += DAILY_FEE;
    }
    if (fee >= loan.baseValue) {
      return loan.baseValue;
    }
  }
  return fee;
}

function assess(records) {
  if (!Array.isArray(records)) {
    throw new TypeError('assess expects a list of records');
  }
  return records.map((record, index) => lateFee(readRecord(record, index)));
}

function formatReport(records, fees) {
  const lines = ['item  out   in  value   fee'];
  let total = 0;
  records.forEach((record, index) => {
    const fee = fees[index];
    total += fee;
    const columns = [index + 1, record[0], record[1], record[2], fee];
    lines.push(columns.map((column) => String(column).padStart(5)).join(' '));
  });
  lines.push(`total fees owed: $${total}`);
  return lines.join('\n');
}

const dataset = [[1, 20, 15], [5, 10, 30], [3, 60, 9], [12, 45, 100]];
const fees = assess(dataset);
console.log(fees.join(', '));
console.log(formatReport(dataset, fees));

