const TAX_RATE = 0.08;
const TIP_RATE = 0.2;

function sumPrices(prices) {
  let total = 0;
  for (const price of prices) {
    if (typeof price !== 'number' || !Number.isFinite(price) || price < 0) {
      throw new TypeError(`invalid price: ${price}`);
    }
    total += price;
  }
  return total;
}

function toDiner(record) {
  const [name, items, shared] = record;
  if (typeof name !== 'string' || name.length === 0) {
    throw new TypeError('each diner needs a non-empty name');
  }
  const ordered = Array.isArray(items) ? items : [];
  const appetizers = Array.isArray(shared) ? shared : [];
  return { name, items: ordered, shared: appetizers };
}

function roundCents(amount) {
  return Math.round(amount * 100) / 100;
}

function split(diners) {
  const people = diners.map(toDiner);
  const headcount = people.length;
  if (headcount === 0) {
    return [];
  }
  let sharedTotal = 0;
  for (const person of people) {
    sharedTotal += sumPrices(person.shared);
  }
  const sharePerPerson = sharedTotal / headcount;
  return people.map((person) => {
    const subtotal = sumPrices(person.items) + sharePerPerson;
    const afterTax = subtotal * (1 + TAX_RATE);
    return roundCents(afterTax * (1 + TIP_RATE));
  });
}

function formatReport(diners, totals) {
  const width = diners.reduce((longest, record) => Math.max(longest, record[0].length), 5);
  const lines = diners.map((record, index) => {
    const label = record[0].padEnd(width, ' ');
    const owed = totals[index].toFixed(2);
    return `${label}  $${owed}`;
  });
  const grandTotal = totals.reduce((sum, owed) => sum + owed, 0);
  lines.push(`${'TABLE'.padEnd(width, ' ')}  $${roundCents(grandTotal).toFixed(2)}`);
  return lines.join('\n');
}

const party = [
  ['Linus', [18.5, 3.25], [12.0, 9.0]],
  ['Margaret', [22.0], []],
  ['Alan', [15.75], [6.5]]
];
const owed = split(party);
console.log(formatReport(party, owed));

module.exports = { split, formatReport };

