const HASH = '#';
const DOT = '.';
const CROSS = '+';

function validateDimensions(dimensions) {
  if (!Array.isArray(dimensions) || dimensions.length !== 3) {
    throw new TypeError('dimensions must be a list of three integers');
  }
  for (const value of dimensions) {
    if (!Number.isInteger(value) || value < 0) {
      throw new TypeError('width, height and border must be non-negative integers');
    }
  }
  const [width, height, border] = dimensions;
  if (width < 2 * border || height < 2 * border) {
    throw new RangeError('border thickness is too large for the given width and height');
  }
  return { width, height, border };
}

function diagonalColumns(innerRow, innerHeight, innerWidth) {
  if (innerWidth < 1) {
    return [];
  }
  if (innerHeight < 2) {
    return [0, innerWidth - 1];
  }
  const main = Math.round((innerRow * (innerWidth - 1)) / (innerHeight - 1));
  const anti = innerWidth - 1 - main;
  return [main, anti];
}

function buildRow(row, width, height, border) {
  const innerHeight = height - 2 * border;
  const innerWidth = width - 2 * border;
  const isBorderRow = row < border || row >= height - border;
  const diagonals = isBorderRow ? [] : diagonalColumns(row - border, innerHeight, innerWidth);
  const cells = [];
  for (let col = 0; col < width; col += 1) {
    const isBorderCol = col < border || col >= width - border;
    if (isBorderRow || isBorderCol) {
      cells.push(HASH);
    } else if (diagonals.includes(col - border)) {
      cells.push(CROSS);
    } else {
      cells.push(DOT);
    }
  }
  return cells.join('');
}

function weave(dimensions) {
  const { width, height, border } = validateDimensions(dimensions);
  const pattern = [];
  for (let row = 0; row < height; row += 1) {
    pattern.push(buildRow(row, width, height, border));
  }
  return pattern;
}

module.exports = { weave, diagonalColumns };

