function parseLine(line, lineNumber) {
  const match = /^( *)\*( *)(.*)$/.exec(line);
  if (!match) {
    throw new Error(`line ${lineNumber}: expected leading spaces followed by an asterisk`);
  }
  const indent = match[1].length;
  if (indent % 2 !== 0) {
    throw new Error(`line ${lineNumber}: indentation of ${indent} space(s) is not a multiple of two`);
  }
  const label = match[3].trim();
  if (label === '') {
    throw new Error(`line ${lineNumber}: list item has no text`);
  }
  return { depth: indent / 2, label };
}

function parse(text) {
  const root = [];
  const stack = [root];
  let level = -1;
  let lineNumber = 0;
  for (const line of text.split('\n')) {
    lineNumber += 1;
    if (line.trim() === '') {
      continue;
    }
    const item = parseLine(line, lineNumber);
    if (item.depth > level + 1) {
      throw new Error(`line ${lineNumber}: indentation jumps from level ${level} to ${item.depth}`);
    }
    while (level < item.depth) {
      const child = [];
      stack[stack.length - 1].push(child);
      stack.push(child);
      level += 1;
    }
    while (level > item.depth) {
      stack.pop();
      level -= 1;
    }
    stack[stack.length - 1].push(item.label);
  }
  return root;
}

function formatOutline(list, depth) {
  const lines = [];
  for (const element of list) {
    if (Array.isArray(element)) {
      lines.push(formatOutline(element, depth + 1));
    } else {
      const pad = ' '.repeat(depth * 2);
      lines.push(`${pad}* ${element}`);
    }
  }
  return lines.join('\n');
}

function countItems(list) {
  let total = 0;
  for (const element of list) {
    total += Array.isArray(element) ? countItems(element) : 1;
  }
  return total;
}

function main() {
  const source = [
    '* parent item',
    '  * child item',
    '* second parent',
    '  * first child',
    '    * grandchild',
    '  * second child',
  ].join('\n');
  const tree = parse(source);
  const total = countItems(tree);
  console.log(JSON.stringify(tree));
  console.log(`${total} items parsed`);
  console.log(formatOutline(tree, -1));
}

main();

