const SOURCE = 'origin';
const DRAIN = 'drain';

function buildNetwork(pipes) {
  if (!Array.isArray(pipes)) {
    throw new TypeError('pipes must be a list of [source, destination, capacity] triples');
  }
  const residual = new Map();
  const ensureNode = (node) => {
    if (!residual.has(node)) {
      residual.set(node, new Map());
    }
    return residual.get(node);
  };
  for (const pipe of pipes) {
    if (!Array.isArray(pipe) || pipe.length !== 3) {
      throw new TypeError('each pipe must contain exactly three values');
    }
    const [from, to, limit] = pipe;
    if (typeof from !== 'string' || typeof to !== 'string') {
      throw new TypeError('pipe endpoints must be strings');
    }
    if (!Number.isInteger(limit) || limit < 0) {
      throw new RangeError(`capacity of ${from}->${to} must be a non-negative integer`);
    }
    const outgoing = ensureNode(from);
    const incoming = ensureNode(to);
    outgoing.set(to, (outgoing.get(to) || 0) + limit);
    if (!incoming.has(from)) {
      incoming.set(from, 0);
    }
  }
  return residual;
}

function findAugmentingPath(residual) {
  const parents = new Map([[SOURCE, null]]);
  const queue = [SOURCE];
  while (queue.length > 0) {
    const node = queue.shift();
    for (const [next, capacityLeft] of residual.get(node)) {
      if (capacityLeft > 0 && !parents.has(next)) {
        parents.set(next, node);
        if (next === DRAIN) {
          return parents;
        }
        queue.push(next);
      }
    }
  }
  return null;
}

function flow(pipes) {
  const residual = buildNetwork(pipes);
  if (!residual.has(SOURCE) || !residual.has(DRAIN)) {
    return 0;
  }
  let delivered = 0;
  let parents = findAugmentingPath(residual);
  while (parents !== null) {
    let bottleneck = Infinity;
    for (let node = DRAIN; parents.get(node) !== null; node = parents.get(node)) {
      const previous = parents.get(node);
      bottleneck = Math.min(bottleneck, residual.get(previous).get(node));
    }
    for (let node = DRAIN; parents.get(node) !== null; node = parents.get(node)) {
      const previous = parents.get(node);
      const forward = residual.get(previous);
      const backward = residual.get(node);
      forward.set(node, forward.get(node) - bottleneck);
      backward.set(previous, backward.get(previous) + bottleneck);
    }
    delivered += bottleneck;
    parents = findAugmentingPath(residual);
  }
  return delivered;
}

function describeNetwork(pipes) {
  const layout = pipes.map(([from, to, limit]) => `${from}-${limit}->${to}`).join(', ');
  return `${layout} => ${flow(pipes)}`;
}

const networks = [
  [['origin', 'a', 10], ['a', 'drain', 5]],
  [['origin', 'a', 8], ['origin', 'b', 4], ['a', 'drain', 6], ['b', 'drain', 7]],
  [['origin', 'a', 3], ['a', 'b', 3], ['b', 'drain', 2], ['origin', 'b', 5]]
];
for (const network of networks) {
  console.log(describeNetwork(network));
}

