function flow(pipes) {
  var residual = buildNetwork(pipes);
  if (!residual.has(SOURCE) || !residual.has(DRAIN)) {
    return 0;
  }
  var delivered = 0;
  var parents = findAugmentingPath(residual);
  while (parents !== null) {
    var bottleneck = Infinity;
    for (var node = DRAIN; parents.get(node) !== null; node = parents.get(node)) {
      var previous = parents.get(node);
      bottleneck = Math.min(bottleneck, residual.get(previous).get(node));
