function buildGraph(trails) {
  const graph = new Map();
  for (const trail of trails) {
    const [from, to, difficulty] = trail;
    if (!Number.isInteger(difficulty) || difficulty < 1 || difficulty > 10) {
      throw new RangeError(`difficulty for ${from}-${to} must be an integer from 1 to 10`);
    }
    if (!graph.has(from)) {
      graph.set(from, []);
    }
    if (!graph.has(to)) {
      graph.set(to, []);
    }
    graph.get(from).push({ next: to, difficulty });
    graph.get(to).push({ next: from, difficulty });
  }
  return graph;
}

function isBetter(candidate, current) {
  if (current === null || current === undefined) {
    return true;
  }
  if (candidate.bottleneck !== current.bottleneck) {
    return candidate.bottleneck < current.bottleneck;
  }
  return candidate.hops < current.hops;
}

function route(trails) {
  const graph = buildGraph(trails);
  if (!graph.has("peak") || !graph.has("base")) {
    return [];
  }

  const best = new Map([["peak", { bottleneck: 0, hops: 0, previous: null }]]);
  const settled = new Set();

  while (settled.size < graph.size) {
    let chosen = null;
    let chosenPoint = null;
    for (const [point, state] of best) {
      if (!settled.has(point) && isBetter(state, chosen)) {
        chosen = state;
        chosenPoint = point;
      }
    }
    if (chosenPoint === null || chosenPoint === "base") {
      break;
    }
    settled.add(chosenPoint);
    for (const edge of graph.get(chosenPoint)) {
      const candidate = {
        bottleneck: Math.max(chosen.bottleneck, edge.difficulty),
        hops: chosen.hops + 1,
        previous: chosenPoint
      };
      if (!settled.has(edge.next) && isBetter(candidate, best.get(edge.next))) {
        best.set(edge.next, candidate);
      }
    }
  }

  if (!best.has("base")) {
    return [];
  }
  const path = [];
  let cursor = "base";
  while (cursor !== null) {
    path.unshift(cursor);
    cursor = best.get(cursor).previous;
  }
  return path;
}

function hardestStep(graph, path) {
  let hardest = 0;
  for (let i = 1; i < path.length; i += 1) {
    const edge = graph.get(path[i - 1]).find((link) => link.next === path[i]);
    hardest = Math.max(hardest, edge.difficulty);
  }
  return hardest;
}

const network = [
  ["peak", "mid", 3],
  ["mid", "base", 4],
  ["peak", "ridge", 2],
  ["ridge", "hut", 2],
  ["hut", "base", 3]
];
const chosenPath = route(network);
console.log(`${chosenPath.join(" -> ")} (hardest: ${hardestStep(buildGraph(network), chosenPath)})`);

