const PANEL_HEIGHT = 2;
const PANEL_WIDTH = 3;

function validateRoof(roof) {
  if (!Array.isArray(roof) || roof.length < PANEL_HEIGHT) {
    throw new Error(`roof must have at least ${PANEL_HEIGHT} rows`);
  }
  const width = roof[0].length;
  if (width < PANEL_WIDTH) {
    throw new Error(`roof must have at least ${PANEL_WIDTH} columns`);
  }
  for (const row of roof) {
    if (!Array.isArray(row) || row.length !== width) {
      throw new Error('roof rows must all be arrays of equal length');
    }
    for (const value of row) {
      if (typeof value !== 'number' || !Number.isFinite(value)) {
        throw new Error('roof values must be finite numbers');
      }
    }
  }
  return width;
}

function sunlightAt(roof, row, col) {
  let total = 0;
  for (let r = row; r < row + PANEL_HEIGHT; r += 1) {
    for (let c = col; c < col + PANEL_WIDTH; c += 1) {
      total += roof[r][c];
    }
  }
  return total;
}

function place(roof) {
  const width = validateRoof(roof);
  const lastRow = roof.length - PANEL_HEIGHT;
  const lastCol = width - PANEL_WIDTH;
  let best = [0, 0];
  let bestTotal = -Infinity;
  for (let row = 0; row <= lastRow; row += 1) {
    for (let col = 0; col <= lastCol; col += 1) {
      const total = sunlightAt(roof, row, col);
      if (total > bestTotal) {
        bestTotal = total;
        best = [row, col];
      }
    }
  }
  return best;
}

function describePlacement(roof, corner) {
  const [row, col] = corner;
  const total = sunlightAt(roof, row, col);
  const average = total / (PANEL_HEIGHT * PANEL_WIDTH);
  return `top-left [${row}, ${col}] -> ${total} h total, ${average.toFixed(2)} h/tile`;
}

const sampleRoof = [
  [1, 1, 1, 2, 2, 1],
  [1, 2, 4, 5, 1, 1],
  [1, 3, 6, 7, 2, 1],
  [2, 2, 2, 1, 1, 1],
];
const bestCorner = place(sampleRoof);
console.log(`Best panel: ${describePlacement(sampleRoof, bestCorner)}`);
console.log(`place() returned [${bestCorner.join(', ')}]`);

