const TURN_THRESHOLD_DEGREES = 45;
const TURN_PENALTY = 5;

function validateWaypoints(waypoints) {
  if (!Array.isArray(waypoints) || waypoints.length === 0) {
    throw new TypeError('waypoints must be a non-empty list of coordinate lists');
  }
  const dimension = Array.isArray(waypoints[0]) ? waypoints[0].length : -1;
  if (dimension < 1) {
    throw new TypeError('each waypoint must be a list of at least one coordinate');
  }
  for (const point of waypoints) {
    if (!Array.isArray(point) || point.length !== dimension) {
      throw new TypeError('all waypoints must have the same number of coordinates');
    }
    for (const coordinate of point) {
      if (!Number.isInteger(coordinate)) {
        throw new TypeError('coordinates must be integers');
      }
    }
  }
  return dimension;
}

function vectorBetween(from, to) {
  return from.map((coordinate, index) => to[index] - coordinate);
}

function magnitude(vector) {
  let sumOfSquares = 0;
  for (const component of vector) {
    sumOfSquares += component * component;
  }
  return Math.sqrt(sumOfSquares);
}

function dotProduct(first, second) {
  let total = 0;
  for (let i = 0; i < first.length; i += 1) {
    total += first[i] * second[i];
  }
  return total;
}

function turnAngle(incoming, outgoing) {
  const lengthProduct = magnitude(incoming) * magnitude(outgoing);
  if (lengthProduct === 0) {
    return 0;
  }
  const cosine = Math.min(1, Math.max(-1, dotProduct(incoming, outgoing) / lengthProduct));
  return (Math.acos(cosine) * 180) / Math.PI;
}

function optimize(waypoints) {
  validateWaypoints(waypoints);
  const count = waypoints.length;
  if (count < 2) {
    return 0;
  }
  const segments = [];
  for (let i = 0; i < count; i += 1) {
    const nextIndex = (i + 1) % count;
    segments.push(vectorBetween(waypoints[i], waypoints[nextIndex]));
  }
  let totalEnergy = 0;
  for (const segment of segments) {
    totalEnergy += magnitude(segment);
  }
  for (let i = 0; i < segments.length; i += 1) {
    const previousVector = segments[(i - 1 + segments.length) % segments.length];
    const angle = turnAngle(previousVector, segments[i]);
    if (angle > TURN_THRESHOLD_DEGREES) {
      totalEnergy += TURN_PENALTY;
    }
  }
  return Math.round(totalEnergy);
}

function describeRoute(waypoints) {
  const stops = waypoints.map((point) => `(${point.join(',')})`).join(' -> ');
  const energy = optimize(waypoints);
  return `${stops} -> (${waypoints[0].join(',')}) costs ${energy} energy`;
}

console.log(describeRoute([[0, 0], [10, 0], [10, 10], [0, 10]]));
console.log(describeRoute([[0, 0, 0], [0, 0, 5], [3, 4, 5]]));

