function groupRoomsByClass(rooms) {
  const byClass = new Map();
  for (const room of rooms) {
    const [number, roomClass] = room;
    const pool = byClass.get(roomClass) || [];
    pool.push(number);
    byClass.set(roomClass, pool);
  }
  for (const numbers of byClass.values()) {
    numbers.sort((a, b) => a - b);
  }
  return byClass;
}

function buildPreferenceOrder(requested) {
  const upgrades = [];
  for (let cls = requested; cls <= 3; cls += 1) {
    upgrades.push(cls);
  }
  const downgrades = [];
  for (let cls = requested - 1; cls >= 1; cls -= 1) {
    downgrades.push(cls);
  }
  return upgrades.concat(downgrades);
}

function takeRoom(byClass, requested) {
  const order = buildPreferenceOrder(requested);
  for (const cls of order) {
    const pool = byClass.get(cls);
    if (pool && pool.length > 0) {
      return pool.shift();
    }
  }
  return null;
}

function upgrade(data) {
  const [bookings, rooms] = data;
  const byClass = groupRoomsByClass(rooms);
  const queue = bookings.slice().sort((a, b) => b[1] - a[1]);
  const assignments = [];
  for (const booking of queue) {
    const [name, tier, requested] = booking;
    if (tier < 1 || tier > 5 || requested < 1 || requested > 3) {
      throw new Error(`invalid booking for ${name}`);
    }
    const roomNumber = takeRoom(byClass, requested);
    if (roomNumber !== null) {
      assignments.push([name, roomNumber]);
    }
  }
  return assignments;
}

function report(assignments, guestCount) {
  const lines = assignments.map(([name, number]) => `${name} -> room ${number}`);
  const unplaced = guestCount - assignments.length;
  if (unplaced > 0) {
    lines.push(`${unplaced} guest(s) could not be placed`);
  }
  return lines.join('\n');
}

const bookings = [
  ['john', 5, 1],
  ['mary', 3, 2],
  ['ana', 4, 3],
  ['pete', 1, 1],
];
const availableRooms = [[101, 2], [202, 3], [303, 1]];
const result = upgrade([bookings, availableRooms]);
console.log(report(result, bookings.length));

