const TRAIN = 'T';
const EMPTY = '-';

function parseTrack(layout) {
  const cleaned = layout.replace(/[\s,]+/g, '');
  const blocks = cleaned.split('');
  return blocks.map((block) => {
    const symbol = block.toUpperCase();
    if (symbol !== TRAIN && symbol !== EMPTY) {
      throw new Error(`invalid block symbol: ${block}`);
    }
    return symbol;
  });
}

function trainIndices(tracks) {
  const occupied = [];
  tracks.forEach((block, index) => {
    if (block === TRAIN) {
      occupied.push(index);
    }
  });
  return occupied;
}

function signal(tracks) {
  const occupied = new Set(trainIndices(tracks));
  const colors = [];
  for (let index = 0; index < tracks.length; index += 1) {
    const next = index + 1;
    if (occupied.has(index)) {
      colors.push('red');
    } else if (occupied.has(next)) {
      colors.push('yellow');
    } else {
      colors.push('green');
    }
  }
  return colors;
}

function formatReport(tracks, colors) {
  const width = Math.max(...colors.map((color) => color.length));
  const lines = colors.map((color, index) => {
    const label = `block ${index}`.padEnd(9);
    const state = tracks[index] === TRAIN ? 'occupied' : 'clear';
    return `${label} ${color.padEnd(width)}  (${state})`;
  });
  return lines.join('\n');
}

function main() {
