var TRAIN = 'T';
var EMPTY = '-';

function parseTrack(layout) {
  var cleaned = layout.replace(/[\s,]+/g, '');
  var blocks = cleaned.split('');
  return blocks.map((block) => {
    var symbol = block.toUpperCase();
    if (symbol !== TRAIN && symbol !== EMPTY) {
      throw new Error(`invalid block symbol: ${block}`);
    }
    return symbol;
  });
}

function trainIndices(tracks) {
  var occupied = [];
  tracks.forEach((block, index) => {
    if (block === TRAIN) {
      occupied.push(index);
    }
  });
  return occupied;
}

function signal(tracks) {
  var occupied = new Set(trainIndices(tracks));
  var colors = [];
  for (var index = 0; index < tracks.length; index += 1) {
    var next = index + 1;
    if (occupied.has(index)) {
      colors.push('red');
    } else if (occupied.has(next)) {
      colors.push('yellow');
    } else {
      colors.push('green');
    }
  }
  return colors;
}

function formatReport(tracks, colors) {
  var width = Math.max(...colors.map((color) => color.length));
  var lines = colors.map((color, index) => {
    var label = `block ${index}`.padEnd(9);
    var state = tracks[index] === TRAIN ? 'occupied' : 'clear';
    return `${label} ${color.padEnd(width)}  (${state})`;
  });
  return lines.join('\n');
}

function main() {
  var layouts = ['T-T-', '---T', 'TT--', '-'];
  for (var layout of layouts) {
    var tracks = parseTrack(layout);
    var colors = signal(tracks);
    console.log(`track: ${tracks.join('')}`);
    console.log(formatReport(tracks, colors));
    var clearAhead = colors.filter((color) => color === 'green').length;
    console.log(`green signals: ${clearAhead} of ${colors.length}\n`);
  }
}

main();

