const RING_COUNT = 3;
const POSITIONS = 10;

function normalize(position) {
  const wrapped = position % POSITIONS;
  return wrapped < 0 ? wrapped + POSITIONS : wrapped;
}

function validateActions(actions) {
  if (!Array.isArray(actions)) {
    throw new TypeError('actions must be an array of integers');
  }
  for (const action of actions) {
    if (!Number.isInteger(action)) {
      throw new TypeError(`invalid instruction: ${String(action)}`);
    }
  }
  return actions;
}

function unlock(actions) {
  const rings = new Array(RING_COUNT).fill(0);
  let active = 0;
  for (const action of validateActions(actions)) {
    if (action === 0) {
      active = (active + 1) % RING_COUNT;
    } else {
      rings[active] = normalize(rings[active] + action);
    }
  }
  return rings;
}

function parseCombination(text) {
  const tokens = text.split(/[\s,]+/).filter((token) => token.length > 0);
  return tokens.map((token) => {
    const value = Number(token);
    if (!Number.isInteger(value)) {
      throw new TypeError(`cannot parse instruction: ${token}`);
    }
    return value;
  });
}

function describe(actions) {
  const rings = unlock(actions);
  const dial = rings.join('-');
  const steps = actions.length;
  return `${steps} instruction(s) -> ${dial}`;
}

function main() {
  const samples = [
    [12, 0, -3],
    [0, 0, -1],
    [5, 0, 5, 0, 5, 0, 5],
  ];
  for (const sample of samples) {
    console.log(`[${sample.join(', ')}]: ${describe(sample)}`);
  }

  const typed = '9 0 11 0 -14';
  const parsed = parseCombination(typed);
  console.log(`"${typed}": ${describe(parsed)}`);

  const final = unlock(parsed);
  const sum = final.reduce((total, value) => total + value, 0);
  console.log(`digit sum of final dial: ${sum}`);
}

main();

module.exports = { unlock, parseCombination, describe };

