const PALLET_LIMIT = 100;

function stack(boxes) {
  if (!Array.isArray(boxes)) {
    throw new TypeError('stack expects an array of integer weights');
  }
  const pallets = [];
  let current = [];
  let currentWeight = 0;

  for (const box of boxes) {
    if (!Number.isInteger(box) || box <= 0) {
      throw new RangeError(`invalid box weight: ${box}`);
    }
    if (box > PALLET_LIMIT) {
      if (current.length > 0) {
        pallets.push(current);
        current = [];
        currentWeight = 0;
      }
      pallets.push([box]);
      continue;
    }
    if (currentWeight + box > PALLET_LIMIT) {
      pallets.push(current);
      current = [];
      currentWeight = 0;
    }
    current.push(box);
    currentWeight += box;
  }

  if (current.length > 0) {
    pallets.push(current);
  }
  return pallets;
}

function palletWeight(pallet) {
  return pallet.reduce((sum, box) => sum + box, 0);
}

function describePallet(pallet, index) {
  const weight = palletWeight(pallet);
  const contents = pallet.join(' + ');
  const note = weight > PALLET_LIMIT ? ' (oversized, shipped alone)' : '';
  return `Pallet ${index + 1}: ${contents} = ${weight}${note}`;
}

function report(boxes) {
  const pallets = stack(boxes);
  const lines = pallets.map(describePallet);
  const total = pallets.reduce((sum, pallet) => sum + palletWeight(pallet), 0);
  lines.push(`${pallets.length} pallet(s), ${total} total weight units`);
  return lines.join('\n');
}

function parseWeights(args) {
  return args.flatMap((arg) => arg.split(',')).filter((part) => part.trim() !== '').map((part) => Number(part.trim()));
}

function main(args) {
  const weights = args.length > 0 ? parseWeights(args) : [30, 40, 50, 110];
  console.log(`Boxes: ${weights.join(', ')}`);
  console.log(report(weights));
}

if (require.main === module) {
  main(process.argv.slice(2));
}

module.exports = { stack, report, palletWeight, parseWeights, PALLET_LIMIT };

