'use strict';

const WAKE_LOSS = 0.1;

function validateSpeeds(speeds) {
  if (!Array.isArray(speeds)) {
    throw new TypeError('speeds must be an array of integers');
  }
  for (const speed of speeds) {
    if (!Number.isInteger(speed) || speed < 0) {
      throw new RangeError(`invalid wind speed: ${speed}`);
    }
  }
  return speeds;
}

function effectiveSpeeds(speeds) {
  validateSpeeds(speeds);
  const effective = [];
  let available = null;
  for (const incoming of speeds) {
    const current = available === null ? incoming : Math.min(incoming, available);
    effective.push(current);
    available = current * (1 - WAKE_LOSS);
  }
  return effective;
}

function estimate(speeds) {
  return effectiveSpeeds(speeds).map((speed) => Math.round(speed * speed));
}

function totalPower(powers) {
  return powers.reduce((sum, power) => sum + power, 0);
}

function wakeLossPercent(speeds, powers) {
  const lead = speeds.length > 0 ? speeds[0] : 0;
  const ideal = lead * lead * speeds.length;
  if (ideal === 0) {
    return 0;
  }
  const lost = ideal - totalPower(powers);
  return (lost / ideal) * 100;
}

function formatReport(speeds) {
  const powers = estimate(speeds);
  const effective = effectiveSpeeds(speeds);
  const lines = [' # | incoming | effective | power'];
  effective.forEach((speed, index) => {
    const label = String(index + 1).padStart(2);
    const shown = speed.toFixed(2).padStart(9);
    lines.push(`${label} | ${String(speeds[index]).padStart(8)} | ${shown} | ${String(powers[index]).padStart(5)}`);
  });
  const loss = wakeLossPercent(speeds, powers);
  lines.push(`total power: ${totalPower(powers)} (wake loss ${loss.toFixed(1)}%)`);
  return lines.join('\n');
}

function main() {
  const farms = [[10, 10, 10], [12, 14, 9, 9, 20], [25]];
  const blocks = farms.map((farm) => {
    const header = `incoming ${JSON.stringify(farm)} -> ${JSON.stringify(estimate(farm))}`;
    return `${header}\n${formatReport(farm)}`;
  });
  console.log(blocks.join('\n\n'));
}

main();

module.exports = { estimate, effectiveSpeeds, totalPower, wakeLossPercent, formatReport };

