const MAX_RADIUS = 100;
const ZONE_WIDTH = 10;
const MAX_STRENGTH = 10;

function distanceTo(device) {
  const [x, y] = device;
  return Math.sqrt(x * x + y * y);
}

function signalFor(distance) {
  if (distance > MAX_RADIUS) {
    return 0;
  }
  const zone = Math.max(Math.ceil(distance / ZONE_WIDTH), 1);
  return MAX_STRENGTH + 1 - zone;
}

function readDevice(device, index) {
  if (!Array.isArray(device) || device.length !== 2) {
    throw new TypeError(`device at index ${index} must be a pair of integers`);
  }
  const [x, y] = device;
  if (!Number.isInteger(x) || !Number.isInteger(y)) {
    throw new TypeError(`device at index ${index} has a non-integer coordinate`);
  }
  const distance = distanceTo(device);
  return { x, y, distance, strength: signalFor(distance) };
}

function survey(devices) {
  if (!Array.isArray(devices)) {
    throw new TypeError('devices must be a list of coordinate pairs');
  }
  const readings = [];
  let index = 0;
  for (const device of devices) {
    readings.push(readDevice(device, index));
    index += 1;
  }
  return readings;
}

function measure(devices) {
  let total = 0;
  for (const reading of survey(devices)) {
    total += reading.strength;
  }
  return total;
}

function report(devices) {
  const readings = survey(devices);
  const lines = [];
  let total = 0;
  for (const reading of readings) {
    const label = `(${reading.x}, ${reading.y})`;
    const state = reading.strength === 0 ? 'dropped' : `strength ${reading.strength}`;
    const shown = reading.distance.toFixed(2);
    lines.push(`${label.padEnd(14)} d=${shown.padStart(7)}  ${state}`);
    total += reading.strength;
  }
  lines.push(`total signal strength: ${total}`);
  return lines.join('\n');
}

const network = [[0, 5], [30, 40], [100, 100]];
console.log(report(network));

const dense = [[3, 4], [0, 0], [15, 20], [60, 0], [70, 70], [-45, 12]];
console.log('');
console.log(report(dense));

