function validateSchedule(cars) {
  if (!Array.isArray(cars)) {
    throw new TypeError('simulate expects a list of [arrival, duration] pairs');
  }
  cars.forEach((entry, index) => {
    if (!Array.isArray(entry) || entry.length !== 2) {
      throw new TypeError(`car ${index} must be a pair [arrival, duration]`);
    }
    const [arrival, duration] = entry;
    if (!Number.isInteger(arrival) || !Number.isInteger(duration)) {
      throw new TypeError(`car ${index} must use integer minutes`);
    }
    if (arrival < 0) {
      throw new RangeError(`car ${index} arrives at a negative time`);
    }
    if (duration <= 0) {
      throw new RangeError(`car ${index} must have a positive wash duration`);
    }
  });
}

function orderByArrival(cars) {
  const indexed = cars.map((entry, index) => ({
    index,
    arrival: entry[0],
    duration: entry[1],
  }));
  return indexed.sort((a, b) => a.arrival - b.arrival || a.index - b.index);
}

function simulate(cars) {
  validateSchedule(cars);
  const pending = orderByArrival(cars);
  const departures = new Array(cars.length).fill(0);
  const queue = [];
  let clock = 0;
  let next = 0;

  while (next < pending.length || queue.length > 0) {
    if (queue.length === 0) {
      clock = Math.max(clock, pending[next].arrival);
    }
    while (next < pending.length && pending[next].arrival <= clock) {
      queue.push(pending[next]);
      next += 1;
    }
    const current = queue.shift();
    clock += current.duration;
    departures[current.index] = clock;
  }

  return departures;
}

function formatReport(cars, departures) {
  return cars.map((entry, index) => {
    const [arrival, duration] = entry;
    const departure = departures[index];
    const waited = departure - duration - arrival;
    return `car ${index + 1}: arrives ${arrival}, washes ${duration}, leaves ${departure} (waited ${waited})`;
  });
}

function main() {
  const schedule = [[0, 5], [1, 3], [10, 4], [11, 2]];
  const departures = simulate(schedule);
  console.log(departures.join(', '));
  for (const line of formatReport(schedule, departures)) {
    console.log(line);
  }
  const lastDeparture = departures.reduce((a, b) => Math.max(a, b), 0);
  console.log(`bay closes at minute ${lastDeparture}`);
}

main();

