function msPerBeat(bpm) {
  if (!Number.isInteger(bpm) || bpm <= 0) {
    throw new RangeError(`tempo must be a positive integer bpm, got ${bpm}`);
  }
  return 60000 / bpm;
}

function validateBlock(block, index) {
  if (!Array.isArray(block) || block.length !== 2) {
    throw new TypeError(`tempo block ${index} must be a [bpm, beats] pair`);
  }
  const bpm = block[0];
  const beats = block[1];
  if (!Number.isInteger(beats) || beats < 0) {
    throw new RangeError(`duration in block ${index} must be a non-negative integer, got ${beats}`);
  }
  return { bpm, beats };
}

function click(tempos) {
  if (!Array.isArray(tempos)) {
    throw new TypeError('tempos must be a list of [bpm, beats] pairs');
  }
  const timestamps = [];
  let elapsed = 0;
  for (let i = 0; i < tempos.length; i += 1) {
    const { bpm, beats } = validateBlock(tempos[i], i);
    const interval = msPerBeat(bpm);
    for (let beat = 0; beat < beats; beat += 1) {
      timestamps.push(Math.round(elapsed));
      elapsed += interval;
    }
  }
  return timestamps;
}

function formatTimestamp(ms) {
  const minutes = Math.floor(ms / 60000);
  const seconds = Math.floor((ms % 60000) / 1000);
  const millis = ms % 1000;
  const paddedSeconds = String(seconds).padStart(2, '0');
  const paddedMillis = String(millis).padStart(3, '0');
  return `${minutes}:${paddedSeconds}.${paddedMillis}`;
}

function report(tempos) {
  const clicks = click(tempos);
  const plan = tempos.map((block) => `${block[1]}@${block[0]}bpm`).join(' + ');
  const lines = [`${plan} -> ${clicks.length} beats`];
  for (let i = 0; i < clicks.length; i += 1) {
    lines.push(`  beat ${i + 1}: ${clicks[i]} ms (${formatTimestamp(clicks[i])})`);
  }
  return lines.join('\n');
}

function main() {
  const songs = [
    [[60, 2], [120, 2]],
    [[140, 3], [70, 2], [200, 4]],
  ];
  for (const song of songs) {
    console.log(report(song));
  }
}

main();

module.exports = { click, report, formatTimestamp, msPerBeat };

