const WASTE_AMMONIA_PER_DAY = 2;
const FOOD_AMMONIA_PER_DAY = 1;
const PLANT_NITRATE_UPTAKE = 1;

function validateDays(days) {
  const isInteger = Number.isInteger(days);
  if (!isInteger || days < 0) {
    throw new RangeError(`days must be a non-negative integer, got ${days}`);
  }
  return days;
}

function cycle(days) {
  const total = validateDays(days);
  let ammonia = 0;
  let nitrite = 0;
  let nitrate = 0;

  for (let day = 1; day <= total; day += 1) {
    ammonia += WASTE_AMMONIA_PER_DAY + FOOD_AMMONIA_PER_DAY;

    const ammoniaEaten = Math.min(ammonia, day);
    ammonia -= ammoniaEaten;
    nitrite += ammoniaEaten;

    const nitriteCapacity = Math.floor(day / 2);
    const nitriteEaten = Math.min(nitrite, nitriteCapacity);
    nitrite -= nitriteEaten;
    nitrate += nitriteEaten;

    nitrate = Math.max(0, nitrate - PLANT_NITRATE_UPTAKE);
  }

  return [ammonia, nitrite, nitrate];
}

function formatReport(days) {
  const levels = cycle(days);
  const labels = ['ammonia', 'nitrite', 'nitrate'];
  const parts = labels.map((label, index) => `${label}=${levels[index]}`);
  return `day ${String(days).padStart(3, ' ')}: ${parts.join(', ')}`;
}

function main() {
  const milestones = [1, 3, 7, 30];
  for (const days of milestones) {
    console.log(formatReport(days));
  }

  const [ammonia, nitrite, nitrate] = cycle(3);
  const peakRisk = Math.max(ammonia, nitrite);
  console.log(`after three days the highest toxin level is ${peakRisk}`);
  console.log(`nitrate left for the plants: ${nitrate}`);
}

main();

module.exports = { cycle, formatReport };

