const MIN_GAP = 300;
const MAX_GAP = 500;

function validate(jumps) {
  if (!Array.isArray(jumps)) {
    throw new TypeError('jumps must be an array of millisecond timestamps');
  }
  for (const stamp of jumps) {
    if (!Number.isInteger(stamp)) {
      throw new TypeError(`timestamp ${stamp} is not an integer`);
    }
  }
  for (let i = 1; i < jumps.length; i += 1) {
    const previous = jumps[i - 1];
    if (jumps[i] < previous) {
      throw new RangeError(`timestamps must not decrease: ${previous} then ${jumps[i]}`);
    }
  }
}

function analyze(jumps) {
  validate(jumps);
  if (jumps.length === 0) {
    return [0, null];
  }

  let currentStreak = 1;
  let streakStart = jumps[0];
  let bestStreak = 1;
  let bestStart = jumps[0];

  for (let i = 1; i < jumps.length; i += 1) {
    const gap = jumps[i] - jumps[i - 1];
    if (gap >= MIN_GAP && gap <= MAX_GAP) {
      currentStreak += 1;
    } else {
      currentStreak = 1;
      streakStart = jumps[i];
    }
    if (currentStreak >= bestStreak) {
      bestStreak = currentStreak;
      bestStart = streakStart;
    }
  }

  return [bestStreak, bestStart];
}

function describe(jumps) {
  const [streak, start] = analyze(jumps);
  if (streak === 0) {
    return 'no jumps recorded';
  }
  const seconds = (start / 1000).toFixed(3);
  const word = streak === 1 ? 'jump' : 'jumps';
  return `longest streak: ${streak} ${word}, starting at ${seconds}s (t=${start}ms)`;
}

const contests = [
  ['Ana', [0, 400, 800, 1600, 2000, 2400]],
  ['Bo', [100, 350, 700, 1100, 1450, 1500, 1900]],
  ['Cleo', [0, 1000, 2000]],
  ['Dai', []],
];

for (const [name, jumps] of contests) {
  console.log(`${name}: ${describe(jumps)}`);
}

const totals = contests.map(([, jumps]) => analyze(jumps)[0]);
const champion = Math.max(...totals);
const winners = contests
  .filter((entry, index) => totals[index] === champion)
  .map(([name]) => name);
console.log(`best of the day (${champion}): ${winners.join(', ')}`);

