function crossProduct(origin, a, b) {
  const dx1 = a[0] - origin[0];
  const dy1 = a[1] - origin[1];
  const dx2 = b[0] - a[0];
  const dy2 = b[1] - a[1];
  return dx1 * dy2 - dy1 * dx2;
}

function checkPoints(points) {
  if (!Array.isArray(points)) {
    throw new TypeError("graham expects an array of [x, y] pairs");
  }
  for (const point of points) {
    const isPair = Array.isArray(point) && point.length === 2;
    if (!isPair || !Number.isFinite(point[0]) || !Number.isFinite(point[1])) {
      throw new TypeError("invalid point: " + JSON.stringify(point));
    }
  }
}

function lowestIndex(points) {
  let best = 0;
  for (let i = 1; i < points.length; i += 1) {
    const lower = points[i][1] < points[best][1];
    const tied = points[i][1] === points[best][1] && points[i][0] < points[best][0];
    if (lower || tied) {
      best = i;
    }
  }
  return best;
}

function sortByAngle(pivot, points) {
  const keyed = points.map((point) => {
    const dx = point[0] - pivot[0];
    const dy = point[1] - pivot[1];
    return { point, angle: Math.atan2(dy, dx), dist: dx * dx + dy * dy };
  });
  keyed.sort((a, b) => (a.angle === b.angle ? a.dist - b.dist : a.angle - b.angle));
  return keyed.map((entry) => entry.point);
}

function graham(points) {
  checkPoints(points);
  if (points.length < 3) {
    return points.map((point) => point.slice());
  }
  const start = lowestIndex(points);
  const pivot = points[start];
  const rest = sortByAngle(pivot, points.filter((_point, i) => i !== start));
  const stack = [pivot];
  for (const point of rest) {
    while (stack.length >= 2) {
      const top = stack[stack.length - 1];
      const below = stack[stack.length - 2];
      if (crossProduct(below, top, point) > 0) {
        break;
      }
      stack.pop();
    }
    stack.push(point);
  }
  return stack.map((point) => point.slice());
}

function formatHull(hull) {
  return hull.map(([x, y]) => "(" + x + ", " + y + ")").join(" -> ");
}

const square = [[0, 0], [4, 0], [4, 4], [0, 4], [2, 2]];
const hull = graham(square);
console.log("points: " + formatHull(square));
console.log("hull:   " + formatHull(hull));
console.log("vertices: " + hull.length);

