const INITIAL_RATING = 1200;
const K_FACTOR = 32;
const RATING_SCALE = 400;

function expectedScore(ratingA, ratingB) {
  const exponent = (ratingB - ratingA) / RATING_SCALE;
  return 1 / (1 + Math.pow(10, exponent));
}

function validateMatch(match, index) {
  if (!Array.isArray(match) || match.length !== 3) {
    throw new TypeError(`match ${index} must be an array of three elements`);
  }
  const [playerOne, playerTwo, result] = match;
  if (typeof playerOne !== 'string' || typeof playerTwo !== 'string') {
    throw new TypeError(`match ${index} must name two players as strings`);
  }
  if (result !== 0 && result !== 0.5 && result !== 1) {
    throw new RangeError(`match ${index} result must be 0, 0.5 or 1`);
  }
  return { playerOne, playerTwo, result };
}

function rate(matches) {
  const ratings = new Map();
  const currentRating = (player) => {
    if (!ratings.has(player)) {
      ratings.set(player, INITIAL_RATING);
    }
    return ratings.get(player);
  };

  matches.forEach((match, index) => {
    const { playerOne, playerTwo, result } = validateMatch(match, index);
    const ratingOne = currentRating(playerOne);
    const ratingTwo = currentRating(playerTwo);
    const expectedOne = expectedScore(ratingOne, ratingTwo);
    const expectedTwo = expectedScore(ratingTwo, ratingOne);
    ratings.set(playerOne, ratingOne + K_FACTOR * (result - expectedOne));
