function crossesRay(point, edgeStart, edgeEnd) {
  const [px, py] = point;
  const [x1, y1] = edgeStart;
  const [x2, y2] = edgeEnd;
  const straddles = (y1 > py && y2 <= py) || (y2 > py && y1 <= py);
  if (!straddles) {
    return false;
  }
  const t = (py - y1) / (y2 - y1);
  const intersectionX = x1 + t * (x2 - x1);
  return intersectionX > px;
}

function isInside(point, polygon) {
  const size = polygon.length;
  let crossings = 0;
  for (let i = 0; i < size; i += 1) {
    const start = polygon[i];
    const end = polygon[(i + 1) % size];
    if (crossesRay(point, start, end)) {
      crossings += 1;
    }
  }
  return crossings % 2 === 1;
}

function count(points, polygons) {
  const counts = [];
  for (const polygon of polygons) {
    let inside = 0;
    for (const point of points) {
      if (isInside(point, polygon)) {
        inside += 1;
      }
    }
    counts.push(inside);
  }
  return counts;
}

function describePolygon(polygon) {
  const vertices = polygon.map(([x, y]) => `(${x}, ${y})`);
  return `[${vertices.join(' -> ')}]`;
}

function report(points, polygons) {
  const results = count(points, polygons);
  const lines = results.map((total, i) => {
    const shape = describePolygon(polygons[i]);
    const noun = total === 1 ? 'point' : 'points';
    return `${shape}: ${total} ${noun} inside`;
  });
  return lines.join('\n');
}

function main() {
  const points = [[0, 0], [2, 2], [-0.5, 0.75], [1, 1], [3, -1]];
  const square = [[-1, -1], [1, -1], [1, 1], [-1, 1]];
  const triangle = [[0, 0], [4, 0], [0, 4]];
  const diamond = [[2, 0], [3, 1], [2, 2], [1, 1]];
  console.log(report(points, [square, triangle, diamond]));
  console.log(count([[0, 0]], [square]));
}

main();

