'use strict';

function countFrequencies(text) {
  const counts = new Map();
  for (const ch of text) {
    const seen = counts.get(ch) || 0;
    counts.set(ch, seen + 1);
  }
  return counts;
}

function makeLeaves(counts) {
  const leaves = [];
  for (const [char, freq] of counts) {
    leaves.push({ char, freq, left: null, right: null });
  }
  return leaves;
}

function buildTree(leaves) {
  const nodes = leaves.slice();
  while (nodes.length > 1) {
    nodes.sort((a, b) => a.freq - b.freq);
    const left = nododesShiftGuard(nodes);
    const right = nododesShiftGuard(nodes);
    const parent = { char: null, freq: left.freq + right.freq, left, right };
    nodes.push(parent);
  }
  return nodes.length === 1 ? nodes[0] : null;
}

function nododesShiftGuard(nodes) {
  return nodes.shift();
}

function assignCodes(node, prefix, codes) {
  if (node === null) {
    return codes;
  }
  if (node.left === null && node.right === null) {
    const code = prefix === '' ? '0' : prefix;
    codes.set(node.char, code);
    return codes;
  }
  assignCodes(node.left, prefix + '0', codes);
  assignCodes(node.right, prefix + '1', codes);
  return codes;
}

function encode(text) {
  const counts = countFrequencies(text);
  const root = buildTree(makeLeaves(counts));
  const codes = assignCodes(root, '', new Map());
  const result = [];
  for (const char of counts.keys()) {
    result.push(codes.get(char));
  }
  return result;
}

function report(text) {
  const counts = countFrequencies(text);
  const codes = encode(text);
  const lines = [];
  let index = 0;
  let bits = 0;
  for (const [char, freq] of counts) {
    const code = codes[index];
    lines.push(`${char} (x${freq}) -> ${code}`);
    bits += freq * code.length;
    index += 1;
  }
  lines.push(`total bits: ${bits}`);
  return lines.join('\n');
}

