const OPERATORS = {
  '+': (left, right) => left + right,
  '-': (left, right) => left - right,
  '*': (left, right) => left * right,
  '/': (left, right) => left / right
};

function tokenize(expression) {
  const pieces = expression.split(' ');
  return pieces.filter(piece => piece.length > 0);
}

function applyOperator(stack, token) {
  const operation = OPERATORS[token];
  const right = stack.pop();
  const left = stack.pop();
  if (left === undefined || right === undefined) {
    throw new Error(`not enough operands for "${token}"`);
  }
  stack.push(operation(left, right));
}

function evaluateOne(expression) {
  const stack = [];
  for (const token of tokenize(expression)) {
    if (Object.prototype.hasOwnProperty.call(OPERATORS, token)) {
      applyOperator(stack, token);
    } else {
      const value = Number.parseFloat(token);
      if (Number.isNaN(value)) {
        throw new Error(`invalid token "${token}" in "${expression}"`);
      }
      stack.push(value);
    }
  }
  if (stack.length !== 1) {
    throw new Error(`malformed expression "${expression}"`);
  }
  return stack[0];
}

function evaluate(expressions) {
  return expressions.map(evaluateOne);
}

function formatResult(expression, value) {
  const rounded = Math.round(value * 1e6) / 1e6;
  const text = Number.isInteger(rounded) ? String(rounded) : rounded.toFixed(6);
  return `${expression} => ${text}`;
}

function report(expressions) {
  const results = evaluate(expressions);
  const lines = expressions.map((expression, index) => formatResult(expression, results[index]));
  return lines.join('\n');
}

if (require.main === module) {
  const args = process.argv.slice(2);
  if (args.length > 0) {
    console.log(report(args));
  }
}

module.exports = { evaluate, evaluateOne, report };

