function editDistance(first, second) {
  const rows = first.length + 1;
  const cols = second.length + 1;
  const grid = [];

  for (let r = 0; r < rows; r += 1) {
    const row = new Array(cols).fill(0);
    row[0] = r;
    grid.push(row);
  }

  const topRow = grid[0];
  for (let c = 0; c < cols; c += 1) {
    topRow[c] = c;
  }

  for (let r = 1; r < rows; r += 1) {
    const previous = grid[r - 1];
    const current = grid[r];
    for (let c = 1; c < cols; c += 1) {
      if (first[r - 1] === second[c - 1]) {
        current[c] = previous[c - 1];
      } else {
        const best = Math.min(previous[c], current[c - 1], previous[c - 1]);
        current[c] = best + 1;
      }
    }
  }

  return grid[rows - 1][cols - 1];
}

function matrix(words) {
  const size = words.length;
  const distances = [];

  for (let i = 0; i < size; i += 1) {
    const row = new Array(size).fill(0);
    for (let j = 0; j < i; j += 1) {
      const distance = editDistance(words[i], words[j]);
      row[j] = distance;
      distances[j][i] = distance;
    }
    distances.push(row);
  }

  return distances;
}

function formatMatrix(words, distances) {
  const labelWidth = words.reduce((widest, word) => Math.max(widest, word.length), 0);
  const cellWidth = labelWidth;
  const header = ' '.repeat(labelWidth) + words
    .map((word) => ' ' + word.padStart(cellWidth, ' '))
    .join('');
  const lines = [header];

  for (let i = 0; i < distances.length; i += 1) {
    const label = words[i].padEnd(labelWidth, ' ');
    const cells = distances[i].map((value) => ' ' + String(value).padStart(cellWidth, ' '));
    lines.push(label + cells.join(''));
  }

  return lines.join('\n');
}

const sample = ['kitten', 'sitting'];
console.log(JSON.stringify(matrix(sample)));

const family = ['rosettacode', 'raisethysword', 'kitten', 'sitting', 'saturday', 'sunday'];
console.log(formatMatrix(family, matrix(family)));

