'use strict';

function validateInput(numbers, groups) {
  if (!Array.isArray(numbers)) {
    throw new TypeError('numbers must be an array of numbers');
  }
  const hasNonNumber = numbers.some((value) => typeof value !== 'number' || Number.isNaN(value));
  if (hasNonNumber) {
    throw new TypeError('numbers must contain only finite numeric values');
  }
  if (!Number.isInteger(groups) || groups < 1) {
    throw new RangeError('groups must be a positive integer');
  }
  if (groups > numbers.length) {
    throw new RangeError('groups cannot exceed the amount of numbers');
  }
}

function initialCentroids(numbers, groups) {
  const sorted = [...numbers].sort((a, b) => a - b);
  const step = sorted.length / groups;
  const centroids = [];
  for (let i = 0; i < groups; i += 1) {
    centroids.push(sorted[Math.floor(i * step)]);
  }
  return centroids;
}

function assign(numbers, centroids) {
  const buckets = centroids.map(() => []);
  for (const value of numbers) {
    let best = 0;
    let bestDistance = Math.abs(value - centroids[0]);
    for (let i = 1; i < centroids.length; i += 1) {
      const distance = Math.abs(value - centroids[i]);
      if (distance < bestDistance) {
        bestDistance = distance;
        best = i;
      }
    }
    buckets[best].push(value);
  }
  return buckets;
}

function recentre(buckets, centroids) {
  return centroids.map((centroid, i) => {
    const bucket = buckets[i];
    if (bucket.length === 0) {
      return centroid;
    }
    const total = bucket.reduce((sum, value) => sum + value, 0);
    return total / bucket.length;
  });
}

function cluster(numbers, groups) {
  validateInput(numbers, groups);
  let centroids = initialCentroids(numbers, groups);
  let buckets = assign(numbers, centroids);
  let stable = false;
  while (!stable) {
    centroids = recentre(buckets, centroids);
    const next = assign(numbers, centroids);
    stable = next.every((bucket, i) => bucket.join(',') === buckets[i].join(','));
    buckets = next;
  }
  return buckets;
}

function describe(buckets) {
  const lines = buckets.map((bucket, i) => {
    const mean = bucket.reduce((sum, value) => sum + value, 0) / (bucket.length || 1);
    return `group ${i + 1}: [${bucket.join(', ')}] mean=${mean.toFixed(2)}`;
  });
  return lines.join('\n');
}

const sample = [1, 2, 10];
const result = cluster(sample, 2);
console.log(JSON.stringify(result));
console.log(describe(result));

const spread = cluster([0.5, 0.6, 4.2, 4.4, 9.9, 10.1, 10.3], 3);
console.log(describe(spread));

