const ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
const PAD = "=";

function validate(bytes) {
  if (!Array.isArray(bytes)) {
    throw new TypeError("encode expects an array of integers");
  }
  for (const value of bytes) {
    const isByte = Number.isInteger(value) && value >= 0 && value <= 255;
    if (!isByte) {
      throw new RangeError(`not a byte in range 0..255: ${value}`);
    }
  }
}

function encodeGroup(a, b, c) {
  const triple = (a << 16) | (b << 8) | c;
  let chunk = "";
  for (let shift = 18; shift >= 0; shift -= 6) {
    const index = (triple >>> shift) & 0x3f;
    chunk += ALPHABET[index];
  }
  return chunk;
}

function encode(bytes) {
  validate(bytes);
  let result = "";
  let i = 0;
  while (i + 2 < bytes.length) {
    result += encodeGroup(bytes[i], bytes[i + 1], bytes[i + 2]);
    i += 3;
  }
  const remaining = bytes.length - i;
  if (remaining === 1) {
    const group = encodeGroup(bytes[i], 0, 0);
    result += group.slice(0, 2) + PAD + PAD;
  } else if (remaining === 2) {
    const group = encodeGroup(bytes[i], bytes[i + 1], 0);
    result += group.slice(0, 3) + PAD;
  }
  return result;
}

