function buildAdjacency(graph) {
  const adjacency = new Map();
  for (const [source, target, distance] of graph) {
    if (!adjacency.has(source)) adjacency.set(source, []);
    if (!adjacency.has(target)) adjacency.set(target, []);
    adjacency.get(source).push({ node: target, distance });
    adjacency.get(target).push({ node: source, distance });
  }
  return adjacency;
}

function closestUnvisited(unvisited, distances) {
  let best = null;
  let bestDistance = Infinity;
  for (const point of unvisited) {
    const known = distances.get(point);
    if (known < bestDistance) {
      bestDistance = known;
      best = point;
    }
  }
  return best;
}

function rebuildPath(previous, start, end) {
  const path = [end];
  let cursor = end;
  while (cursor !== start) {
    if (!previous.has(cursor)) return [];
    cursor = previous.get(cursor);
    path.unshift(cursor);
  }
  return path;
}

function navigate(graph, start, end) {
  const adjacency = buildAdjacency(graph);
  if (!adjacency.has(start) || !adjacency.has(end)) return [];

  const distances = new Map();
  const previous = new Map();
  const unvisited = [];
  for (const point of adjacency.keys()) {
    distances.set(point, Infinity);
    unvisited.push(point);
  }
  distances.set(start, 0);

  while (unvisited.length > 0) {
    const current = closestUnvisited(unvisited, distances);
    if (current === null || current === end) break;
    unvisited.splice(unvisited.indexOf(current), 1);
    const baseDistance = distances.get(current);
    for (const edge of adjacency.get(current)) {
      const candidate = baseDistance + edge.distance;
      if (candidate < distances.get(edge.node)) {
        distances.set(edge.node, candidate);
        previous.set(edge.node, current);
      }
    }
  }

  return rebuildPath(previous, start, end);
}

function describeRoute(graph, start, end) {
  const path = navigate(graph, start, end);
  if (path.length === 0) return `no route from ${start} to ${end}`;
  return path.join(" -> ");
}

const links = [
  ["Alpha", "Bravo", 4],
  ["Bravo", "Charlie", 3],
  ["Alpha", "Charlie", 10]
];

console.log(navigate(links, "Alpha", "Charlie"));
console.log(describeRoute(links, "Alpha", "Charlie"));

