function buildGrid(first, second) {
    const rows = first.length + 1;
    const cols = second.length + 1;
    const grid = [];
    for (let r = 0; r < rows; r += 1) {
        grid.push(new Array(cols).fill(0));
    }
    for (let r = 1; r < rows; r += 1) {
        const upper = first[r - 1];
        for (let c = 1; c < cols; c += 1) {
            if (upper === second[c - 1]) {
                grid[r][c] = grid[r - 1][c - 1] + 1;
            } else {
                const above = grid[r - 1][c];
                const left = grid[r][c - 1];
                grid[r][c] = above > left ? above : left;
            }
        }
    }
    return grid;
}

function backtrack(first, second, grid) {
    let r = first.length;
    let c = second.length;
    let result = '';
    while (r > 0 && c > 0) {
        if (first[r - 1] === second[c - 1]) {
            result = first[r - 1] + result;
            r -= 1;
            c -= 1;
        } else if (grid[r - 1][c] >= grid[r][c - 1]) {
            r -= 1;
        } else {
            c -= 1;
        }
    }
    return result;
}

function subsequence(strings) {
    if (!Array.isArray(strings) || strings.length !== 2) {
        throw new TypeError('subsequence expects a list of exactly two strings');
    }
    const [first, second] = strings;
    if (typeof first !== 'string' || typeof second !== 'string') {
        throw new TypeError('both elements must be strings');
    }
    const grid = buildGrid(first, second);
    return backtrack(first, second, grid);
}

function report(pair) {
    const common = subsequence(pair);
    const label = pair.map((s) => JSON.stringify(s)).join(' and ');
    return `${label} -> ${JSON.stringify(common)} (length ${common.length})`;
}

function main() {
    const samples = [
        ['abc', 'ac'],
        ['thisisatest', 'testing123testing'],
        ['1234', '1224533324'],
        ['abcdef', ''],
    ];
    for (const pair of samples) {
        console.log(report(pair));
    }
}

main();

