const DAMPING = 0.85;

function collectPages(links) {
  const pages = new Set();
  for (const [source, target] of links) {
    pages.add(source);
    pages.add(target);
  }
  return Array.from(pages);
}

function buildGraph(links, pages) {
  const incoming = new Map();
  const outgoing = new Map();
  for (const page of pages) {
    incoming.set(page, []);
    outgoing.set(page, 0);
  }
  for (const [source, target] of links) {
    incoming.get(target).push(source);
    outgoing.set(source, outgoing.get(source) + 1);
  }
  return { incoming, outgoing };
}

function step(ranks, incoming, outgoing, total) {
  const next = new Map();
  const base = (1 - DAMPING) / total;
  for (const [page, sources] of incoming) {
    let inflow = 0;
    for (const source of sources) {
      const degree = outgoing.get(source);
      if (degree > 0) {
        inflow += ranks.get(source) / degree;
      }
    }
    next.set(page, DAMPING * inflow + base);
  }
  return next;
}

function rank(links, iterations) {
  const pages = collectPages(links);
  const total = pages.length;
  if (total === 0) {
    return [];
  }
  const { incoming, outgoing } = buildGraph(links, pages);
  let ranks = new Map(pages.map((page) => [page, 1 / total]));
  for (let i = 0; i < iterations; i += 1) {
    ranks = step(ranks, incoming, outgoing, total);
  }
  const result = Array.from(ranks.entries());
  result.sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
  return result;
}

function formatRanking(ranking) {
  const lines = ranking.map(([page, score], index) => {
    const position = String(index + 1).padStart(2, " ");
    return `${position}. ${page.padEnd(12, " ")} ${score.toFixed(6)}`;
  });
  return lines.join("\n");
}

function main() {
  const simple = rank([["page1", "page2"]], 1);
  console.log(formatRanking(simple));

  const web = [
    ["home", "about"],
    ["home", "products"],
    ["about", "home"],
    ["products", "home"],
    ["products", "about"],
    ["contact", "home"],
  ];
  const ranking = rank(web, 30);
  console.log(formatRanking(ranking));

  const totalMass = ranking.reduce((sum, [, score]) => sum + score, 0);
  console.log(`total rank mass: ${totalMass.toFixed(6)}`);
}

main();

