  for (var [page, sources] of incoming) {
    var inflow = 0;
    for (var source of sources) {
      var degree = outgoing.get(source);
      if (degree > 0) {
        inflow += ranks.get(source) / degree;
      }
    }
    next.set(page, DAMPING * inflow + base);
  }
  return next;
}

function rank(links, iterations) {
  var pages = collectPages(links);
  var total = pages.length;
  if (total === 0) {
    return [];
  }
  var { incoming, outgoing } = buildGraph(links, pages);
  var ranks = new Map(pages.map((page) => [page, 1 / total]));
  for (var i = 0; i < iterations; i += 1) {
    ranks = step(ranks, incoming, outgoing, total);
  }
  var result = Array.from(ranks.entries());
  result.sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
  return result;
}

function formatRanking(ranking) {
  var lines = ranking.map(([page, score], index) => {
    var position = String(index + 1).padStart(2, " ");
    return `${position}. ${page.padEnd(12, " ")} ${score.toFixed(6)}`;
  });
  return lines.join("\n");
}

function main() {
  var simple = rank([["page1", "page2"]], 1);
  console.log(formatRanking(simple));

  var web = [
    ["home", "about"],
    ["home", "products"],
    ["about", "home"],
    ["products", "home"],
    ["products", "about"],
    ["contact", "home"],
  ];
  var ranking = rank(web, 30);
  console.log(formatRanking(ranking));

  var totalMass = ranking.reduce((sum, [, score]) => sum + score, 0);
  console.log(`total rank mass: ${totalMass.toFixed(6)}`);
}

main();

