function inBounds(point, width, height) {
  const [x, y] = point;
  return x >= 0 && x < width && y >= 0 && y < height;
}

function samePoint(a, b) {
  return a[0] === b[0] && a[1] === b[1];
}

function findFoodIndex(food, head) {
  for (let i = 0; i < food.length; i += 1) {
    if (samePoint(food[i], head)) {
      return i;
    }
  }
  return -1;
}

function tick(state, direction) {
  const [width, height, body, food] = state;
  const head = body[0];
  const [dx, dy] = direction;
  const newHead = [head[0] + dx, head[1] + dy];

  if (!inBounds(newHead, width, height)) {
    return [];
  }
  if (body.some((segment) => samePoint(segment, newHead))) {
    return [];
  }

  const eatenIndex = findFoodIndex(food, newHead);
  let nextFood = food;
  let nextBody = body;

  if (eatenIndex >= 0) {
    nextFood = food.filter((_item, index) => index !== eatenIndex);
  } else {
    nextBody = body.slice(0, body.length - 1);
  }

  return [width, height, [newHead, ...nextBody], nextFood];
}

function describe(state) {
  if (state.length === 0) {
    return 'game over';
  }
  const [width, height, body, food] = state;
  const segments = body.map((segment) => `(${segment[0]},${segment[1]})`).join(' ');
  const meals = food.map((item) => `(${item[0]},${item[1]})`).join(' ') || 'none';
  return `${width}x${height} snake[${body.length}]: ${segments} | food: ${meals}`;
}

function main() {
  const start = [10, 10, [[5, 5], [4, 5], [3, 5]], [[6, 5], [1, 1]]];
  const right = [1, 0];
  const afterMeal = tick(start, right);
  console.log(describe(start));
  console.log(describe(afterMeal));

  let current = afterMeal;
  const path = [[1, 0], [0, 1], [0, 1], [-1, 0]];
  for (const step of path) {
    current = tick(current, step);
    console.log(describe(current));
  }

  const cornered = [3, 3, [[2, 1], [1, 1]], []];
  console.log(describe(tick(cornered, [1, 0])));

  const biting = [8, 8, [[4, 4], [4, 5], [3, 5], [3, 4]], []];
  console.log(describe(tick(biting, [0, 1])));
}

main();

