const LINES = [
  [0, 1, 2], [3, 4, 5], [6, 7, 8],
  [0, 3, 6], [1, 4, 7], [2, 5, 8],
  [0, 4, 8], [2, 4, 6]
];

function opponent(player) {
  return player === 'x' ? 'o' : 'x';
}

function winner(board) {
  for (const line of LINES) {
    const [a, b, c] = line;
    const mark = board[a];
    if (mark && mark === board[b] && mark === board[c]) return mark;
  }
  return null;
}

function emptyIndices(board) {
  const spots = [];
  for (let i = 0; i < board.length; i += 1) {
    if (board[i] === '') spots.push(i);
  }
  return spots;
}

function minimax(board, player, toMove, depth) {
  const won = winner(board);
  if (won) return won === player ? 10 - depth : depth - 10;
  const spots = emptyIndices(board);
  if (spots.length === 0) return 0;
  const maximizing = toMove === player;
  let result = maximizing ? -Infinity : Infinity;
  for (const idx of spots) {
    board[idx] = toMove;
    const value = minimax(board, player, opponent(toMove), depth + 1);
    board[idx] = '';
    result = maximizing ? Math.max(result, value) : Math.min(result, value);
  }
  return result;
}

function best(board, player) {
  if (!Array.isArray(board) || board.length !== 9) {
    throw new Error('board must contain exactly nine cells');
  }
  if (player !== 'x' && player !== 'o') {
    throw new Error('player must be "x" or "o"');
  }
  const working = board.slice();
  let bestIndex = -1;
  let bestScore = -Infinity;
  for (const idx of emptyIndices(working)) {
    working[idx] = player;
    const value = minimax(working, player, opponent(player), 1);
    working[idx] = '';
    if (value > bestScore) {
      bestScore = value;
      bestIndex = idx;
    }
  }
  return bestIndex;
}

function render(board) {
  const rows = [];
  for (let r = 0; r < 3; r += 1) {
    const cells = board.slice(r * 3, r * 3 + 3).map(cell => (cell === '' ? '.' : cell));
    rows.push(cells.join(' '));
  }
  return rows.join('\n');
}

function main() {
  const board = ['x', 'x', '', 'o', 'o', '', '', '', ''];
  const player = 'x';
  const move = best(board, player);
  console.log(render(board));
  console.log(`${player} plays index ${move}`);
}

main();

