const END = 'end';

function buildTrie(words) {
  const root = Object.create(null);
  for (const word of words) {
    let node = root;
    for (const char of word) {
      if (!node[char]) {
        node[char] = Object.create(null);
      }
      node = node[char];
    }
    node[END] = true;
  }
  return root;
}

function findNode(root, prefix) {
  let node = root;
  for (const char of prefix) {
    const next = node[char];
    if (!next) {
      return null;
    }
    node = next;
  }
  return node;
}

function collectWords(node, prefix) {
  const results = [];
  const stack = [[node, prefix]];
  while (stack.length > 0) {
    const [current, accumulated] = stack.pop();
    if (current[END]) {
      results.push(accumulated);
    }
    const chars = Object.keys(current).filter((key) => key !== END);
    for (let i = chars.length - 1; i >= 0; i -= 1) {
      const char = chars[i];
      stack.push([current[char], accumulated + char]);
    }
  }
  return results;
}

function complete(words, prefix) {
  const root = buildTrie(words);
  const start = findNode(root, prefix);
  if (!start) {
    return [];
  }
  return collectWords(start, prefix);
}

function formatReport(prefix, matches) {
  if (matches.length === 0) {
    return `No vocabulary word starts with "${prefix}".`;
  }
  const listing = matches.join(', ');
  return `${matches.length} match(es) for "${prefix}": ${listing}`;
}

function main() {
  const vocabulary = ['apple', 'apply', 'banana'];
  const queries = ['app', 'ban', 'cat'];
  for (const query of queries) {
    const matches = complete(vocabulary, query);
    console.log(formatReport(query, matches));
  }
}

main();

