function validateInputs(items, weights) {
  if (!Array.isArray(items) || !Array.isArray(weights)) {
    throw new TypeError('items and weights must both be arrays');
  }
  if (items.length !== weights.length) {
    throw new RangeError('items and weights must have the same length');
  }
  for (let i = 0; i < weights.length; i += 1) {
    const weight = weights[i];
    if (typeof weight !== 'number' || !Number.isFinite(weight) || weight <= 0) {
      throw new RangeError(`weight for "${items[i]}" must be a positive finite number`);
    }
  }
}

function shuffle(items, weights) {
  validateInputs(items, weights);

  const remainingItems = items.slice();
  const remainingWeights = weights.slice();
  const result = [];

  while (remainingItems.length > 0) {
    let total = 0;
    for (const weight of remainingWeights) {
      total += weight;
    }

    const target = Math.random() * total;
    let running = 0;
    let chosen = remainingItems.length - 1;

    for (let i = 0; i < remainingItems.length; i += 1) {
      running += remainingWeights[i];
      if (running > target) {
        chosen = i;
        break;
      }
    }

    const [picked] = remainingItems.splice(chosen, 1);
    remainingWeights.splice(chosen, 1);
    result.push(picked);
  }

  return result;
}

function tally(items, weights, trials) {
  const counts = new Map();
  for (let run = 0; run < trials; run += 1) {
    const order = shuffle(items, weights).join(',');
    counts.set(order, (counts.get(order) || 0) + 1);
  }
  return counts;
}

function report(counts, trials) {
  const lines = [];
  const ordered = [...counts.entries()].sort((a, b) => b[1] - a[1]);
  for (const [order, count] of ordered) {
    const share = ((count / trials) * 100).toFixed(1);
    lines.push(`[${order}] ${count} times (${share}%)`);
  }
  return lines.join('\n');
}

const items = ['a', 'b'];
const weights = [90, 10];
const trials = 10000;

console.log(shuffle(items, weights).join(', '));
console.log(report(tally(items, weights, trials), trials));

