const BASE32 = '0123456789bcdefghjkmnpqrstuvwxyz';

function geohash(latitude, longitude, precision) {
  const lat = Number(latitude);
  const lon = Number(longitude);
  const length = Math.trunc(precision);

  if (!Number.isFinite(lat) || lat < -90 || lat > 90) {
    throw new RangeError(`latitude out of range: ${latitude}`);
  }
  if (!Number.isFinite(lon) || lon < -180 || lon > 180) {
    throw new RangeError(`longitude out of range: ${longitude}`);
  }
  if (length < 1) {
    throw new RangeError(`precision must be at least 1: ${precision}`);
  }

  const latRange = { low: -90.0, high: 90.0 };
  const lonRange = { low: -180.0, high: 180.0 };
  let useLongitude = true;
  let bitBuffer = 0;
  let bitCount = 0;
  let hash = '';

  while (hash.length < length) {
    const range = useLongitude ? lonRange : latRange;
    const coordinate = useLongitude ? lon : lat;
    const middle = (range.low + range.high) / 2;
    let bit = 0;

    if (coordinate > middle) {
      bit = 1;
      range.low = middle;
    } else {
      range.high = middle;
    }

    bitBuffer = (bitBuffer << 1) | bit;
    bitCount += 1;
    useLongitude = !useLongitude;

    if (bitCount === 5) {
      hash += BASE32[bitBuffer];
      bitBuffer = 0;
      bitCount = 0;
    }
  }

  return hash;
}

function describe(latitude, longitude, precision) {
  const hash = geohash(latitude, longitude, precision);
  const lat = latitude.toFixed(4);
  const lon = longitude.toFixed(4);
  return `${lat}, ${lon} @ ${precision} -> ${hash}`;
}

function main() {
  const places = [
    { name: 'Null Island', latitude: 0.0, longitude: 0.0, precision: 1 },
    { name: 'Eiffel Tower', latitude: 48.8582, longitude: 2.2945, precision: 9 },
    { name: 'Sydney Opera House', latitude: -33.8568, longitude: 151.2153, precision: 8 },
    { name: 'Christ the Redeemer', latitude: -22.9519, longitude: -43.2105, precision: 7 }
  ];

  const width = places.reduce((widest, place) => Math.max(widest, place.name.length), 0);

  for (const place of places) {
    const label = place.name.padEnd(width);
    const report = describe(place.latitude, place.longitude, place.precision);
    console.log(`${label}  ${report}`);
  }
}

main();

