const LEVELS = 256;
const MAX_LEVEL = 255;

function buildHistogram(pixels) {
  const histogram = new Array(LEVELS).fill(0);
  for (const pixel of pixels) {
    histogram[pixel] += 1;
  }
  return histogram;
}

function cumulativeSums(histogram) {
  const cumulative = new Array(LEVELS).fill(0);
  let running = 0;
  for (let level = 0; level < LEVELS; level += 1) {
    running += histogram[level];
    cumulative[level] = running;
  }
  return cumulative;
}

function minimumNonZero(cumulative) {
  for (const total of cumulative) {
    if (total > 0) {
      return total;
    }
  }
  return 0;
}

function buildMapping(cumulative, pixelCount) {
  const minimum = minimumNonZero(cumulative);
  const denominator = pixelCount - minimum;
  const mapping = new Array(LEVELS).fill(0);
  if (denominator <= 0) {
    return mapping;
  }
  for (let level = 0; level < LEVELS; level += 1) {
    const shifted = cumulative[level] - minimum;
    mapping[level] = Math.round((shifted * MAX_LEVEL) / denominator);
  }
  return mapping;
}

function equalize(pixels) {
  if (!Array.isArray(pixels)) {
    throw new TypeError('pixels must be an array of integers');
  }
  for (const pixel of pixels) {
    const valid = Number.isInteger(pixel) && pixel >= 0 && pixel <= MAX_LEVEL;
    if (!valid) {
      throw new RangeError(`pixel out of range: ${pixel}`);
    }
  }
  const histogram = buildHistogram(pixels);
  const cumulative = cumulativeSums(histogram);
  const mapping = buildMapping(cumulative, pixels.length);
  return pixels.map((pixel) => mapping[pixel]);
}

function describe(label, pixels) {
  const equalized = equalize(pixels);
  const distinct = new Set(equalized).size;
  let brightest = 0;
  for (const pixel of equalized) {
    if (pixel > brightest) {
      brightest = pixel;
    }
  }
  return `${label}: ${equalized.join(',')} (levels=${distinct}, max=${brightest})`;
}

const flatImage = new Array(6).fill(17);
const gradientImage = [0, 0, 32, 64, 64, 128, 200, 255];
console.log(describe('flat dark image', flatImage));
console.log(describe('gradient image', gradientImage));

module.exports = { equalize, buildHistogram, cumulativeSums, buildMapping };

