const PRECEDENCE = { '+': 1, '-': 1, '*': 2, '/': 2 };

function isOperator(token) {
  return Object.prototype.hasOwnProperty.call(PRECEDENCE, token);
}

function isNumber(token) {
  return /^\d+(\.\d+)?$/.test(token);
}

function convert(expression) {
  const output = [];
  const stack = [];

  for (const token of expression) {
    if (isNumber(token)) {
      output.push(token);
    } else if (token === '(') {
      stack.push(token);
    } else if (token === ')') {
      let top = stack.pop();
      while (top !== undefined && top !== '(') {
        output.push(top);
        top = stack.pop();
      }
      if (top === undefined) {
        throw new Error('Unbalanced parentheses: extra ")"');
      }
    } else if (isOperator(token)) {
      const current = PRECEDENCE[token];
      while (stack.length > 0) {
        const top = stack[stack.length - 1];
        if (!isOperator(top) || PRECEDENCE[top] < current) {
          break;
        }
        output.push(stack.pop());
      }
      stack.push(token);
    } else {
      throw new Error(`Unrecognised token: ${token}`);
    }
  }

  while (stack.length > 0) {
    const remaining = stack.pop();
    if (remaining === '(') {
      throw new Error('Unbalanced parentheses: extra "("');
    }
    output.push(remaining);
  }

  return output;
}

function tokenize(text) {
  const matches = text.match(/\d+(?:\.\d+)?|[+\-*/()]/g);
  if (matches === null) {
    throw new Error('No tokens found in input');
  }
  return matches;
}

function report(text) {
  const tokens = tokenize(text);
  const rpn = convert(tokens);
  return `${tokens.join(' ')}  ->  ${rpn.join(' ')}`;
}

const formulas = [
  '3 + 4',
  '3 + 4 * 2',
  '(3 + 4) * 2',
  '10 / 5 - 2 * (1 + 1)'
];

for (const formula of formulas) {
  console.log(report(formula));
}

