function toSet(items) {
  const unique = new Set();
  for (const item of items) {
    unique.add(item);
  }
  return unique;
}

function intersectionSize(a, b) {
  const [small, large] = a.size <= b.size ? [a, b] : [b, a];
  let shared = 0;
  for (const value of small) {
    if (large.has(value)) {
      shared += 1;
    }
  }
  return shared;
}

function similarity(a, b) {
  const shared = intersectionSize(a, b);
  const union = a.size + b.size - shared;
  if (union === 0) {
    return 1;
  }
  return shared / union;
}

function jaccard(sets) {
  if (!Array.isArray(sets)) {
    throw new TypeError('jaccard expects a list of lists of strings');
  }
  const collections = sets.map((items, index) => {
    if (!Array.isArray(items)) {
      throw new TypeError(`collection at index ${index} is not a list`);
    }
    return toSet(items);
  });
  const size = collections.length;
  const grid = [];
  for (let row = 0; row < size; row += 1) {
    const scores = new Array(size);
    for (let col = row; col < size; col += 1) {
      scores[col] = similarity(collections[row], collections[col]);
    }
    grid.push(scores);
  }
  for (let row = 0; row < size; row += 1) {
    for (let col = 0; col < row; col += 1) {
      grid[row][col] = grid[col][row];
    }
  }
  return grid;
}

function formatMatrix(matrix, digits = 2) {
  const lines = matrix.map((row) => {
    const cells = row.map((score) => score.toFixed(digits));
    return cells.join('  ');
  });
  return lines.join('\n');
}

function main() {
  const collections = [
    ['apple', 'banana'],
    ['banana', 'cherry'],
    ['apple', 'banana', 'cherry'],
    [],
  ];
  const matrix = jaccard(collections);
  console.log(formatMatrix(matrix));
}

main();

module.exports = { jaccard, formatMatrix };

