const REAL_MIN = -2;
const REAL_MAX = 1;
const IMAG_MIN = -1;
const IMAG_MAX = 1;
const RAMP = "@%#*+=-:. ";

function scale(index, count, lo, hi) {
  const span = hi - lo;
  const divisor = count > 1 ? count - 1 : 1;
  return lo + (span * index) / divisor;
}

function escapeSteps(cRe, cIm, max) {
  let zRe = 0;
  let zIm = 0;
  let steps = 0;
  while (steps < max) {
    const sqRe = zRe * zRe - zIm * zIm;
    const sqIm = 2 * zRe * zIm;
    zRe = sqRe + cRe;
    zIm = sqIm + cIm;
    steps += 1;
    if (zRe * zRe + zIm * zIm > 4) {
      break;
    }
  }
  return steps;
}

function glyphFor(steps, max) {
  const ratio = steps / max;
  const index = Math.round(ratio * (RAMP.length - 1));
  return RAMP[index];
}

function render(width, height, max) {
  if (!Number.isInteger(width) || !Number.isInteger(height) || !Number.isInteger(max)) {
    throw new TypeError("width, height and max must be integers");
  }
  if (width < 1 || height < 1 || max < 1) {
    throw new RangeError("width, height and max must be positive");
  }
  const rows = [];
  for (let row = 0; row < height; row += 1) {
    const cIm = scale(row, height, IMAG_MIN, IMAG_MAX);
    let line = "";
    for (let col = 0; col < width; col += 1) {
      const cRe = scale(col, width, REAL_MIN, REAL_MAX);
      const steps = escapeSteps(cRe, cIm, max);
      line += glyphFor(steps, max);
    }
    rows.push(line);
  }
  return rows;
}

function frame(rows) {
  const inner = rows.length > 0 ? rows[0].length : 0;
  const border = `+${"-".repeat(inner)}+`;
  const framed = [border];
  for (const line of rows) {
    framed.push(`|${line}|`);
  }
  framed.push(border);
  return framed.join("\n");
}

const picture = render(10, 10, 10);
console.log(frame(picture));

module.exports = { render, escapeSteps, glyphFor, frame };

