function isSafe(board, column) {
  const row = board.length;
  for (let previousRow = 0; previousRow < row; previousRow += 1) {
    const placedColumn = board[previousRow];
    if (placedColumn === column) {
      return false;
    }
    const rowDistance = row - previousRow;
    const columnDistance = Math.abs(placedColumn - column);
    if (rowDistance === columnDistance) {
      return false;
    }
  }
  return true;
}

function queens(size) {
  const results = [];
  const board = [];

  function place(row) {
    if (row === size) {
      results.push(board.slice());
      return;
    }
    for (let column = 0; column < size; column += 1) {
      if (isSafe(board, column)) {
        board.push(column);
        place(row + 1);
        board.pop();
      }
    }
  }

  place(0);
  return results;
}

function renderBoard(solution) {
  const size = solution.length;
  const lines = solution.map((queenColumn) => {
    const cells = [];
    for (let column = 0; column < size; column += 1) {
      cells.push(column === queenColumn ? 'Q' : '.');
    }
    return cells.join(' ');
  });
  return lines.join('\n');
}

function report(size) {
  const solutions = queens(size);
  const parts = [`Board size ${size}: ${solutions.length} solution(s)`];
  solutions.forEach((solution, index) => {
    const label = `Solution ${index + 1}: [${solution.join(', ')}]`;
    parts.push(`${label}\n${renderBoard(solution)}`);
  });
  return parts.join('\n\n');
}

function main() {
  const sizes = [4, 6];
  for (const size of sizes) {
    console.log(report(size));
    console.log('');
  }
  const counts = [1, 2, 3, 4, 5, 6, 7, 8].map((size) => queens(size).length);
  console.log(`Solution counts for sizes 1..8: ${counts.join(', ')}`);
}

main();

