function signedArea(polygon) {
  let total = 0;
  for (let i = 0; i < polygon.length; i += 1) {
    const [x1, y1] = polygon[i];
    const [x2, y2] = polygon[(i + 1) % polygon.length];
    total += x1 * y2 - x2 * y1;
  }
  return total / 2;
}

function crossProduct(edgeStart, edgeEnd, point) {
  const [ex1, ey1] = edgeStart;
  const [ex2, ey2] = edgeEnd;
  const [px, py] = point;
  return (ex2 - ex1) * (py - ey1) - (ey2 - ey1) * (px - ex1);
}

function lineIntersection(a, b, c, d) {
  const [x1, y1] = a;
  const [x2, y2] = b;
  const [x3, y3] = c;
  const [x4, y4] = d;
  const denominator = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4);
  const first = x1 * y2 - y1 * x2;
  const second = x3 * y4 - y3 * x4;
  const x = (first * (x3 - x4) - (x1 - x2) * second) / denominator;
  const y = (first * (y3 - y4) - (y1 - y2) * second) / denominator;
  return [x, y];
}

function intersect(subject, clip) {
  if (subject.length < 3 || clip.length < 3) {
    throw new Error("both polygons need at least three vertices");
  }
  const orientation = signedArea(clip) < 0 ? -1 : 1;
  let output = subject.slice();
  for (let i = 0; i < clip.length && output.length > 0; i += 1) {
    const edgeStart = clip[(i + clip.length - 1) % clip.length];
    const edgeEnd = clip[i];
    const nextOutput = [];
    for (let j = 0; j < output.length; j += 1) {
      const previous = output[(j + output.length - 1) % output.length];
      const current = output[j];
      const currentInside = orientation * crossProduct(edgeStart, edgeEnd, current) >= 0;
      const previousInside = orientation * crossProduct(edgeStart, edgeEnd, previous) >= 0;
      if (currentInside) {
        if (!previousInside) {
          nextOutput.push(lineIntersection(previous, current, edgeStart, edgeEnd));
        }
        nextOutput.push(current);
      } else if (previousInside) {
        nextOutput.push(lineIntersection(previous, current, edgeStart, edgeEnd));
      }
    }
    output = nextOutput;
  }
  return output;
}

function formatPolygon(polygon) {
  const parts = polygon.map(([x, y]) => `(${x}, ${y})`);
  return parts.length > 0 ? parts.join(" ") : "empty";
}

function main() {
  const subject = [[0, 0], [10, 0], [10, 10], [0, 10]];
  const clip = [[5, 5], [15, 5], [15, 15], [5, 15]];
  const region = intersect(subject, clip);
  const area = Math.abs(signedArea(region));
  console.log(`subject: ${formatPolygon(subject)}`);
  console.log(`clip:    ${formatPolygon(clip)}`);
  console.log(`result:  ${formatPolygon(region)}`);
  console.log(`area:    ${area}`);
}

main();

