function crossProduct(edgeStart, edgeEnd, point) {
  var [ex1, ey1] = edgeStart;
  var [ex2, ey2] = edgeEnd;
  var [px, py] = point;
  return (ex2 - ex1) * (py - ey1) - (ey2 - ey1) * (px - ex1);
}

function lineIntersection(a, b, c, d) {
  var [x1, y1] = a;
  var [x2, y2] = b;
  var [x3, y3] = c;
  var [x4, y4] = d;
  var denominator = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4);
  var first = x1 * y2 - y1 * x2;
  var second = x3 * y4 - y3 * x4;
  var x = (first * (x3 - x4) - (x1 - x2) * second) / denominator;
  var y = (first * (y3 - y4) - (y1 - y2) * second) / denominator;
  return [x, y];
}

function intersect(subject, clip) {
  if (subject.length < 3 || clip.length < 3) {
    throw new Error("both polygons need at least three vertices");
  }
  var orientation = signedArea(clip) < 0 ? -1 : 1;
  var output = subject.slice();
  for (var i = 0; i < clip.length && output.length > 0; i += 1) {
    var edgeStart = clip[(i + clip.length - 1) % clip.length];
    var edgeEnd = clip[i];
    var nextOutput = [];
    for (var j = 0; j < output.length; j += 1) {
      var previous = output[(j + output.length - 1) % output.length];
      var current = output[j];
      var currentInside = orientation * crossProduct(edgeStart, edgeEnd, current) >= 0;
      var previousInside = orientation * crossProduct(edgeStart, edgeEnd, previous) >= 0;
      if (currentInside) {
        if (!previousInside) {
          nextOutput.push(lineIntersection(previous, current, edgeStart, edgeEnd));
        }
        nextOutput.push(current);
      } else if (previousInside) {
        nextOutput.push(lineIntersection(previous, current, edgeStart, edgeEnd));
      }
    }
    output = nextOutput;
  }
  return output;
}

function formatPolygon(polygon) {
  var parts = polygon.map(([x, y]) => `(${x}, ${y})`);
  return parts.length > 0 ? parts.join(" ") : "empty";
}

function main() {
  var subject = [[0, 0], [10, 0], [10, 10], [0, 10]];
  var clip = [[5, 5], [15, 5], [15, 15], [5, 15]];
  var region = intersect(subject, clip);
  var area = Math.abs(signedArea(region));
  console.log(`subject: ${formatPolygon(subject)}`);
  console.log(`clip:    ${formatPolygon(clip)}`);
  console.log(`result:  ${formatPolygon(region)}`);
  console.log(`area:    ${area}`);
}

main();

