function maze(width, height) {
  if (width % 2 === 0 || height % 2 === 0) {
    throw new RangeError('width and height must be odd integers');
  }
  const grid = [];
  for (let row = 0; row < height; row++) {
    grid.push(new Array(width).fill('#'));
  }
  const startRow = 1;
  const startCol = 1;
  grid[startRow][startCol] = ' ';
  const stack = [[startRow, startCol]];
  const directions = [[-2, 0], [2, 0], [0, -2], [0, 2]];

  while (stack.length > 0) {
    const [row, col] = stack[stack.length - 1];
    const neighbors = [];
    for (const [dRow, dCol] of directions) {
      const nextRow = row + dRow;
      const nextCol = col + dCol;
      const inBounds = nextRow > 0 && nextRow < height - 1 && nextCol > 0 && nextCol < width - 1;
      if (inBounds && grid[nextRow][nextCol] === '#') {
        neighbors.push([nextRow, nextCol]);
      }
    }
    if (neighbors.length === 0) {
      stack.pop();
      continue;
    }
    const pick = Math.floor(Math.random() * neighbors.length);
    const [chosenRow, chosenCol] = neighbors[pick];
    const wallRow = (row + chosenRow) / 2;
    const wallCol = (col + chosenCol) / 2;
    grid[wallRow][wallCol] = ' ';
    grid[chosenRow][chosenCol] = ' ';
    stack.push([chosenRow, chosenCol]);
  }

  return grid.map((cells) => cells.join(''));
}

function countOpenCells(rows) {
  let open = 0;
  for (const row of rows) {
    for (const cell of row) {
      if (cell === ' ') {
        open++;
      }
    }
  }
  return open;
}

function describe(width, height) {
  const rows = maze(width, height);
  const open = countOpenCells(rows);
  const header = `${width} x ${height} maze (${open} open cells)`;
  const border = '-'.repeat(header.length);
  return [header, border, ...rows].join('\n');
}

const sizes = [[5, 5], [11, 7]];
for (const [width, height] of sizes) {
  console.log(describe(width, height));
  console.log('');
}

module.exports = { maze, countOpenCells, describe };

