function buildIndex(database) {
  const index = new Map();
  for (const entry of database) {
    const [name, calories, protein] = entry;
    index.set(String(name).toLowerCase(), { calories: Number(calories), protein: Number(protein) });
  }
  return index;
}

function calculate(ingredients, database) {
  const index = buildIndex(database);
  let totalCalories = 0;
  let totalProtein = 0;
  let topCalorieName = null;
  let topProteinName = null;
  let topCalorieValue = -Infinity;
  let topProteinValue = -Infinity;

  for (const pair of ingredients) {
    const [quantity, name] = pair;
    const facts = index.get(String(name).toLowerCase());
    if (!facts) {
      throw new Error(`unknown ingredient: ${name}`);
    }
    const amount = Number(quantity);
    const calories = amount * facts.calories;
    const protein = amount * facts.protein;
    totalCalories += calories;
    totalProtein += protein;
    if (calories > topCalorieValue) {
      topCalorieValue = calories;
      topCalorieName = name;
    }
    if (protein > topProteinValue) {
      topProteinValue = protein;
      topProteinName = name;
    }
  }

  return [totalCalories, totalProtein, topCalorieName, topProteinName];
}

function formatReport(recipeName, result) {
  const [calories, protein, topCalorie, topProtein] = result;
  const lines = [
    `Recipe: ${recipeName}`,
    `Total calories: ${calories}`,
    `Total protein: ${protein} g`,
    `Most calories from: ${topCalorie}`,
    `Most protein from: ${topProtein}`
  ];
  return lines.join('\n');
}

const database = [
  ['apple', 50, 1],
  ['oats', 120, 4],
  ['milk', 80, 8],
  ['peanut butter', 190, 7],
  ['honey', 60, 0]
];

const recipe = [
  [2, 'apple'],
  [1.5, 'oats'],
  [2, 'milk'],
  [1, 'peanut butter'],
  [1, 'honey']
];

const summary = calculate(recipe, database);
console.log(formatReport('Breakfast bowl', summary));

const snack = [[3, 'apple'], [1, 'honey']];
console.log(formatReport('Afternoon snack', calculate(snack, database)));

