const ZONES = [
  { limit: 2, points: 10 },
  { limit: 4, points: 8 },
  { limit: 6, points: 6 },
  { limit: 8, points: 4 },
  { limit: 10, points: 2 },
];

const BULLSEYE = 10;

function arrowPoints(distance) {
  if (typeof distance !== 'number' || Number.isNaN(distance) || distance < 0) {
    throw new TypeError(`invalid distance: ${distance}`);
  }
  for (const zone of ZONES) {
    if (distance <= zone.limit) {
      return zone.points;
    }
  }
  return 0;
}

function score(arrows) {
  if (!Array.isArray(arrows)) {
    throw new TypeError('arrows must be an array of distances');
  }
  let total = 0;
  let bullseyes = 0;
  let streak = 0;
  let longestStreak = 0;
  for (const distance of arrows) {
    const points = arrowPoints(distance);
    total += points;
    if (points === BULLSEYE) {
      bullseyes += 1;
      streak += 1;
      if (streak > longestStreak) {
        longestStreak = streak;
      }
    } else {
      streak = 0;
    }
  }
  return [total, bullseyes, longestStreak];
}

function pointsPerArrow(arrows) {
  return arrows.map(arrowPoints);
}

function report(arrows) {
  const [total, bullseyes, longestStreak] = score(arrows);
  const breakdown = pointsPerArrow(arrows).join(', ');
  const lines = [
    `distances: ${arrows.join(', ')}`,
    `points:    ${breakdown}`,
    `total score: ${total}`,
    `bullseyes: ${bullseyes}`,
    `longest bullseye streak: ${longestStreak}`,
  ];
  return lines.join('\n');
}

const rounds = [
  [1, 3, 1, 1, 12],
  [0, 2, 2, 5, 9.5, 10.1],
  [1, 1, 1, 4, 1, 1],
];

for (const arrows of rounds) {
  console.log(report(arrows));
  console.log('');
}

const best = rounds.reduce((leader, arrows) => (score(arrows)[0] > score(leader)[0] ? arrows : leader));
console.log(`best round: ${best.join(', ')} with ${score(best)[0]} points`);

