function validateSplits(splits) {
  if (!Array.isArray(splits) || splits.length === 0) {
    throw new TypeError('splits must be a non-empty array of segment times');
  }
  if (splits.length % 2 !== 0) {
    throw new RangeError('splits must contain an even number of segments');
  }
  for (const time of splits) {
    if (typeof time !== 'number' || !Number.isFinite(time) || time <= 0) {
      throw new RangeError(`invalid segment time: ${time}`);
    }
  }
}

function sum(values) {
  let total = 0;
  for (const value of values) {
    total += value;
  }
  return total;
}

function analyze(splits) {
  validateSplits(splits);
  const total = sum(splits);
  const average = total / splits.length;
  const fastest = Math.min(...splits);
  const slowest = Math.max(...splits);
  const half = splits.length / 2;
  const firstHalf = sum(splits.slice(0, half));
  const secondHalf = sum(splits.slice(half));
  return [total, average, fastest, slowest, secondHalf - firstHalf];
}

function formatMinutes(minutes) {
  const wholeMinutes = Math.floor(minutes);
  const seconds = Math.round((minutes - wholeMinutes) * 60);
  const hours = Math.floor(wholeMinutes / 60);
  const parts = [String(wholeMinutes % 60), String(seconds)];
  const padded = parts.map((part) => part.padStart(2, '0'));
  return `${hours}:${padded.join(':')}`;
}

function report(splits) {
  const [total, average, fastest, slowest, positiveSplit] = analyze(splits);
  const lines = [
    `segments: ${splits.length} x 5 km`,
    `finish time: ${formatMinutes(total)}`,
    `average per segment: ${formatMinutes(average)}`,
    `fastest segment: ${formatMinutes(fastest)}`,
    `slowest segment: ${formatMinutes(slowest)}`
  ];
  const sign = positiveSplit >= 0 ? '+' : '-';
  const label = positiveSplit >= 0 ? 'positive split' : 'negative split';
  lines.push(`${label}: ${sign}${formatMinutes(Math.abs(positiveSplit))}`);
  return lines.join('\n');
}

function main() {
  const marathon = [21.5, 21.2, 21.8, 22.1, 22.4, 23.0, 23.6, 24.3, 10.4];
  const evenSegments = marathon.slice(0, 8);
  console.log(report(evenSegments));
  const finalKick = analyze(evenSegments);
  console.log(`\nraw analysis: ${finalKick.map((n) => n.toFixed(2)).join(', ')}`);
}

main();

module.exports = { analyze, report, formatMinutes };

