const G = 1;

function acceleration(planet, others) {
  const [, position] = planet;
  let total = 0;
  for (const other of others) {
    if (other === planet) continue;
    const [otherMass, otherPosition] = other;
    const offset = otherPosition - position;
    const distanceSquared = offset * offset;
    if (distanceSquared === 0) continue;
    const direction = Math.sign(offset);
    total += direction * G * otherMass / distanceSquared;
  }
  return total;
}

function step(planets) {
  const accelerations = planets.map((planet) => acceleration(planet, planets));
  return planets.map((planet, index) => {
    const [mass, position, velocity] = planet;
    const newVelocity = velocity + accelerations[index];
    return [mass, position + newVelocity, newVelocity];
  });
}

function validate(planets) {
  if (!Array.isArray(planets)) throw new TypeError('planets must be an array');
  planets.forEach((planet, index) => {
    if (!Array.isArray(planet) || planet.length !== 3) {
      throw new TypeError(`planet ${index} must be [mass, position, velocity]`);
    }
    for (const value of planet) {
      if (typeof value !== 'number' || !Number.isFinite(value)) {
        throw new TypeError(`planet ${index} has a non-finite component`);
      }
    }
    const mass = planet[0];
    if (mass <= 0) throw new RangeError(`planet ${index} must have positive mass`);
  });
}

function simulate(planets, time) {
  validate(planets);
  const steps = Math.floor(time);
  if (steps < 0) throw new RangeError('time must not be negative');
  let state = planets.map(([mass, position, velocity]) => [mass, position, velocity]);
  for (let t = 0; t < steps; t += 1) {
    state = step(state);
  }
  return state.map(([, position]) => position);
}

function report(planets, time) {
  const positions = simulate(planets, time);
  const lines = positions.map((position, index) => {
    const mass = planets[index][0];
    const start = planets[index][1];
    const shift = position - start;
    return `planet ${index} (m=${mass}): ${start} -> ${position.toFixed(4)} (drift ${shift.toFixed(4)})`;
  });
  return `after ${Math.floor(time)} units of time\n${lines.join('\n')}`;
}

const system = [
  [100, 0, 0],
  [1, 10, 0],
  [1, -10, 0.5],
  [5, 10, -1],
];

console.log(report(system, 20));
console.log(simulate([[3, 2, 0], [3, 2, 0]], 5).join(', '));

