function padMessage(message, size) {
  const remainder = message.length % size;
  if (remainder === 0) {
    return message;
  }
  const missing = size - remainder;
  return message + '!'.repeat(missing);
}

function splitBlocks(padded, size) {
  const blocks = [];
  for (let start = 0; start < padded.length; start += size) {
    blocks.push(padded.slice(start, start + size));
  }
  return blocks;
}

function blockChecksum(block) {
  let total = 0;
  for (const character of block) {
    total += character.charCodeAt(0);
  }
  return total;
}

function slice(message, size) {
  if (typeof message !== 'string') {
    throw new TypeError('message must be a string');
  }
  if (!Number.isInteger(size) || size <= 0) {
    throw new RangeError('size must be a positive integer');
  }
  const padded = padMessage(message, size);
  const checksums = splitBlocks(padded, size).map((block) => blockChecksum(block) % 256);
  const sum = checksums.reduce((acc, value) => acc + value, 0);
  const average = sum / checksums.length;
  return [padded, checksums, average];
}

function formatReport(message, size) {
  const [padded, checksums, average] = slice(message, size);
  const lines = [`input: "${message}" (block size ${size})`];
  lines.push(`padded: "${padded}"`);
  const listed = checksums.join(', ');
  lines.push(`checksums: [${listed}]`);
  lines.push(`average: ${average.toFixed(2)}`);
  return lines.join('\n');
}

function main() {
  const samples = [
    ['Hello, World!', 5],
    ['abcdefgh', 4],
    ['secret transmission', 7]
  ];
  for (const [message, size] of samples) {
    console.log(formatReport(message, size));
    console.log('');
  }
}

main();

