function amortize(principal, rate, payment) {
  const monthlyRate = rate / 1200;
  const firstInterest = principal * monthlyRate;
  if (payment <= firstInterest) {
    throw new Error(`payment of ${payment} never covers monthly interest of ${firstInterest.toFixed(2)}`);
  }

  let balance = principal;
  let totalInterest = 0;
  let months = 0;
  let finalPayment = payment;

  while (balance > 0) {
    const interest = balance * monthlyRate;
    let reduction = payment - interest;
    if (reduction > balance) {
      reduction = balance;
      finalPayment = reduction + interest;
    }
    balance -= reduction;
    totalInterest += interest;
    months += 1;
  }

  return [months, totalInterest, finalPayment];
}

function schedule(principal, rate, payment) {
  const monthlyRate = rate / 1200;
  const rows = [];
  let balance = principal;

  while (balance > 0) {
    const interest = balance * monthlyRate;
    const reduction = Math.min(payment - interest, balance);
    balance -= reduction;
    rows.push({ month: rows.length + 1, interest, reduction, balance });
  }

  return rows;
}

function formatSummary(principal, rate, payment) {
  const [months, totalInterest, finalPayment] = amortize(principal, rate, payment);
  const years = Math.floor(months / 12);
  const leftover = months % 12;
  const term = leftover === 0 ? `${years} years` : `${years} years, ${leftover} months`;
  const lines = [
    `Loan of ${principal.toFixed(2)} at ${rate}% paid ${payment.toFixed(2)} per month`,
    `Term: ${months} payments (${term})`,
    `Total interest: ${totalInterest.toFixed(2)}`,
    `Final payment: ${finalPayment.toFixed(2)}`,
    `Total paid: ${(principal + totalInterest).toFixed(2)}`
  ];
  return lines.join('\n');
}

function main() {
  const principal = 100000;
  const rate = 6.5;
  const payment = 1000;

  console.log(formatSummary(principal, rate, payment));

  const rows = schedule(principal, rate, payment);
  const preview = rows.slice(0, 3).concat(rows[rows.length - 1]);
  for (const row of preview) {
    const cells = [
      String(row.month).padStart(4),
      row.interest.toFixed(2).padStart(10),
      row.reduction.toFixed(2).padStart(10),
      row.balance.toFixed(2).padStart(12)
    ];
    console.log(cells.join(' '));
  }
}

main();

