function parseDuration(value) {
  const minutes = Number(value);
  if (!Number.isFinite(minutes) || minutes < 0) {
    throw new RangeError(`invalid duration: ${value}`);
  }
  return Math.round(minutes);
}

function build(episodes, limit) {
  const cap = parseDuration(limit);
  const playlist = [];
  let used = 0;
  let skipped = 0;
  for (const [title, duration] of episodes) {
    const length = parseDuration(duration);
    if (used + length > cap) {
      skipped += 1;
      continue;
    }
    playlist.push(title);
    used += length;
  }
  const remaining = cap - used;
  return [playlist, used, skipped, remaining];
}

function formatClock(minutes) {
  const hours = Math.floor(minutes / 60);
  const rest = minutes % 60;
  if (hours === 0) {
    return `${rest}m`;
  }
  return `${hours}h ${String(rest).padStart(2, '0')}m`;
}

function report(episodes, limit) {
  const [playlist, used, skipped, remaining] = build(episodes, limit);
  const lines = playlist.map((title, index) => `${index + 1}. ${title}`);
  lines.push(`Total: ${formatClock(used)} of ${formatClock(limit)}`);
  lines.push(`Skipped: ${skipped}`);
  lines.push(`Remaining: ${formatClock(remaining)}`);
  return lines.join('\n');
}

function main() {
  const episodes = [
    ['Pilot', 42],
    ['The Long Walk', 55],
    ['Interlude', 22],
    ['Double Feature', 88],
    ['Short Cut', 13],
    ['Finale', 47],
  ];
  const limit = 150;
  console.log(report(episodes, limit));

  const tight = build(episodes, 40);
  const [titles, , skippedCount] = tight;
  console.log(`\nWith a 40 minute limit: ${titles.length} kept, ${skippedCount} skipped`);
}

main();

module.exports = { build, report, formatClock };

