function validateInputs(shares, price, dividends) {
  const errors = [];
  if (!Number.isInteger(shares) || shares < 0) {
    errors.push('shares must be a non-negative integer');
  }
  if (typeof price !== 'number' || !(price > 0)) {
    errors.push('price must be a positive number');
  }
  if (!Array.isArray(dividends) || dividends.some((rate) => typeof rate !== 'number' || rate < 0)) {
    errors.push('dividends must be an array of non-negative payout rates');
  }
  return errors;
}

function reinvest(shares, price, dividends) {
  const problems = validateInputs(shares, price, dividends);
  if (problems.length > 0) {
    throw new TypeError(`reinvest: ${problems.join('; ')}`);
  }

  let totalShares = shares;
  let totalDividends = 0;
  let cash = 0;

  for (const rate of dividends) {
    const payout = totalShares * rate;
    totalDividends += payout;
    cash += payout;

    const newShares = Math.floor(cash / price);
    totalShares += newShares;
    cash -= newShares * price;
  }

  return [totalShares, totalDividends, cash];
}

function quarterByQuarter(shares, price, dividends) {
  const rows = [];
  let held = shares;
  let carry = 0;

  dividends.forEach((rate, index) => {
    const payout = held * rate;
    const available = carry + payout;
    const bought = Math.floor(available / price);
    held += bought;
    carry = available - bought * price;
    rows.push({ quarter: index + 1, payout, bought, shares: held, carry });
  });

  return rows;
}

function formatReport(shares, price, dividends) {
  const lines = [`Start: ${shares} shares @ $${price.toFixed(2)}`];
  const rows = quarterByQuarter(shares, price, dividends);

  for (const row of rows) {
    const money = row.payout.toFixed(2);
    const left = row.carry.toFixed(2);
    lines.push(`Q${row.quarter}: paid $${money}, bought ${row.bought}, held ${row.shares}, cash $${left}`);
  }

  const [finalShares, totalCash, leftover] = reinvest(shares, price, dividends);
  lines.push(`Final: ${finalShares} shares, $${totalCash.toFixed(2)} dividends, $${leftover.toFixed(2)} cash`);
  return lines.join('\n');
}

function main() {
  const startingShares = 1000;
  const sharePrice = 45.5;
  const quarterlyRates = [0.62, 0.65, 0.65, 0.7];
  console.log(formatReport(startingShares, sharePrice, quarterlyRates));

  const summary = reinvest(startingShares, sharePrice, quarterlyRates);
  console.log(summary);
}

main();

