function validateDimensions(rows, seats) {
  const rowsOk = Number.isInteger(rows) && rows > 0;
  const seatsOk = Number.isInteger(seats) && seats > 0;
  if (!rowsOk || !seatsOk) {
    throw new RangeError('rows and seats must be positive integers');
  }
}

function validateGroups(groups) {
  if (!Array.isArray(groups)) {
    throw new TypeError('groups must be an array of group sizes');
  }
  for (const size of groups) {
    if (!Number.isInteger(size) || size <= 0) {
      throw new RangeError(`invalid group size: ${size}`);
    }
  }
}

function findRowForGroup(available, size) {
  for (let row = 0; row < available.length; row += 1) {
    if (available[row] >= size) {
      return row;
    }
  }
  return -1;
}

function optimize(groups, rows, seats) {
  validateDimensions(rows, seats);
  validateGroups(groups);

  const available = new Array(rows).fill(seats);
  let seated = 0;
  let turnedAway = 0;

  for (const size of groups) {
    const row = findRowForGroup(available, size);
    if (row === -1) {
      turnedAway += 1;
    } else {
      available[row] -= size;
      seated += 1;
    }
  }

  return [seated, turnedAway, available];
}

function report(groups, rows, seats) {
  const [seated, turnedAway, remaining] = optimize(groups, rows, seats);
  const totalFree = remaining.reduce((sum, free) => sum + free, 0);
  const capacity = rows * seats;
  const occupancy = ((capacity - totalFree) / capacity) * 100;
  const lines = [
    `Theater: ${rows} rows x ${seats} seats (${capacity} places)`,
    `Groups seated: ${seated}`,
    `Groups turned away: ${turnedAway}`,
    `Occupancy: ${occupancy.toFixed(1)}%`
  ];
  remaining.forEach((free, index) => {
    const taken = seats - free;
    lines.push(`  Row ${index + 1}: ${taken} taken, ${free} free`);
  });
  return lines.join('\n');
}

const audience = [3, 5, 2, 8, 4, 6, 1, 7, 2, 9, 5, 3];
const rowCount = 5;
const seatsPerRow = 10;
console.log(report(audience, rowCount, seatsPerRow));

const bigParty = [12, 4, 4, 4];
console.log(report(bigParty, 3, 10));

module.exports = { optimize, report };

