var BASE_FEE = 2.0;
var STANDARD_RATE = 0.25;
var REDUCED_RATE = 0.15;
var RATE_THRESHOLD = 50;
var DISCOUNT_STATION_COUNT = 5;
var DISCOUNT_FACTOR = 0.9;

function parseStation(entry, index) {
  if (!Array.isArray(entry) || entry.length < 2) {
    throw new TypeError(`station at index ${index} must be a [name, distance] pair`);
  }
  var [name, rawDistance] = entry;
  var distance = Number(rawDistance);
  if (!Number.isFinite(distance)) {
    throw new TypeError(`station "${name}" has a non-numeric distance`);
  }
  return { name: String(name), distance };
}

function fareForDistance(miles) {
  var standardMiles = Math.min(miles, RATE_THRESHOLD);
  var reducedMiles = Math.max(miles - RATE_THRESHOLD, 0);
  return BASE_FEE + standardMiles * STANDARD_RATE + reducedMiles * REDUCED_RATE;
}

function roundCents(amount) {
  return Math.round(amount * 100) / 100;
}

function compute(stations) {
  if (!Array.isArray(stations) || stations.length < 2) {
    throw new RangeError('a journey needs at least two stations');
  }
  var parsed = stations.map(parseStation);
  var origin = parsed[0];
  var terminus = parsed[parsed.length - 1];
  var totalDistance = Math.abs(terminus.distance - origin.distance);
  var stationCount = parsed.length;
  var fare = fareForDistance(totalDistance);
  if (stationCount > DISCOUNT_STATION_COUNT) {
    fare *= DISCOUNT_FACTOR;
  }
  return [totalDistance, stationCount, roundCents(fare)];
}

function describeJourney(stations) {
  var [miles, count, fare] = compute(stations);
  var first = stations[0][0];
  var last = stations[stations.length - 1][0];
  var money = fare.toFixed(2);
  return `${first} -> ${last}: ${miles} miles, ${count} stations, $${money}`;
}

var shortHop = [['Union', 0], ['Maple', 12], ['Riverside', 31]];
var longHaul = [
  ['Union', 0],
  ['Maple', 12],
  ['Riverside', 31],
  ['Oakfield', 48],
  ['Granite', 64],
  ['Summit', 87],
];

for (var journey of [shortHop, longHaul]) {
  console.log(describeJourney(journey));
}

module.exports = { compute, describeJourney, fareForDistance };

