function expireLots(lots, asOf) {
  let removed = 0;
  const live = [];
  for (const lot of lots) {
    if (asOf - lot.month >= 12) {
      removed += lot.remaining;
    } else {
      live.push(lot);
    }
  }
  return { removed, live };
}

function spendPoints(lots, amount) {
  let outstanding = amount;
  for (const lot of lots) {
    if (outstanding === 0) {
      break;
    }
    const taken = Math.min(lot.remaining, outstanding);
    lot.remaining -= taken;
    outstanding -= taken;
  }
  if (outstanding > 0) {
    throw new RangeError(`spent ${amount} points but only ${amount - outstanding} were available`);
  }
  return amount;
}

function validate(transactions, current) {
  if (!Array.isArray(transactions)) {
    throw new TypeError('transactions must be an array of triplets');
  }
  for (const entry of transactions) {
    if (!Array.isArray(entry) || entry.length !== 3) {
      throw new TypeError('each transaction must be [earned, spent, month]');
    }
    const [earned, spent, month] = entry;
    if (!Number.isFinite(earned) || !Number.isFinite(spent) || !Number.isFinite(month)) {
      throw new TypeError('earned, spent and month must be finite numbers');
    }
    if (earned < 0 || spent < 0) {
      throw new RangeError('earned and spent points must be non-negative');
    }
    if (month > current) {
      throw new RangeError(`transaction in month ${month} is later than current month ${current}`);
    }
  }
}

function expire(transactions, current) {
  validate(transactions, current);
  const ordered = [...transactions].sort((a, b) => a[2] - b[2]);
  let lots = [];
  let expired = 0;
  let spent = 0;
  for (const [earned, used, month] of ordered) {
    const aged = expireLots(lots, month);
    expired += aged.removed;
    lots = aged.live;
    if (earned > 0) {
      lots.push({ month, remaining: earned });
    }
    spent += spendPoints(lots, used);
    lots = lots.filter((lot) => lot.remaining > 0);
  }
  const final = expireLots(lots, current);
  expired += final.removed;
  const active = final.live.reduce((sum, lot) => sum + lot.remaining, 0);
  return [active, expired, spent];
}

function report(transactions, current) {
  const [active, expired, spent] = expire(transactions, current);
  return [
    `month ${current}: ${transactions.length} transactions processed`,
    `  active  : ${active}`,
    `  expired : ${expired}`,
    `  spent   : ${spent}`,
  ].join('\n');
}

const ledger = [
  [100, 0, 1],
  [50, 0, 3],
  [0, 120, 8],
  [200, 0, 14],
  [0, 75, 20],
  [40, 10, 24],
];
console.log(report(ledger, 26));
console.log(report([[500, 0, 12], [0, 200, 18]], 19));

