function findEarliestFree(freeTimes) {
  let bestIndex = 0;
  for (let i = 1; i < freeTimes.length; i += 1) {
    if (freeTimes[i] < freeTimes[bestIndex]) {
      bestIndex = i;
    }
  }
  return bestIndex;
}

function validateInput(customers, baristas) {
  if (!Array.isArray(customers)) {
    throw new TypeError('customers must be an array of preparation times');
  }
  if (!Number.isInteger(baristas) || baristas < 1) {
    throw new RangeError('baristas must be a positive integer');
  }
  for (const time of customers) {
    if (typeof time !== 'number' || !Number.isFinite(time) || time < 0) {
      throw new RangeError(`invalid preparation time: ${time}`);
    }
  }
}

function process(customers, baristas) {
  validateInput(customers, baristas);
  const freeTimes = new Array(baristas).fill(0);
  let maxWait = 0;
  for (const prepTime of customers) {
    const index = findEarliestFree(freeTimes);
    const wait = freeTimes[index];
    if (wait > maxWait) {
      maxWait = wait;
    }
    freeTimes[index] = wait + prepTime;
  }
  const completion = Math.max(...freeTimes);
  return [maxWait, completion];
}

function formatReport(customers, baristas) {
  const [maxWait, completion] = process(customers, baristas);
  const totalWork = customers.reduce((sum, time) => sum + time, 0);
  const utilisation = completion === 0 ? 0 : totalWork / (completion * baristas);
  const lines = [
    `orders: ${customers.length}, baristas: ${baristas}`,
    `longest wait before service: ${maxWait}`,
    `all orders finished at: ${completion}`,
    `barista utilisation: ${(utilisation * 100).toFixed(1)}%`,
  ];
  return lines.join('\n');
}

function main() {
  const morningRush = [4, 2, 7, 3, 5, 1, 6];
  const staffing = [1, 2, 3];
  for (const crew of staffing) {
    console.log(formatReport(morningRush, crew));
    console.log('');
  }
  const single = process([5], 4);
  console.log(`single order with idle staff -> wait ${single[0]}, done ${single[1]}`);
}

main();

module.exports = { process, findEarliestFree, formatReport };

