const HEATER_COST = 3;
const AC_COST = 4;
const IDLE_COST = 1;
const TOLERANCE = 2;

function classify(reading, target) {
  const deviation = reading - target;
  if (deviation < -TOLERANCE) {
    return 'heater';
  }
  if (deviation > TOLERANCE) {
    return 'ac';
  }
  return 'idle';
}

function manage(readings, target) {
  let totalEnergy = 0;
  let heaterHours = 0;
  let acHours = 0;

  for (const reading of readings) {
    const mode = classify(reading, target);
    if (mode === 'heater') {
      heaterHours += 1;
      totalEnergy += HEATER_COST;
    } else if (mode === 'ac') {
      acHours += 1;
      totalEnergy += AC_COST;
    } else {
      totalEnergy += IDLE_COST;
    }
  }

  return [totalEnergy, heaterHours, acHours];
}

function parseReadings(raw) {
  const parts = raw.split(',');
  const readings = [];
  for (const part of parts) {
    const value = Number(part.trim());
    if (!Number.isFinite(value)) {
      throw new RangeError(`not a temperature: "${part.trim()}"`);
    }
    readings.push(value);
  }
  return readings;
}

function report(readings, target) {
  const [totalEnergy, heaterHours, acHours] = manage(readings, target);
  const idleHours = readings.length - heaterHours - acHours;
  const lines = [
    `Target temperature: ${target}`,
    `Hours measured:     ${readings.length}`,
    `Heater on:          ${heaterHours} h`,
    `AC on:              ${acHours} h`,
    `Idle:               ${idleHours} h`,
    `Energy consumed:    ${totalEnergy} units`,
  ];
  return lines.join('\n');
}

function main() {
  const raw = '18, 19.5, 20, 21, 25, 26, 22, 14, 20, 23.5';
  const target = 21;
  const readings = parseReadings(raw);
  console.log(report(readings, target));

  const summary = manage(readings, target);
  console.log(`manage() -> [${summary.join(', ')}]`);
}

main();

module.exports = { manage, classify, parseReadings, report };

