function normalizeBuilding(triplet, index) {
  const [left, right, height] = triplet;
  if (![left, right, height].every(Number.isFinite)) {
    throw new TypeError(`building ${index} must hold three finite numbers`);
  }
  if (right < left) {
    throw new RangeError(`building ${index} has its right edge left of its left edge`);
  }
  if (height < 0) {
    throw new RangeError(`building ${index} has a negative height`);
  }
  return [Math.trunc(left), Math.trunc(right), Math.trunc(height)];
}

function measure(buildings) {
  const plots = buildings.map(normalizeBuilding);
  let width = 0;
  for (const [, right] of plots) {
    if (right > width) {
      width = right;
    }
  }

  const cityHeights = new Array(width).fill(0);
  for (const [left, right, height] of plots) {
    for (let x = left; x < right; x += 1) {
      if (height > cityHeights[x]) {
        cityHeights[x] = height;
      }
    }
  }

  let area = 0;
  let tallest = 0;
  for (const column of cityHeights) {
    area += column;
    if (column > tallest) {
      tallest = column;
    }
  }
  return [area, tallest];
}

function skyline(buildings) {
  const [area, tallest] = measure(buildings);
  const width = buildings.reduce((widest, [, right]) => Math.max(widest, right), 0);
  const rows = [];
  for (let level = tallest; level > 0; level -= 1) {
    let row = '';
    for (let x = 0; x < width; x += 1) {
      const covered = buildings.some(([left, right, height]) => x >= left && x < right && height >= level);
      row += covered ? '#' : ' ';
    }
    rows.push(row.replace(/\s+$/, ''));
  }
  return { area, tallest, picture: rows.join('\n') };
}

const city = [
  [1, 5, 11], [2, 7, 6], [3, 9, 13], [12, 16, 7],
  [14, 25, 3], [19, 22, 18], [23, 29, 13], [24, 28, 4],
];

const report = skyline(city);
console.log(report.picture);
console.log(`total visible area: ${report.area}`);
console.log(`tallest building: ${report.tallest}`);

