const BASE_YIELDS = {
  corn: 150,
  soybeans: 50,
  wheat: 80
};

const DROUGHT_THRESHOLD = 10;
const EXCESS_THRESHOLD = 20;

function adjustedYield(crop, rainfall) {
  const base = BASE_YIELDS[crop];
  if (rainfall < DROUGHT_THRESHOLD) {
    if (crop === 'corn') {
      return base * 0.8;
    }
    if (crop === 'soybeans') {
      return base * 0.9;
    }
  }
  if (rainfall > EXCESS_THRESHOLD && crop === 'wheat') {
    return base * 0.85;
  }
  return base;
}

function normalizeCrop(name) {
  const cleaned = String(name).trim().toLowerCase();
  if (cleaned === 'soybean' || cleaned === 'soy') {
    return 'soybeans';
  }
  return cleaned;
}

function predict(fields, rainfall) {
  const totals = { corn: 0, soybeans: 0, wheat: 0 };
  for (const [rawCrop, acres] of fields) {
    const crop = normalizeCrop(rawCrop);
    if (!(crop in BASE_YIELDS)) {
      throw new Error(`unknown crop type: ${rawCrop}`);
    }
    const planted = Number(acres);
    if (!Number.isFinite(planted) || planted < 0) {
      throw new Error(`invalid acreage for ${crop}: ${acres}`);
    }
    totals[crop] += adjustedYield(crop, rainfall) * planted;
  }
  return [totals.corn, totals.soybeans, totals.wheat];
}

function formatReport(fields, rainfall) {
  const [corn, soybeans, wheat] = predict(fields, rainfall);
  const lines = [`Season rainfall: ${rainfall.toFixed(1)} in`];
  const labels = ['Corn', 'Soybeans', 'Wheat'];
  const amounts = [corn, soybeans, wheat];
  labels.forEach((label, index) => {
    const bushels = Math.round(amounts[index]);
    lines.push(`${label.padEnd(9)} ${bushels.toLocaleString('en-US')} bu`);
  });
  const grandTotal = Math.round(corn + soybeans + wheat);
  lines.push(`Total     ${grandTotal.toLocaleString('en-US')} bu`);
  return lines.join('\n');
}

const farm = [
  ['corn', 120],
  ['soybeans', 80],
  ['wheat', 45],
  ['Corn', 30]
];

for (const season of [8, 15, 24]) {
  console.log(formatReport(farm, season));
  console.log('');
}

