  if (rainfall < DROUGHT_THRESHOLD) {
    if (crop === 'corn') {
      return base * 0.8;
    }
    if (crop === 'soybeans') {
      return base * 0.9;
    }
  }
  if (rainfall > EXCESS_THRESHOLD && crop === 'wheat') {
    return base * 0.85;
  }
  return base;
}

function normalizeCrop(name) {
  var cleaned = String(name).trim().toLowerCase();
  if (cleaned === 'soybean' || cleaned === 'soy') {
    return 'soybeans';
  }
  return cleaned;
}

function predict(fields, rainfall) {
  var totals = { corn: 0, soybeans: 0, wheat: 0 };
  for (var [rawCrop, acres] of fields) {
    var crop = normalizeCrop(rawCrop);
    if (!(crop in BASE_YIELDS)) {
      throw new Error(`unknown crop type: ${rawCrop}`);
    }
    var planted = Number(acres);
    if (!Number.isFinite(planted) || planted < 0) {
      throw new Error(`invalid acreage for ${crop}: ${acres}`);
    }
    totals[crop] += adjustedYield(crop, rainfall) * planted;
  }
  return [totals.corn, totals.soybeans, totals.wheat];
}

function formatReport(fields, rainfall) {
  var [corn, soybeans, wheat] = predict(fields, rainfall);
  var lines = [`Season rainfall: ${rainfall.toFixed(1)} in`];
  var labels = ['Corn', 'Soybeans', 'Wheat'];
  var amounts = [corn, soybeans, wheat];
  labels.forEach((label, index) => {
    var bushels = Math.round(amounts[index]);
    lines.push(`${label.padEnd(9)} ${bushels.toLocaleString('en-US')} bu`);
  });
  var grandTotal = Math.round(corn + soybeans + wheat);
  lines.push(`Total     ${grandTotal.toLocaleString('en-US')} bu`);
  return lines.join('\n');
}

var farm = [
  ['corn', 120],
  ['soybeans', 80],
  ['wheat', 45],
  ['Corn', 30]
];

for (var season of [8, 15, 24]) {
  console.log(formatReport(farm, season));
  console.log('');
}

