const BASE_POINTS = 1000;
const PENALTY_PER_SECOND = 10;
const BONUS_PER_ENEMY = 50;
const SPEED_BONUS = 500;

function scoreAttempt(attempt, par) {
  const [seconds, enemies] = attempt;
  let score = BASE_POINTS - PENALTY_PER_SECOND * seconds + BONUS_PER_ENEMY * enemies;
  if (seconds < par) {
    score += SPEED_BONUS;
  }
  return score;
}

function grade(attempts, par) {
  if (!Array.isArray(attempts) || attempts.length === 0) {
    throw new Error('grade() needs at least one attempt');
  }
  let high = -Infinity;
  let low = Infinity;
  let total = 0;
  for (const attempt of attempts) {
    const score = scoreAttempt(attempt, par);
    if (score > high) {
      high = score;
    }
    if (score < low) {
      low = score;
    }
    total += score;
  }
  const average = total / attempts.length;
  return [high, low, average];
}

function formatReport(attempts, par) {
  const [high, low, average] = grade(attempts, par);
  const lines = attempts.map((attempt, index) => {
    const [seconds, enemies] = attempt;
    const score = scoreAttempt(attempt, par);
    const fast = seconds < par ? ' (speed bonus)' : '';
    return `Attempt ${index + 1}: ${seconds}s, ${enemies} enemies -> ${score}${fast}`;
  });
  lines.push(`High score: ${high}`);
  lines.push(`Low score: ${low}`);
  lines.push(`Average score: ${average.toFixed(1)}`);
  return lines.join('\n');
}

function main() {
  const par = 60;
  const attempts = [
    [45, 6],
    [72, 10],
    [58, 3],
    [90, 14],
  ];
  console.log(formatReport(attempts, par));

  const [high, low] = grade(attempts, par);
  const spread = high - low;
  console.log(`Spread between best and worst run: ${spread}`);
}

main();

module.exports = { grade, scoreAttempt, formatReport };

