function scoreMatch(goalsA, goalsB, overtime) {
  if (goalsA === goalsB) {
    return [1, 1];
  }
  const winnerPoints = overtime ? 2 : 3;
  const loserPoints = overtime ? 1 : 0;
  return goalsA > goalsB ? [winnerPoints, loserPoints] : [loserPoints, winnerPoints];
}

function validateMatch(record, index) {
  if (!Array.isArray(record) || record.length !== 5) {
    throw new Error(`Match ${index} must have exactly five fields`);
  }
  const [teamA, goalsA, teamB, goalsB, overtime] = record;
  if (typeof teamA !== 'string' || typeof teamB !== 'string') {
    throw new Error(`Match ${index} has a non-string team name`);
  }
  if (!Number.isInteger(goalsA) || !Number.isInteger(goalsB) || goalsA < 0 || goalsB < 0) {
    throw new Error(`Match ${index} has invalid goal counts`);
  }
  if (typeof overtime !== 'boolean') {
    throw new Error(`Match ${index} has a non-boolean overtime flag`);
  }
  if (overtime && goalsA === goalsB) {
    throw new Error(`Match ${index} cannot be tied after overtime`);
  }
  return { teamA, goalsA, teamB, goalsB, overtime };
}

function tally(matches) {
  const totals = new Map();
  matches.forEach((record, index) => {
    const { teamA, goalsA, teamB, goalsB, overtime } = validateMatch(record, index);
    const [pointsA, pointsB] = scoreMatch(goalsA, goalsB, overtime);
    totals.set(teamA, (totals.get(teamA) || 0) + pointsA);
    totals.set(teamB, (totals.get(teamB) || 0) + pointsB);
  });
  return totals;
}

function rank(matches) {
  if (!Array.isArray(matches)) {
    throw new Error('matches must be a list of match records');
  }
  const totals = tally(matches);
  const teams = [...totals.keys()];
  teams.sort((left, right) => {
    const diff = totals.get(right) - totals.get(left);
    return diff !== 0 ? diff : left.localeCompare(right);
  });
  return teams;
}

function formatTable(matches) {
  const totals = tally(matches);
  const order = rank(matches);
  const width = order.reduce((longest, team) => Math.max(longest, team.length), 4);
  const lines = order.map((team, position) => {
    const place = String(position + 1).padStart(2, ' ');
    const label = team.padEnd(width, ' ');
    return `${place}. ${label}  ${String(totals.get(team)).padStart(3, ' ')}`;
  });
  return lines.join('\n');
}

const season = [
  ['red', 2, 'blue', 1, false],
  ['blue', 3, 'green', 2, true],
  ['green', 1, 'red', 1, false],
  ['blue', 0, 'red', 4, false],
  ['green', 2, 'blue', 1, false],
];

console.log(formatTable(season));

