function validateInput(groups, capacity) {
  if (!Array.isArray(groups)) {
    throw new TypeError('groups must be an array of group sizes');
  }
  if (!Number.isInteger(capacity) || capacity <= 0) {
    throw new RangeError('capacity must be a positive integer');
  }
  for (const size of groups) {
    if (!Number.isInteger(size) || size <= 0) {
      throw new RangeError(`invalid group size: ${size}`);
    }
    if (size > capacity) {
      throw new RangeError(`group of ${size} cannot fit in a train of ${capacity}`);
    }
  }
}

function dispatch(groups, capacity) {
  validateInput(groups, capacity);
  const trains = [];
  let current = 0;
  for (const size of groups) {
    if (current + size > capacity) {
      trains.push(current);
      current = size;
    } else {
      current += size;
    }
  }
  if (current > 0) {
    trains.push(current);
  }
  return trains;
}

function summarize(trains, capacity) {
  const totalPassengers = trains.reduce((sum, load) => sum + load, 0);
  const seats = trains.length * capacity;
  const emptySeats = seats - totalPassengers;
  const fullest = trains.length > 0 ? Math.max(...trains) : 0;
  return { trains: trains.length, totalPassengers, emptySeats, fullest };
}

function formatReport(groups, capacity) {
  const loads = dispatch(groups, capacity);
  const stats = summarize(loads, capacity);
  const lines = [`capacity ${capacity}, groups [${groups.join(', ')}]`];
  loads.forEach((load, index) => {
    const free = capacity - load;
    lines.push(`train ${index + 1}: ${load} passengers, ${free} seat(s) free`);
  });
  lines.push(
    `${stats.trains} train(s) carried ${stats.totalPassengers} passengers; ` +
    `${stats.emptySeats} empty seat(s), fullest train held ${stats.fullest}`
  );
  return lines.join('\n');
}

function main() {
  const schedules = [
    { groups: [4, 3, 2, 5], capacity: 6 },
    { groups: [2, 2, 2, 2], capacity: 4 },
    { groups: [7, 1, 1, 6, 3], capacity: 7 }
  ];
  for (const schedule of schedules) {
    console.log(formatReport(schedule.groups, schedule.capacity));
    console.log('');
  }
  try {
    dispatch([3, 9], 8);
  } catch (error) {
    console.log(`rejected: ${error.message}`);
  }
}

main();

