function peakAmplitude(samples) {
  let peak = 0;
  for (const sample of samples) {
    const magnitude = Math.abs(sample);
    if (magnitude > peak) {
      peak = magnitude;
    }
  }
  return peak;
}

function validateTrack(samples, target) {
  if (!Array.isArray(samples)) {
    throw new TypeError('samples must be an array of numbers');
  }
  const badIndex = samples.findIndex((s) => typeof s !== 'number' || !Number.isFinite(s));
  if (badIndex !== -1) {
    throw new TypeError(`sample at index ${badIndex} is not a finite number`);
  }
  if (typeof target !== 'number' || !Number.isFinite(target) || target <= 0) {
    throw new RangeError('target must be a positive finite number');
  }
}

function normalize(samples, target) {
  validateTrack(samples, target);
  const peak = peakAmplitude(samples);
  if (peak === 0) {
    return samples.map(() => 0);
  }
  const factor = target / peak;
  return samples.map((sample) => Math.trunc(sample * factor));
}

function gainInDecibels(samples, target) {
  const peak = peakAmplitude(samples);
  if (peak === 0) {
    return -Infinity;
  }
  return 20 * Math.log10(target / peak);
}

function formatReport(name, samples, target) {
  const normalized = normalize(samples, target);
  const gain = gainInDecibels(samples, target);
  const before = peakAmplitude(samples);
  const after = peakAmplitude(normalized);
  const gainText = Number.isFinite(gain) ? `${gain.toFixed(2)} dB` : 'silent track, no gain applied';
  return [
    `Track: ${name}`,
    `  input   : [${samples.join(', ')}]`,
    `  output  : [${normalized.join(', ')}]`,
    `  peak    : ${before} -> ${after} (target ${target})`,
    `  gain    : ${gainText}`,
  ].join('\n');
}

function main() {
  const tracks = [
    { name: 'quiet-sweep', samples: [-10, 5, 20], target: 50 },
    { name: 'loud-clip', samples: [1200, -32000, 15000, 0], target: 32767 },
    { name: 'silence', samples: [0, 0, 0, 0], target: 100 },
  ];
  const reports = tracks.map((track) => formatReport(track.name, track.samples, track.target));
  console.log(reports.join('\n\n'));
}

main();

module.exports = { normalize, peakAmplitude, gainInDecibels, formatReport };

