function validateInputs(blocks, width) {
  if (!Array.isArray(blocks)) {
    throw new TypeError('blocks must be an array of square dimensions');
  }
  const rollWidth = Number(width);
  if (!Number.isFinite(rollWidth) || rollWidth <= 0) {
    throw new RangeError('width must be a positive finite number');
  }
  const sizes = blocks.map((block, index) => {
    const size = Number(block);
    if (!Number.isFinite(size) || size <= 0) {
      throw new RangeError(`block at index ${index} is not a positive size`);
    }
    if (size > rollWidth) {
      throw new RangeError(`block at index ${index} (${size}) exceeds roll width ${rollWidth}`);
    }
    return size;
  });
  return { sizes, rollWidth };
}

function layout(sizes, rollWidth) {
  const rows = [];
  let current = [];
  let used = 0;
  for (const size of sizes) {
    if (used + size > rollWidth) {
      rows.push(current);
      current = [];
      used = 0;
    }
    current.push(size);
    used += size;
  }
  if (current.length > 0) {
    rows.push(current);
  }
  return rows;
}

function rowHeight(row) {
  let tallest = 0;
  for (const size of row) {
    if (size > tallest) {
      tallest = size;
    }
  }
  return tallest;
}

function estimate(blocks, width) {
  const { sizes, rollWidth } = validateInputs(blocks, width);
  return layout(sizes, rollWidth).reduce((total, row) => total + rowHeight(row), 0);
}

function describeLayout(blocks, width) {
  const { sizes, rollWidth } = validateInputs(blocks, width);
  const rows = layout(sizes, rollWidth);
  let total = 0;
  const lines = rows.map((row, index) => {
    const height = rowHeight(row);
    const filled = row.reduce((sum, size) => sum + size, 0);
    total += height;
    return `Row ${index + 1}: [${row.join(', ')}] height ${height}, unused width ${rollWidth - filled}`;
  });
  lines.push(`Total fabric length on a roll of width ${rollWidth}: ${total}`);
  return lines.join('\n');
}

const design = [10, 20, 15, 5];
console.log(describeLayout(design, 30));

const sampler = [12, 12, 12, 36, 6, 6, 18];
console.log(describeLayout(sampler, 36));

