    }
  }
  return tallest;
}

function estimate(blocks, width) {
  var { sizes, rollWidth } = validateInputs(blocks, width);
  return layout(sizes, rollWidth).reduce((total, row) => total + rowHeight(row), 0);
}

function describeLayout(blocks, width) {
  var { sizes, rollWidth } = validateInputs(blocks, width);
  var rows = layout(sizes, rollWidth);
  var total = 0;
  var lines = rows.map((row, index) => {
    var height = rowHeight(row);
    var filled = row.reduce((sum, size) => sum + size, 0);
    total += height;
    return `Row ${index + 1}: [${row.join(', ')}] height ${height}, unused width ${rollWidth - filled}`;
  });
  lines.push(`Total fabric length on a roll of width ${rollWidth}: ${total}`);
  return lines.join('\n');
}

