function validateTables(tables, range) {
  if (!Array.isArray(tables)) {
    throw new TypeError('tables must be an array of distances');
  }
  const cleaned = tables.map((value, index) => {
    const distance = Number(value);
    if (!Number.isFinite(distance) || distance < 0) {
      throw new RangeError(`table ${index} has an invalid distance: ${value}`);
    }
    return distance;
  });
  const walk = Number(range);
  if (!Number.isFinite(walk) || walk < 0) {
    throw new RangeError(`walking range must be a non-negative number: ${range}`);
  }
  return { cleaned, walk };
}

function countFrom(sorted, startIndex, span) {
  const limit = sorted[startIndex] + span;
  let served = 0;
  for (let i = startIndex; i < sorted.length; i += 1) {
    if (sorted[i] > limit) {
      break;
    }
    served += 1;
  }
  return served;
}

function locate(tables, range) {
  const { cleaned, walk } = validateTables(tables, range);
  const sorted = cleaned.slice().sort((a, b) => a - b);
  const span = 2 * walk;
  let best = 0;
  for (let start = 0; start < sorted.length; start += 1) {
    const served = countFrom(sorted, start, span);
    if (served > best) {
      best = served;
    }
  }
  return best;
}

function bestSpot(tables, range) {
  const { cleaned, walk } = validateTables(tables, range);
  const sorted = cleaned.slice().sort((a, b) => a - b);
  const target = locate(sorted, walk);
  for (let start = 0; start < sorted.length; start += 1) {
    if (countFrom(sorted, start, 2 * walk) === target) {
      return sorted[start] + walk;
    }
  }
  return null;
}

function describe(tables, range) {
  const served = locate(tables, range);
  const spot = bestSpot(tables, range);
  const where = spot === null ? 'nowhere' : `${spot} units from the entrance`;
  return `tables [${tables.join(', ')}] with range ${range}: grill at ${where} serves ${served} of ${tables.length}`;
}

function runCli(argv) {
  if (argv.length < 1) {
    return 'usage: grill <range> [table distance ...]';
  }
  const walk = argv[0];
  const tables = argv.slice(1);
  return describe(tables, walk);
}

if (require.main === module) {
  console.log(runCli(process.argv.slice(2)));
}

module.exports = { locate, bestSpot, describe, runCli };

