function stepDuration(current, rate, target) {
  const difference = current - target;
  return difference / rate;
}

function cooldownSchedule(temperature, steps) {
  let current = temperature;
  const schedule = [];
  for (const step of steps) {
    const rate = step[0];
    const target = step[1];
    if (!(rate > 0)) {
      throw new RangeError(`cooling rate must be positive, got ${rate}`);
    }
    if (target >= current) {
      continue;
    }
    const hours = stepDuration(current, rate, target);
    schedule.push({ rate: rate, from: current, to: target, hours: hours });
    current = target;
  }
  return schedule;
}

function cooldown(temperature, steps) {
  const schedule = cooldownSchedule(temperature, steps);
  let total = 0;
  for (const leg of schedule) {
    total += leg.hours;
  }
  return Math.floor(total);
}

function formatSchedule(temperature, steps) {
  const schedule = cooldownSchedule(temperature, steps);
  const lines = [`Firing temperature: ${temperature} deg`];
  if (schedule.length === 0) {
    lines.push('  no valid cooling steps; kiln stays at firing temperature');
    return lines.join('\n');
  }
  let elapsed = 0;
  for (const leg of schedule) {
    elapsed += leg.hours;
    const span = leg.hours.toFixed(2);
    lines.push(
      `  ${leg.from} -> ${leg.to} at ${leg.rate} deg/h : ` +
        `${span} h (elapsed ${elapsed.toFixed(2)} h)`
    );
  }
  const last = schedule[schedule.length - 1];
  lines.push(`Final temperature: ${last.to} deg`);
  lines.push(`Total time: ${Math.floor(elapsed)} h`);
  return lines.join('\n');
}

function main() {
  const firings = [
    { temperature: 1000, steps: [[50, 500], [20, 100]] },
    { temperature: 1200, steps: [[100, 1300], [60, 600], [15, 150]] },
    { temperature: 800, steps: [[40, 900]] }
  ];
  for (const firing of firings) {
    console.log(formatSchedule(firing.temperature, firing.steps));
    console.log(`cooldown() = ${cooldown(firing.temperature, firing.steps)}`);
  }
}

main();

