function validateColor(color, index) {
  if (!Array.isArray(color) || color.length !== 3) {
    throw new TypeError(`Color at position ${index} must be a list of three numbers`);
  }
  for (const channel of color) {
    const isNumber = typeof channel === 'number' && Number.isFinite(channel);
    if (!isNumber || channel < 0 || channel > 255) {
      throw new RangeError(`Color at position ${index} has a channel outside 0..255`);
    }
  }
}

function blend(paints) {
  if (!Array.isArray(paints) || paints.length === 0) {
    throw new TypeError('blend expects a non-empty list of colors');
  }
  const totals = [0, 0, 0];
  paints.forEach((color, index) => {
    validateColor(color, index);
    for (let channel = 0; channel < 3; channel += 1) {
      totals[channel] += color[channel];
    }
  });
  const count = paints.length;
  return totals.map((sum) => Math.round(sum / count));
}

function toHex(color) {
  const digits = color.map((channel) => channel.toString(16).padStart(2, '0'));
  return `#${digits.join('')}`;
}

function describe(color) {
  const [red, green, blue] = color;
  const brightness = Math.round(red * 0.299 + green * 0.587 + blue * 0.114);
  const tone = brightness < 85 ? 'dark' : brightness < 170 ? 'medium' : 'light';
  return `rgb(${red}, ${green}, ${blue}) ${toHex(color)} — ${tone}`;
}

function report(name, paints) {
  const result = blend(paints);
  const sources = paints.map((color) => toHex(color)).join(' + ');
  return `${name}: ${sources} => ${describe(result)}`;
}

const palettes = [
  ['red and blue', [[255, 0, 0], [0, 0, 255]]],
  ['primary trio', [[255, 0, 0], [0, 255, 0], [0, 0, 255]]],
  ['pastels', [[250, 218, 221], [173, 216, 230], [255, 253, 208]]],
  ['single swatch', [[12, 34, 56]]],
];

for (const [name, paints] of palettes) {
  console.log(report(name, paints));
}

