const centerDistance = (a, b) => {
  const dx = a[0] - b[0];
  const dy = a[1] - b[1];
  return Math.sqrt(dx * dx + dy * dy);
};

const overlaps = (a, b) => {
  const reach = a[2] + b[2];
  return centerDistance(a, b) < reach;
};

function validate(sprinklers) {
  if (!Array.isArray(sprinklers)) {
    throw new TypeError('sprinklers must be an array');
  }
  sprinklers.forEach((sprinkler, index) => {
    if (!Array.isArray(sprinkler) || sprinkler.length !== 3) {
      throw new TypeError(`sprinkler ${index} must be [x, y, radius]`);
    }
    const bad = sprinkler.find((value) => typeof value !== 'number' || !Number.isFinite(value));
    if (bad !== undefined) {
      throw new TypeError(`sprinkler ${index} has a non-numeric value`);
    }
    if (sprinkler[2] < 0) {
      throw new RangeError(`sprinkler ${index} has a negative radius`);
    }
  });
}

function overlappingPairs(sprinklers) {
  validate(sprinklers);
  const total = sprinklers.length;
  const pairs = [];
  for (let i = 0; i < total; i += 1) {
    for (let j = i + 1; j < total; j += 1) {
      if (overlaps(sprinklers[i], sprinklers[j])) {
        pairs.push([i, j]);
      }
    }
  }
  return pairs;
}

function overlap(sprinklers) {
  validate(sprinklers);
  const total = sprinklers.length;
  let count = 0;
  for (let i = 0; i < total; i += 1) {
    for (let j = i + 1; j < total; j += 1) {
      if (overlaps(sprinklers[i], sprinklers[j])) {
        count += 1;
      }
    }
  }
  return count;
}

function report(sprinklers) {
  const pairs = overlappingPairs(sprinklers);
  const header = `${pairs.length} overlapping pair(s) among ${sprinklers.length} sprinkler(s)`;
  return pairs.reduce((text, [i, j]) => {
    const gap = centerDistance(sprinklers[i], sprinklers[j]).toFixed(2);
    return `${text}\n  sprinkler ${i} and sprinkler ${j} overlap (centers ${gap} apart)`;
  }, header);
}

function main() {
  const garden = [[0, 0, 5], [10, 0, 6], [20, 0, 2]];
  console.log(report(garden));
  console.log(`overlap() = ${overlap(garden)}`);

  const dense = [[0, 0, 4], [3, 3, 4], [6, 0, 4], [3, -3, 1]];
  console.log(report(dense));
  console.log(`overlap() = ${overlap(dense)}`);
}

main();

