const STANDARD_POINTS = 50;
const MULTIPLIER_POINTS = 10;
const STREAK_BONUS = 500;
const STREAK_LENGTH = 3;

const HIT_ALIASES = {
  standard: 'standard',
  s: 'standard',
  multiplier: 'multiplier',
  m: 'multiplier',
};

function normalizeHit(hit, index) {
  if (typeof hit !== 'string') {
    throw new TypeError(`hit at position ${index} is not a string`);
  }
  const key = hit.trim().toLowerCase();
  const kind = HIT_ALIASES[key];
  if (kind === undefined) {
    throw new Error(`unknown bumper "${hit}" at position ${index}`);
  }
  return kind;
}

function score(hits) {
  if (!Array.isArray(hits)) {
    throw new TypeError('hits must be an array of bumper names');
  }
  let total = 0;
  let multiplier = 1;
  let streak = 0;
  hits.forEach((hit, index) => {
    const kind = normalizeHit(hit, index);
    if (kind === 'multiplier') {
      total += MULTIPLIER_POINTS * multiplier;
      multiplier += 1;
      streak = 0;
      return;
    }
    total += STANDARD_POINTS * multiplier;
    streak += 1;
    if (streak === STREAK_LENGTH) {
      total += STREAK_BONUS;
      streak = 0;
    }
  });
  return total;
}

function describeRun(hits) {
  const kinds = hits.map(normalizeHit);
  const multiplierCount = kinds.filter((kind) => kind === 'multiplier').length;
  const standardCount = kinds.length - multiplierCount;
  return {
    total: score(kinds),
    standardCount,
    multiplierCount,
    finalMultiplier: multiplierCount + 1,
  };
}

function formatReport(label, hits) {
  const { total, standardCount, multiplierCount, finalMultiplier } = describeRun(hits);
  const parts = [
    `${standardCount} standard`,
    `${multiplierCount} multiplier`,
    `final multiplier x${finalMultiplier}`,
  ];
  return `${label}: ${total} points (${parts.join(', ')})`;
}

function main() {
  const runs = [
    ['opening combo', ['standard', 'multiplier', 'standard', 'standard']],
    ['triple bonus', ['S', 'S', 'S']],
    ['stacked multipliers', ['M', 'M', 'standard', 'standard', 'standard', 'M']],
  ];
  for (const [label, hits] of runs) {
    console.log(formatReport(label, hits));
  }
}

main();

