function validateRainfall(rainfall) {
  if (!Array.isArray(rainfall)) {
    throw new TypeError('rainfall must be an array of numbers');
  }
  rainfall.forEach((value, index) => {
    const isUsable = typeof value === 'number' && Number.isFinite(value);
    if (!isUsable) {
      throw new TypeError(`rainfall[${index}] is not a finite number`);
    }
    if (value < 0) {
      throw new RangeError(`rainfall[${index}] must not be negative`);
    }
  });
}

function movingAverage(rainfall, index) {
  const start = Math.max(0, index - (WINDOW_SIZE - 1));
  const window = rainfall.slice(start, index + 1);
  let total = 0;
  for (const measurement of window) {
    total += measurement;
  }
  return total / window.length;
}

function nextSpeed(currentSpeed, average) {
  if (average > INCREASE_THRESHOLD) {
    return Math.min(MAX_SPEED, currentSpeed + 1);
  }
  if (average < DECREASE_THRESHOLD) {
    return Math.max(MIN_SPEED, currentSpeed - 1);
  }
  return currentSpeed;
}

function wipers(rainfall) {
  validateRainfall(rainfall);
  const speeds = [];
  let speed = MIN_SPEED;
  for (let i = 0; i < rainfall.length; i += 1) {
    const average = movingAverage(rainfall, i);
    speed = nextSpeed(speed, average);
    speeds.push(speed);
  }
  return speeds;
}

function report(rainfall) {
  const speeds = wipers(rainfall);
  const lines = speeds.map((level, index) => {
    const average = movingAverage(rainfall, index);
    return `interval ${index + 1}: rain=${rainfall[index]} avg=${average.toFixed(2)} speed=${level}`;
  });
  return lines.join('\n');
}

function parseMeasurements(args) {
  return args.map((arg) => Number(arg));
}

function main(args) {
  if (args.length === 0) {
    console.error('usage: wipers <rainfall> [rainfall ...]');
    return 1;
  }
  const rainfall = parseMeasurements(args);
  console.log(report(rainfall));
  return 0;
}

if (require.main === module) {
  process.exitCode = main(process.argv.slice(2));
}

module.exports = { wipers, movingAverage, report, parseMeasurements };

