function correctedTime(elapsedMinutes, rating) {
  const scaled = (elapsedMinutes / rating) * 100;
  return Math.floor(scaled);
}

function validateEntry(entry) {
  if (!Array.isArray(entry) || entry.length < 3) {
    throw new TypeError('each entry needs a name, elapsed time and rating');
  }
  const [name, elapsed, rating] = entry;
  if (typeof name !== 'string' || name.length === 0) {
    throw new TypeError('boat name must be a non-empty string');
  }
  if (!Number.isFinite(elapsed) || elapsed < 0) {
    throw new RangeError(`invalid elapsed time for ${name}`);
  }
  if (!Number.isFinite(rating) || rating <= 0) {
    throw new RangeError(`invalid handicap rating for ${name}`);
  }
  return { name, elapsed, rating };
}

function scoreFleet(boats) {
  const scored = boats.map((entry) => {
    const { name, elapsed, rating } = validateEntry(entry);
    return { name, elapsed, rating, corrected: correctedTime(elapsed, rating) };
  });
  scored.sort((a, b) => {
    const gap = a.corrected - b.corrected;
    return gap !== 0 ? gap : a.name.localeCompare(b.name);
  });
  return scored;
}

function adjust(boats) {
  return scoreFleet(boats).map((boat) => boat.name);
}

function formatResults(boats) {
  const scored = scoreFleet(boats);
  const nameWidth = scored.reduce((widest, boat) => Math.max(widest, boat.name.length), 4);
  const lines = ['Pos  ' + 'Boat'.padEnd(nameWidth) + '  Elapsed  Rating  Corrected'];
  let position = 0;
  let previous = null;
  let ties = 0;
  for (const boat of scored) {
    if (previous !== null && boat.corrected === previous) {
      ties += 1;
    } else {
      position += 1 + ties;
      ties = 0;
    }
    previous = boat.corrected;
    const cells = [
      String(position).padStart(3),
      boat.name.padEnd(nameWidth),
      String(boat.elapsed).padStart(7),
      String(boat.rating).padStart(6),
      String(boat.corrected).padStart(9),
    ];
    lines.push(cells.join('  '));
  }
  return lines.join('\n');
}

const regatta = [
  ['Windfall', 60, 100],
  ['Osprey', 50, 80],
  ['Nimbus', 72, 120],
  ['Aurora', 66, 110],
  ['Tempest', 45, 75],
];

console.log(formatResults(regatta));
console.log('Finish order:', adjust(regatta).join(' > '));

module.exports = { adjust, correctedTime, formatResults };

