const SPEED_OF_SOUND = 1500;
const HAZARD_THRESHOLD = 50;

function isValidPing(ping) {
  const { emitted, returned } = ping;
  return Number.isFinite(emitted) && Number.isFinite(returned) && returned >= emitted;
}

function pingDistance(ping) {
  const elapsed = ping.returned - ping.emitted;
  return (elapsed * SPEED_OF_SOUND) / 2;
}

function echoes(pings) {
  const readings = [];
  for (const ping of pings) {
    if (!isValidPing(ping)) {
      continue;
    }
    const distance = Math.trunc(pingDistance(ping));
    const hazard = distance < HAZARD_THRESHOLD;
    readings.push([distance, hazard]);
  }
  return readings;
}

function seafloorPoint(distance, angleDegrees) {
  const radians = (angleDegrees * Math.PI) / 180;
  const depth = distance * Math.cos(radians);
  const offset = distance * Math.sin(radians);
  return { depth, offset };
}

function surveyReport(pings) {
  const valid = pings.filter(isValidPing);
  const readings = echoes(pings);
  const lines = [];
  let hazardCount = 0;
  readings.forEach(([distance, hazard], index) => {
    const angle = valid[index].angle;
    const { depth, offset } = seafloorPoint(distance, angle);
    if (hazard) {
      hazardCount += 1;
    }
    const status = hazard ? 'HAZARD' : 'clear';
    lines.push(
      `${String(distance).padStart(5)} m at ${angle}deg -> depth ${depth.toFixed(1)} m, ` +
        `offset ${offset.toFixed(1)} m [${status}]`
    );
  });
  const skipped = pings.length - readings.length;
  lines.push(`${readings.length} valid echo(es), ${hazardCount} hazard(s), ${skipped} discarded`);
  return lines.join('\n');
}

function main() {
  const pings = [
    { emitted: 2, returned: 4, angle: 0 },
    { emitted: 10, returned: 10.04, angle: 15 },
    { emitted: 20, returned: 19, angle: 30 },
    { emitted: 30.5, returned: 31.1, angle: 45 },
  ];
  const results = echoes(pings);
  console.log(JSON.stringify(results));
  console.log(surveyReport(pings));
}

main();

module.exports = { echoes, pingDistance, seafloorPoint, surveyReport };

