function validateInput(observations, window) {
  if (!Array.isArray(observations)) {
    throw new TypeError("observations must be an array of integers");
  }
  for (const count of observations) {
    if (!Number.isInteger(count) || count < 0) {
      throw new RangeError(`invalid meteor count: ${count}`);
    }
  }
  if (!Number.isInteger(window) || window < 1) {
    throw new RangeError("window must be a positive integer");
  }
  if (window > observations.length) {
    throw new RangeError("window is larger than the observation period");
  }
}

function movingSums(observations, window) {
  const sums = [];
  let running = 0;
  for (let i = 0; i < window; i += 1) {
    running += observations[i];
  }
  sums.push(running);
  for (let i = window; i < observations.length; i += 1) {
    running += observations[i] - observations[i - window];
    sums.push(running);
  }
  return sums;
}

function meteors(observations, window) {
  validateInput(observations, window);
  const sums = movingSums(observations, window);
  let peakIndex = 0;
  for (let i = 1; i < sums.length; i += 1) {
    if (sums[i] > sums[peakIndex]) {
      peakIndex = i;
    }
  }
  return [peakIndex, sums[peakIndex]];
}

function formatReport(observations, window) {
  const [start, total] = meteors(observations, window);
  const end = start + window - 1;
  const average = (total / window).toFixed(2);
  const lines = [
    `Minutes observed: ${observations.length}`,
    `Window size: ${window}`,
    `Peak window: minutes ${start}-${end}`,
    `Meteors in peak window: ${total}`,
    `Average per minute during peak: ${average}`,
  ];
  return lines.join("\n");
}

const nightCounts = [0, 2, 5, 3, 1];
console.log(formatReport(nightCounts, 3));

const perseidWatch = [4, 1, 0, 7, 2, 2, 9, 3, 0, 6, 5, 1];
for (const size of [1, 4, 6]) {
  const [start, total] = meteors(perseidWatch, size);
  console.log(`window=${size} -> peak at minute ${start} with ${total} meteors`);
}

module.exports = { meteors, movingSums, formatReport };

