const DRYING_MAX = 150;
const BROWNING_MAX = 200;
const MIN_DEVELOPMENT_RATIO = 0.15;
const MAX_DEVELOPMENT_RATIO = 0.25;

function classifyPhase(temperature) {
  if (temperature < DRYING_MAX) {
    return 'drying';
  }
  if (temperature <= BROWNING_MAX) {
    return 'browning';
  }
  return 'development';
}

function countPhases(temperatures) {
  const counts = { drying: 0, browning: 0, development: 0 };
  for (const temperature of temperatures) {
    const phase = classifyPhase(temperature);
    counts[phase] += 1;
  }
  return counts;
}

function isBalanced(developmentMinutes, totalMinutes) {
  if (totalMinutes === 0) {
    return false;
  }
  const ratio = developmentMinutes / totalMinutes;
  return ratio >= MIN_DEVELOPMENT_RATIO && ratio <= MAX_DEVELOPMENT_RATIO;
}

function evaluate(temperatures) {
  if (!Array.isArray(temperatures)) {
    throw new TypeError('temperatures must be an array of numbers');
  }
  for (const temperature of temperatures) {
    if (typeof temperature !== 'number' || Number.isNaN(temperature)) {
      throw new TypeError(`invalid temperature reading: ${temperature}`);
    }
  }
  const counts = countPhases(temperatures);
  const total = temperatures.length;
  const balanced = isBalanced(counts.development, total);
  return [counts.drying, counts.browning, counts.development, balanced];
}

function formatReport(label, temperatures) {
  const [drying, browning, development, balanced] = evaluate(temperatures);
  const total = drying + browning + development;
  let percentage = '0.0';
  if (total > 0) {
    percentage = ((development / total) * 100).toFixed(1);
  }
  const verdict = balanced ? 'balanced' : 'unbalanced';
  return `${label}: drying=${drying}min browning=${browning}min development=${development}min (${percentage}%) -> ${verdict}`;
}

function buildRamp(minutes, startTemp, endTemp) {
  const step = minutes > 1 ? (endTemp - startTemp) / (minutes - 1) : 0;
  const readings = [];
  for (let minute = 0; minute < minutes; minute += 1) {
    readings.push(startTemp + step * minute);
  }
  return readings;
}

function main() {
  const evenRoast = buildRamp(10, 120, 145)
    .concat(buildRamp(5, 155, 195))
    .concat(buildRamp(5, 205, 215));
  const scorchedRoast = buildRamp(4, 130, 148).concat(buildRamp(8, 205, 230));
  const reports = [
    formatReport('even roast', evenRoast),
    formatReport('scorched roast', scorchedRoast),
  ];
  for (const line of reports) {
    console.log(line);
  }
}

main();

module.exports = { evaluate, formatReport, classifyPhase };

