function smooth(sharpness) {
  const length = sharpness.length;
  if (length < 3) {
    return sharpness.slice();
  }
  const smoothed = sharpness.slice();
  for (let i = 1; i < length - 1; i += 1) {
    const previous = sharpness[i - 1];
    const current = sharpness[i];
    const next = sharpness[i + 1];
    smoothed[i] = Math.trunc((previous + current + next) / 3);
  }
  return smoothed;
}

function indexOfMaximum(values) {
  let bestIndex = 0;
  let bestValue = values[0];
  for (let i = 1; i < values.length; i += 1) {
    const candidate = values[i];
    if (candidate > bestValue) {
      bestValue = candidate;
      bestIndex = i;
    }
  }
  return bestIndex;
}

function calibrate(sharpness) {
  if (!Array.isArray(sharpness) || sharpness.length === 0) {
    throw new Error('calibrate requires a non-empty array of sharpness scores');
  }
  for (const score of sharpness) {
