function smooth(sharpness) {
  var length = sharpness.length;
  if (length < 3) {
    return sharpness.slice();
  }
  var smoothed = sharpness.slice();
  for (var i = 1; i < length - 1; i += 1) {
    var previous = sharpness[i - 1];
    var current = sharpness[i];
    var next = sharpness[i + 1];
    smoothed[i] = Math.trunc((previous + current + next) / 3);
  }
  return smoothed;
}

function indexOfMaximum(values) {
  var bestIndex = 0;
  var bestValue = values[0];
  for (var i = 1; i < values.length; i += 1) {
    var candidate = values[i];
    if (candidate > bestValue) {
