const BURN_COST = 2;
const BURN_LIFT = 20;
const VENT_DROP = 15;
const COOLING_DROP = 5;
const GROUND = 0;

function clampAltitude(altitude) {
  return altitude < GROUND ? GROUND : altitude;
}

function applyBurn(state) {
  if (state.fuel < BURN_COST) {
    return { altitude: clampAltitude(state.altitude - COOLING_DROP), fuel: state.fuel };
  }
  const lifted = state.altitude + BURN_LIFT;
  return { altitude: lifted, fuel: state.fuel - BURN_COST };
}

function applyVent(state) {
  const vented = state.altitude - VENT_DROP;
  return { altitude: clampAltitude(vented), fuel: state.fuel };
}

function parseCommand(command) {
  const name = String(command).trim().toLowerCase();
  if (name !== 'burn' && name !== 'vent') {
    throw new Error(`unknown command: ${command}`);
  }
  return name;
}

function navigate(commands, fuel) {
  if (!Array.isArray(commands)) {
    throw new TypeError('commands must be an array of strings');
  }
  if (typeof fuel !== 'number' || Number.isNaN(fuel) || fuel < 0) {
    throw new RangeError('fuel must be a non-negative number');
  }
  let state = { altitude: GROUND, fuel };
  for (const command of commands) {
    const name = parseCommand(command);
    state = name === 'burn' ? applyBurn(state) : applyVent(state);
  }
  return [state.altitude, state.fuel];
}

function formatFlight(commands, fuel) {
  const [altitude, remaining] = navigate(commands, fuel);
  const route = commands.join(' -> ');
  return `${route} | start ${fuel} L => altitude ${altitude} m, fuel ${remaining} L`;
}

function main() {
  const flights = [
    { commands: ['burn', 'vent'], fuel: 3 },
    { commands: ['burn', 'burn', 'burn'], fuel: 4 },
    { commands: ['vent', 'vent', 'burn'], fuel: 2 },
    { commands: ['burn', 'vent', 'vent', 'vent'], fuel: 6 }
  ];
  for (const flight of flights) {
    console.log(formatFlight(flight.commands, flight.fuel));
  }
  let totalFuelUsed = 0;
  for (const flight of flights) {
    const [, remaining] = navigate(flight.commands, flight.fuel);
    totalFuelUsed += flight.fuel - remaining;
  }
  console.log(`total fuel burned across flights: ${totalFuelUsed} L`);
}

main();

module.exports = { navigate, formatFlight };

