function normalizeFlavors(flavors) {
  const seen = new Set();
  const cleaned = [];
  for (const raw of flavors) {
    const name = String(raw).trim();
    if (name === '') {
      continue;
    }
    const key = name.toLowerCase();
    if (!seen.has(key)) {
      seen.add(key);
      cleaned.push(name);
    }
  }
  return cleaned;
}

function mix(flavors) {
  if (!Array.isArray(flavors)) {
    throw new TypeError('mix expects a list of flavor strings');
  }
  const menu = normalizeFlavors(flavors);
  const total = menu.length;
  if (total < 3) {
    return [];
  }
  const combinations = [];
  for (let i = 0; i < total - 2; i += 1) {
    for (let j = i + 1; j < total - 1; j += 1) {
      for (let k = j + 1; k < total; k += 1) {
        const triplet = [menu[i], menu[j], menu[k]];
        combinations.push(triplet.join('-'));
      }
    }
  }
  return combinations;
}

function countCombinations(flavorCount) {
  if (flavorCount < 3) {
    return 0;
  }
  const n = flavorCount;
  return (n * (n - 1) * (n - 2)) / 6;
}

function describeMenu(flavors) {
  const sundaes = mix(flavors);
  const expected = countCombinations(normalizeFlavors(flavors).length);
  const lines = [`Sundaes available: ${sundaes.length} of ${expected} possible`];
  let index = 1;
  for (const sundae of sundaes) {
    const label = String(index).padStart(2, ' ');
    lines.push(`${label}. ${sundae}`);
    index += 1;
  }
  return lines.join('\n');
}

const available = ['mint', 'cherry', 'fudge', 'caramel'];
console.log(describeMenu(available));

const tooFew = ['vanilla', 'chocolate'];
console.log(`Short menu yields ${mix(tooFew).length} sundaes`);

const withDuplicates = ['vanilla', 'Vanilla', ' chocolate ', 'strawberry', 'fudge'];
const dedupedMix = mix(withDuplicates);
console.log(dedupedMix.join(', '));

