function validateShell(shell, index) {
  if (!Array.isArray(shell) || shell.length !== 3) {
    throw new TypeError(`shell ${index} must be [type, delay, flight]`);
  }
  const [type, delay, flight] = shell;
  if (typeof type !== 'string' || type.trim() === '') {
    throw new TypeError(`shell ${index} has an empty type`);
  }
  const numbers = [delay, flight];
  for (const value of numbers) {
    if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) {
      throw new RangeError(`shell ${index} has an invalid timing: ${value}`);
    }
  }
  return { type: type.trim(), delay, flight };
}

function sequence(fireworks) {
  if (!Array.isArray(fireworks)) {
    throw new TypeError('fireworks must be a list of shell records');
  }
  const timeline = [];
  let clock = 0;
  fireworks.forEach((shell, index) => {
    const { type, delay, flight } = validateShell(shell, index);
    clock += delay;
    const explosion = clock + flight;
    timeline.push([type, clock, explosion]);
  });
  return timeline;
}

function showDuration(timeline) {
  let last = 0;
  for (const [, , explosion] of timeline) {
    if (explosion > last) {
      last = explosion;
    }
  }
  return last;
}

function formatTimeline(timeline) {
  const width = timeline.reduce((widest, [type]) => Math.max(widest, type.length), 0);
  const lines = timeline.map(([type, launch, explosion]) => {
    const label = type.padEnd(width, ' ');
    return `${label}  launch ${launch.toFixed(1)}s  burst ${explosion.toFixed(1)}s`;
  });
  const total = showDuration(timeline);
  lines.push(`show ends at ${total.toFixed(1)}s`);
  return lines.join('\n');
}

function main() {
  const shells = [
    ['star', 2, 3],
    ['ring', 4, 2],
    ['willow', 1.5, 4],
    ['crossette', 3, 2.5],
  ];
  const timeline = sequence(shells);
  console.log(formatTimeline(timeline));
}

main();

module.exports = { sequence, formatTimeline, showDuration };

