function findBulkItem(prices, name) {
  for (const entry of prices) {
    const [bulkName] = entry;
    if (bulkName === name) {
      return entry;
    }
  }
  return null;
}

function unitPrice(bulkItem) {
  const [, bulkQuantity, bulkPrice] = bulkItem;
  if (!bulkQuantity) {
    throw new Error(`bulk quantity for ${bulkItem[0]} must be greater than zero`);
  }
  return bulkPrice / bulkQuantity;
}

function round2(value) {
  return Math.round(value * 100) / 100;
}

function cost(materials, prices) {
  let baseTotal = 0;
  for (const [name, quantity] of materials) {
    const bulkItem = findBulkItem(prices, name);
    if (!bulkItem) {
      throw new Error(`no bulk price listed for ${name}`);
    }
    const perUnit = unitPrice(bulkItem);
    baseTotal += perUnit * quantity;
  }
  const withMargin = baseTotal * 1.1;
  return [round2(baseTotal), round2(withMargin)];
}

function breakdown(materials, prices) {
  const lines = [];
  for (const [name, quantity] of materials) {
    const bulkItem = findBulkItem(prices, name);
    const perUnit = bulkItem ? unitPrice(bulkItem) : 0;
    lines.push({
      name,
      quantity,
      unit: round2(perUnit),
      subtotal: round2(perUnit * quantity),
    });
  }
  return lines;
}

function report(materials, prices) {
  const [base, total] = cost(materials, prices);
  const rows = breakdown(materials, prices);
  const text = rows
    .map((row) => `${row.name}: ${row.quantity} @ ${row.unit} = ${row.subtotal}`)
    .join('\n');
  return `${text}\nbase: ${base}\nwith 10% margin: ${total}`;
}

const required = [
  ['wood', 500],
  ['nails', 3000],
  ['concrete', 120],
];

const bulkPrices = [
  ['wood', 1000, 2],
  ['nails', 500, 1.5],
  ['concrete', 40, 30],
];

console.log(report(required, bulkPrices));

const simple = cost([['wood', 500]], [['wood', 1000, 2]]);
console.log(simple);

