function adjustPrice(basePrice, remaining, capacity) {
  const ratio = remaining / capacity;
  if (ratio < 0.2) {
    return Math.round(basePrice * 1.5);
  }
  if (ratio > 0.8) {
    return Math.round(basePrice * 0.8);
  }
  return Math.round(basePrice);
}

function price(tiers, remaining) {
  if (tiers.length !== remaining.length) {
    throw new Error('each tier needs exactly one remaining-seat count');
  }
  const adjusted = [];
  for (let i = 0; i < tiers.length; i += 1) {
    const [name, basePrice, capacity] = tiers[i];
    const left = remaining[i];
    if (capacity <= 0) {
      throw new Error(`tier ${name} has a non-positive capacity`);
    }
    if (left < 0 || left > capacity) {
      throw new Error(`tier ${name} has ${left} seats left of ${capacity}`);
    }
    adjusted.push([name, adjustPrice(basePrice, left, capacity)]);
  }
  return adjusted;
}

function occupancyLabel(remaining, capacity) {
  const ratio = remaining / capacity;
  if (ratio < 0.2) {
    return 'almost sold out';
  }
  if (ratio > 0.8) {
    return 'plenty of seats';
  }
  return 'selling steadily';
}

function report(tiers, remaining) {
  const priced = price(tiers, remaining);
  const nameWidth = Math.max(...tiers.map((tier) => tier[0].length));
  const lines = priced.map(([name, finalPrice], index) => {
    const [, basePrice, capacity] = tiers[index];
    const delta = finalPrice - basePrice;
    const sign = delta >= 0 ? '+' : '-';
    const label = occupancyLabel(remaining[index], capacity);
    const padded = name.padEnd(nameWidth, ' ');
    return `${padded}  ${basePrice} -> ${finalPrice} (${sign}${Math.abs(delta)})  ${label}`;
  });
  const revenue = priced.reduce((sum, [, finalPrice], index) => {
    const sold = tiers[index][2] - remaining[index];
    return sum + sold * finalPrice;
  }, 0);
  lines.push(`projected revenue from seats already sold: ${revenue}`);
  return lines.join('\n');
}

function main() {
  const tiers = [
    ['VIP', 200, 10],
    ['Front Row', 150, 40],
    ['Balcony', 60, 120],
    ['Standing', 35, 200],
  ];
  const remaining = [1, 18, 110, 200];
  console.log(JSON.stringify(price(tiers, remaining)));
  console.log(report(tiers, remaining));
}

main();

