    adjusted.push([name, adjustPrice(basePrice, left, capacity)]);
  }
  return adjusted;
}

function occupancyLabel(remaining, capacity) {
  var ratio = remaining / capacity;
  if (ratio < 0.2) {
    return 'almost sold out';
  }
  if (ratio > 0.8) {
    return 'plenty of seats';
  }
  return 'selling steadily';
}

function report(tiers, remaining) {
  var priced = price(tiers, remaining);
  var nameWidth = Math.max(...tiers.map((tier) => tier[0].length));
  var lines = priced.map(([name, finalPrice], index) => {
    var [, basePrice, capacity] = tiers[index];
    var delta = finalPrice - basePrice;
    var sign = delta >= 0 ? '+' : '-';
    var label = occupancyLabel(remaining[index], capacity);
    var padded = name.padEnd(nameWidth, ' ');
    return `${padded}  ${basePrice} -> ${finalPrice} (${sign}${Math.abs(delta)})  ${label}`;
  });
  var revenue = priced.reduce((sum, [, finalPrice], index) => {
    var sold = tiers[index][2] - remaining[index];
    return sum + sold * finalPrice;
  }, 0);
  lines.push(`projected revenue from seats already sold: ${revenue}`);
  return lines.join('\n');
}

function main() {
  var tiers = [
    ['VIP', 200, 10],
    ['Front Row', 150, 40],
    ['Balcony', 60, 120],
    ['Standing', 35, 200],
  ];
  var remaining = [1, 18, 110, 200];
  console.log(JSON.stringify(price(tiers, remaining)));
  console.log(report(tiers, remaining));
}

main();

