function normalizePackage(pkg) {
  const [zone, weight, priority] = pkg;
  if (typeof zone !== 'string' || zone.length === 0) {
    throw new TypeError('package destination zone must be a non-empty string');
  }
  const kilograms = Number(weight);
  if (!Number.isFinite(kilograms) || kilograms < 0) {
    throw new RangeError(`invalid weight for zone ${zone}: ${weight}`);
  }
  const level = Number(priority);
  if (!Number.isInteger(level)) {
    throw new TypeError(`priority for zone ${zone} must be an integer`);
  }
  return { zone, kilograms, level };
}

function byPriorityThenWeight(a, b) {
  const priorityGap = b.level - a.level;
  if (priorityGap !== 0) {
    return priorityGap;
  }
  return a.kilograms - b.kilograms;
}

function dispatch(packages, capacity) {
  const maxWeight = Number(capacity);
  if (!Number.isFinite(maxWeight) || maxWeight < 0) {
    throw new RangeError(`invalid vehicle capacity: ${capacity}`);
  }
  const manifest = packages.map(normalizePackage).sort(byPriorityThenWeight);
  const zones = [];
  let loaded = 0;
  for (const item of manifest) {
    const projected = loaded + item.kilograms;
    if (projected > maxWeight) {
      continue;
    }
    loaded = projected;
    zones.push(item.zone);
  }
  return zones;
}

function loadedWeight(packages, zones) {
  const remaining = zones.slice();
  let total = 0;
  for (const item of packages.map(normalizePackage).sort(byPriorityThenWeight)) {
    const position = remaining.indexOf(item.zone);
    if (position !== -1) {
      remaining.splice(position, 1);
      total += item.kilograms;
    }
  }
  return total;
}

function describeRun(packages, capacity) {
  const zones = dispatch(packages, capacity);
  const used = loadedWeight(packages, zones);
  const skipped = packages.length - zones.length;
  const route = zones.length > 0 ? zones.join(' -> ') : '(empty run)';
  return `${route} | ${used}/${capacity} kg | ${skipped} package(s) left behind`;
}

