  [[['North', 5, 1], ['South', 3, 2]], 4],
  [[['East', 4, 3], ['West', 4, 3], ['Central', 2, 5], ['Docks', 9, 1]], 10]
];

for (const [packages, capacity] of runs) {
  console.log(describeRun(packages, capacity));
}

