function parseRole(role) {
  const [archetype, level, screenTime] = role;
  return { archetype, level, screenTime };
}

function parseActor(actor) {
  const [name, specialization, maxLevel] = actor;
  return { name, specialization, maxLevel };
}

function eligibleFor(role, pool) {
  return pool.filter((actor) => actor.specialization === role.archetype && actor.maxLevel >= role.level);
}

function cheapestCandidate(candidates) {
  let best = candidates[0];
  for (const candidate of candidates.slice(1)) {
    if (candidate.maxLevel < best.maxLevel) {
      best = candidate;
    }
  }
  return best;
}

function casting(roles, actors) {
  const pool = actors.map(parseActor);
  const assignments = [];
  for (const raw of roles) {
    const role = parseRole(raw);
    const candidates = eligibleFor(role, pool);
    if (candidates.length === 0) {
      continue;
    }
    const chosen = cheapestCandidate(candidates);
    pool.splice(pool.indexOf(chosen), 1);
    assignments.push([role.archetype, chosen.name]);
  }
  return assignments;
}

function screenTimeByActor(roles, assignments) {
  const times = new Map();
  for (const [index, pair] of assignments.entries()) {
    const role = parseRole(roles[index]);
    const actorName = pair[1];
    const previous = times.get(actorName) || 0;
    times.set(actorName, previous + role.screenTime);
  }
  return times;
}

function report(roles, actors) {
  const assignments = casting(roles, actors);
  const lines = assignments.map(([archetype, name]) => `${archetype} -> ${name}`);
  const unfilled = roles.length - assignments.length;
  if (unfilled > 0) {
    lines.push(`${unfilled} role(s) left unfilled`);
  }
  for (const [name, total] of screenTimeByActor(roles, assignments)) {
    lines.push(`${name} on screen for ${total} minutes`);
  }
  return lines.join("\n");
}

const movieRoles = [
  ["villain", 7, 40],
  ["hero", 5, 90],
  ["hero", 8, 25],
  ["sidekick", 3, 15],
];
const availableActors = [
  ["Ada", "hero", 9],
  ["Bram", "hero", 6],
  ["Cleo", "villain", 7],
  ["Dov", "villain", 9],
];
console.log(report(movieRoles, availableActors));

