const TARGETS = Object.freeze({ calcium: 420, alkalinity: 8, magnesium: 1300 });
const FACTORS = Object.freeze({ calcium: 2, alkalinity: 5, magnesium: 3 });
const PARAMETER_ORDER = Object.freeze(['calcium', 'alkalinity', 'magnesium']);

function deficit(name, current) {
  const target = TARGETS[name];
  const gap = target - current;
  return gap > 0 ? gap : 0;
}

function dose(parameters) {
  if (!Array.isArray(parameters) || parameters.length !== 3) {
    throw new TypeError('dose expects a list of three water parameters');
  }
  const volumes = [];
  for (let i = 0; i < PARAMETER_ORDER.length; i += 1) {
    const name = PARAMETER_ORDER[i];
    const current = Number(parameters[i]);
    if (!Number.isFinite(current)) {
      throw new TypeError(`measurement for ${name} is not a number`);
    }
    volumes.push(deficit(name, current) * FACTORS[name]);
  }
  return volumes;
}

function parseReading(text) {
  const fields = String(text).split(',');
  if (fields.length !== 3) {
    throw new SyntaxError(`cannot read three values from "${text}"`);
  }
  return fields.map((field) => Number.parseFloat(field.trim()));
}

function formatReport(parameters) {
  const volumes = dose(parameters);
  const lines = PARAMETER_ORDER.map((name, i) => {
    const current = parameters[i];
    const millilitres = volumes[i];
    const status = millilitres === 0 ? 'at or above target' : `add ${millilitres} mL`;
    return `${name.padEnd(10)} ${String(current).padStart(6)} -> ${status}`;
  });
  const total = volumes.reduce((sum, v) => sum + v, 0);
  lines.push(`total additive volume: ${total} mL`);
  return lines.join('\n');
}

function main() {
  const readings = ['400, 7, 1250', '420, 8.4, 1375', '380, 6.5, 1180'];
  for (const reading of readings) {
    const parameters = parseReading(reading);
    const volumes = dose(parameters);
    console.log(`test kit: ${reading}`);
    console.log(`dose(${JSON.stringify(parameters)}) = ${JSON.stringify(volumes)}`);
    console.log(formatReport(parameters));
    console.log('');
  }
}

main();

module.exports = { dose, deficit, parseReading, formatReport };

