function validateVehicle(vehicle, index) {
  const label = `vehicle #${index + 1}`;
  if (!Array.isArray(vehicle) || vehicle.length !== 3) {
    throw new TypeError(`${label} must be a list of [weight, bowPosition, portPosition]`);
  }
  const [weight, bowPosition, portPosition] = vehicle;
  for (const value of vehicle) {
    if (typeof value !== 'number' || !Number.isFinite(value)) {
      throw new TypeError(`${label} contains a non-numeric measurement: ${String(value)}`);
    }
  }
  if (weight <= 0) {
    throw new RangeError(`${label} must have a positive weight`);
  }
  if (bowPosition < 0 || portPosition < 0) {
    throw new RangeError(`${label} must have non-negative deck positions`);
  }
  return [weight, bowPosition, portPosition];
}

function balance(vehicles) {
  if (!Array.isArray(vehicles) || vehicles.length === 0) {
    throw new RangeError('at least one vehicle is needed to compute a center of gravity');
  }
  let totalWeight = 0;
  let bowMoments = 0;
  let portMoments = 0;
  vehicles.forEach((vehicle, index) => {
    const [weight, bowPosition, portPosition] = validateVehicle(vehicle, index);
    totalWeight += weight;
    bowMoments += weight * bowPosition;
    portMoments += weight * portPosition;
  });
  const averageBow = bowMoments / totalWeight;
  const averagePort = portMoments / totalWeight;
  return [totalWeight, averageBow, averagePort];
}

function trimDifference(vehicles, deckLength, deckWidth) {
  const [, averageBow, averagePort] = balance(vehicles);
  const bowOffset = averageBow - deckLength / 2;
  const portOffset = averagePort - deckWidth / 2;
  return { bowOffset, portOffset };
}

function describeBalance(vehicles, deckLength, deckWidth) {
  const [totalWeight, averageBow, averagePort] = balance(vehicles);
  const { bowOffset, portOffset } = trimDifference(vehicles, deckLength, deckWidth);
  const lengthwise = bowOffset >= 0 ? 'astern' : 'forward';
  const crosswise = portOffset >= 0 ? 'to starboard' : 'to port';
  const lines = [
    `Cargo weight: ${totalWeight.toFixed(2)} t`,
    `Center of gravity: ${averageBow.toFixed(2)} m from the bow, ${averagePort.toFixed(2)} m from port`,
    `Trim: ${Math.abs(bowOffset).toFixed(2)} m ${lengthwise} of midships`,
    `List: ${Math.abs(portOffset).toFixed(2)} m ${crosswise} of the centerline`
  ];
  return lines.join('\n');
}

const deckLength = 60;
const deckWidth = 18;
const loadedVehicles = [
  [1.4, 6.0, 3.2],
  [2.1, 12.5, 9.0],
  [18.0, 24.0, 4.5],
  [3.6, 31.2, 14.1],
  [1.9, 44.8, 8.3]
];

console.log(describeBalance(loadedVehicles, deckLength, deckWidth));

const centerOfGravity = balance(loadedVehicles);
console.log(`balance() -> [${centerOfGravity.map((n) => n.toFixed(3)).join(', ')}]`);

