const DAYS_PER_WEEK = 7;
const SPOILAGE_FACTOR = 1.05;

function validateGroup(group) {
  const [species, count, meatPerDay, producePerDay] = group;
  if (typeof species !== 'string' || species.length === 0) {
    throw new TypeError('species name must be a non-empty string');
  }
  const numbers = [count, meatPerDay, producePerDay];
  for (const value of numbers) {
    if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) {
      throw new RangeError(`invalid quantity for ${species}: ${value}`);
    }
  }
  return { species, count, meatPerDay, producePerDay };
}

function weeklyNeeds(group) {
  const { species, count, meatPerDay, producePerDay } = validateGroup(group);
  const meat = count * meatPerDay * DAYS_PER_WEEK;
  const produce = count * producePerDay * DAYS_PER_WEEK;
  return { species, meat, produce };
}

function diet(animals) {
  let totalMeat = 0;
  let totalProduce = 0;
  for (const group of animals) {
    const needs = weeklyNeeds(group);
    totalMeat += needs.meat;
    totalProduce += needs.produce;
  }
  const meatOrder = Math.ceil(totalMeat * SPOILAGE_FACTOR);
  const produceOrder = Math.ceil(totalProduce * SPOILAGE_FACTOR);
  return [meatOrder, produceOrder];
}

function orderReport(animals) {
  const lines = [];
  for (const group of animals) {
    const { species, meat, produce } = weeklyNeeds(group);
    const label = species.padEnd(12);
    lines.push(`${label} meat ${meat.toFixed(1)} kg, produce ${produce.toFixed(1)} kg`);
  }
  const [meatOrder, produceOrder] = diet(animals);
  lines.push('-'.repeat(48));
  lines.push(`Order (incl. 5% spoilage): ${meatOrder} kg meat, ${produceOrder} kg produce`);
  return lines.join('\n');
}

function main() {
  const zoo = [
    ['lion', 4, 9.5, 0],
    ['elephant', 2, 0, 150],
    ['chimpanzee', 6, 0.4, 4.5],
    ['penguin', 18, 1.2, 0],
    ['giraffe', 3, 0, 32],
  ];
  console.log(orderReport(zoo));

  const nocturnalHouse = [
    ['bat', 40, 0.05, 0.1],
    ['owl', 5, 0.3, 0],
  ];
  const [meat, produce] = diet(nocturnalHouse);
  console.log(`Nocturnal house: ${meat} kg meat, ${produce} kg produce`);
}

main();

module.exports = { diet, weeklyNeeds, orderReport };

