const WALKING_SPEED_KMH = 5;
const MINUTES_PER_HOUR = 60;
const ELEVATION_PENALTY_MINUTES = 15;
const ELEVATION_PENALTY_STEP_M = 100;

function validateSegments(segments) {
  if (!Array.isArray(segments)) {
    throw new TypeError('segments must be a list of [distance, elevation] pairs');
  }
  segments.forEach((segment, index) => {
    if (!Array.isArray(segment) || segment.length !== 2) {
      throw new TypeError(`segment ${index} must be a pair [distance, elevation]`);
    }
    const [distance, elevation] = segment;
    if (typeof distance !== 'number' || typeof elevation !== 'number') {
      throw new TypeError(`segment ${index} must contain numbers`);
    }
    if (distance < 0 || elevation < 0) {
      throw new RangeError(`segment ${index} must not contain negative values`);
    }
  });
  return segments;
}

function trail(segments) {
  validateSegments(segments);
  let totalDistance = 0;
  let totalElevation = 0;
  let totalTime = 0;
  for (const [distance, elevation] of segments) {
    totalDistance += distance;
    totalElevation += elevation;
    const baseTime = (distance / WALKING_SPEED_KMH) * MINUTES_PER_HOUR;
    const climbPenalty = (elevation / ELEVATION_PENALTY_STEP_M) * ELEVATION_PENALTY_MINUTES;
    totalTime += baseTime + climbPenalty;
  }
  return [totalDistance, totalElevation, totalTime];
}

function formatDuration(minutes) {
  const wholeMinutes = Math.round(minutes);
  const hours = Math.floor(wholeMinutes / MINUTES_PER_HOUR);
  const rest = wholeMinutes % MINUTES_PER_HOUR;
  if (hours === 0) {
    return `${rest} min`;
  }
  return `${hours} h ${String(rest).padStart(2, '0')} min`;
}

function describeRoute(name, segments) {
  const [distance, elevation, time] = trail(segments);
  const pace = distance > 0 ? time / distance : 0;
  return [
    `${name}: ${segments.length} segment(s)`,
    `  distance   ${distance.toFixed(1)} km`,
    `  elevation  ${elevation} m`,
    `  time       ${formatDuration(time)} (${pace.toFixed(1)} min/km)`,
  ].join('\n');
}

function main() {
  const routes = [
    ['Warm-up climb', [[5, 200]]],
    ['Ridge traverse', [[3.5, 450], [2, 0], [4.5, 120]]],
    ['Valley stroll', [[8, 0]]],
  ];
  for (const [name, segments] of routes) {
    console.log(describeRoute(name, segments));
  }
  const grandTotal = trail(routes.flatMap(([, segments]) => segments));
  console.log(`All routes combined: ${grandTotal[0]} km, ${grandTotal[1]} m, ${formatDuration(grandTotal[2])}`);
}

main();

module.exports = { trail, describeRoute, formatDuration };

