function parseCustomer(entry) {
  const [name, height] = entry;
  if (typeof name !== 'string' || name.length === 0) {
    throw new TypeError('Each customer needs a name.');
  }
  const cm = Number(height);
  if (!Number.isFinite(cm) || cm <= 0) {
    throw new RangeError(`Invalid height for ${name}: ${height}`);
  }
  return { name, height: cm };
}

function parseBoard(entry) {
  const [id, length] = entry;
  const cm = Number(length);
  if (!Number.isFinite(cm) || cm <= 0) {
    throw new RangeError(`Invalid length for board ${id}: ${length}`);
  }
  return { id, length: cm, available: true };
}

function minimumBoardLength(height) {
  return height * 0.8;
}

function rentals(customers, inventory) {
  const riders = customers.map(parseCustomer);
  const boards = inventory.map(parseBoard);
  boards.sort((a, b) => a.length - b.length);

  const pairings = [];
  for (const rider of riders) {
    const minLength = minimumBoardLength(rider.height);
    const match = boards.find((board) => board.available && board.length >= minLength);
    if (match) {
      match.available = false;
      pairings.push([rider.name, match.id]);
    }
  }
  return pairings;
}

function formatReport(pairings, customers) {
  const heights = new Map(customers.map(([name, height]) => [name, Number(height)]));
  const lines = pairings.map(([name, boardId]) => {
    const minLength = minimumBoardLength(heights.get(name));
    return `${name} (min ${minLength.toFixed(1)} cm) -> board ${boardId}`;
  });
  const unserved = customers.length - pairings.length;
  if (unserved > 0) {
    lines.push(`${unserved} customer(s) could not be matched.`);
  }
  return lines.join('\n');
}

function main() {
  const customers = [
    ['Jane', 161],
    ['Mohammed', 178],
    ['Kaylee', 152],
    ['Oliver', 191],
  ];
  const inventory = [
    ['B1', 150],
    ['B2', 164],
    ['B3', 142],
    ['B4', 158],
    ['B5', 172],
  ];

  const pairings = rentals(customers, inventory);
  console.log(formatReport(pairings, customers));
}

main();

