const MAX_CAPACITY = 100;
const HOURS = 24;

function microgrid(loads, solar, battery) {
  let charge = battery;
  let unmet = 0;
  for (let hour = 0; hour < HOURS; hour += 1) {
    const load = loads[hour];
    const generation = solar[hour];
    const netLoad = load - generation;
    if (netLoad > 0) {
      charge -= netLoad;
      if (charge < 0) {
        unmet += -charge;
        charge = 0;
      }
    } else if (netLoad < 0) {
      const surplus = -netLoad;
      charge = Math.min(charge + surplus, MAX_CAPACITY);
    }
  }
  return [charge, unmet];
}

function validateSeries(name, series) {
  if (!Array.isArray(series)) {
    throw new TypeError(`${name} must be an array`);
  }
  if (series.length !== HOURS) {
    throw new RangeError(`${name} must contain ${HOURS} hourly values`);
  }
  const badIndex = series.findIndex((value) => typeof value !== 'number' || Number.isNaN(value));
  if (badIndex !== -1) {
    throw new TypeError(`${name}[${badIndex}] is not a number`);
  }
}

function dailyProfile(peak, peakHour, width) {
  const profile = [];
  for (let hour = 0; hour < HOURS; hour += 1) {
    const distance = Math.abs(hour - peakHour);
    const value = peak * Math.exp(-(distance * distance) / (2 * width * width));
    profile.push(Math.round(value * 100) / 100);
  }
  return profile;
}

function report(loads, solar, battery) {
  validateSeries('loads', loads);
  validateSeries('solar', solar);
  if (typeof battery !== 'number' || battery < 0 || battery > MAX_CAPACITY) {
    throw new RangeError(`battery must be between 0 and ${MAX_CAPACITY}`);
  }
  const [finalCharge, totalUnmet] = microgrid(loads, solar, battery);
  const totalLoad = loads.reduce((sum, value) => sum + value, 0);
  const totalSolar = solar.reduce((sum, value) => sum + value, 0);
  const served = totalLoad - totalUnmet;
  const coverage = totalLoad === 0 ? 100 : (served / totalLoad) * 100;
  const lines = [
    `Total load:      ${totalLoad.toFixed(2)} units`,
    `Total solar:     ${totalSolar.toFixed(2)} units`,
    `Battery start:   ${battery.toFixed(2)} units`,
    `Battery end:     ${finalCharge.toFixed(2)} units`,
    `Unmet load:      ${totalUnmet.toFixed(2)} units`,
    `Load coverage:   ${coverage.toFixed(1)}%`,
  ];
  return lines.join('\n');
}

const houseLoads = dailyProfile(6, 19, 4).map((value, hour) => value + (hour < 6 ? 0.8 : 1.5));
const roofSolar = dailyProfile(9, 13, 3);
const startingCharge = 40;

console.log(report(houseLoads, roofSolar, startingCharge));

module.exports = { microgrid, report, dailyProfile, validateSeries };

