const BUYER_PREMIUM_RATE = 0.2;
const COMMISSION_RATE = 0.1;

function parseLot(lot) {
  const [id, reserve, bid] = lot;
  if (typeof id !== 'string' || id.length === 0) {
    throw new TypeError('lot identifier must be a non-empty string');
  }
  const reservePrice = Number(reserve);
  const highestBid = Number(bid);
  if (!Number.isFinite(reservePrice) || !Number.isFinite(highestBid)) {
    throw new TypeError(`lot ${id} has non-numeric prices`);
  }
  return { id, reservePrice, highestBid };
}

function settleLot(lot) {
  const { id, reservePrice, highestBid } = parseLot(lot);
  const sold = highestBid >= reservePrice;
  if (!sold) {
    return { id, sold, hammer: 0, premium: 0, commission: 0 };
  }
  const premium = highestBid * BUYER_PREMIUM_RATE;
  const commission = highestBid * COMMISSION_RATE;
  return { id, sold, hammer: highestBid, premium, commission };
}

function auction(lots) {
  if (!Array.isArray(lots)) {
    throw new TypeError('lots must be an array');
  }
  let hammerTotal = 0;
  let premiumTotal = 0;
  let commissionTotal = 0;
  for (const lot of lots) {
    const result = settleLot(lot);
    hammerTotal += result.hammer;
    premiumTotal += result.premium;
    commissionTotal += result.commission;
  }
  return [hammerTotal, premiumTotal, commissionTotal];
}

function formatReport(lots) {
  const lines = [];
  for (const lot of lots) {
    const result = settleLot(lot);
    const status = result.sold ? `sold for ${result.hammer}` : 'unsold';
    lines.push(`${result.id}: ${status}`);
  }
  const [hammer, premium, commission] = auction(lots);
  lines.push(`hammer total: ${hammer}`);
  lines.push(`buyer premiums: ${premium}`);
  lines.push(`commissions: ${commission}`);
  const proceeds = hammer + premium;
  lines.push(`gross proceeds: ${proceeds}`);
  return lines.join('\n');
}

function main() {
  const sale = [
    ['lot1', 100, 150],
    ['lot2', 200, 100],
    ['lot3', 500, 500],
    ['lot4', 750, 1200]
  ];
  console.log(formatReport(sale));
  const totals = auction(sale);
  console.log(`totals: [${totals.join(', ')}]`);
}

main();

module.exports = { auction, settleLot, formatReport };

