function spacing(groups, speed) {
  if (!Array.isArray(groups)) {
    throw new TypeError('groups must be a list of [name, speed] pairs');
  }
  const times = [];
  let clock = 0;
  for (let i = 0; i < groups.length; i += 1) {
    const entry = groups[i];
    if (!Array.isArray(entry) || entry.length !== 2) {
      throw new TypeError(`group at index ${i} must be [name, speed]`);
    }
    const walkSpeed = entry[1];
    if (typeof walkSpeed !== 'number' || !Number.isFinite(walkSpeed) || walkSpeed <= 0) {
      throw new RangeError(`group "${entry[0]}" has an invalid speed: ${walkSpeed}`);
    }
    if (i === 0) {
      times.push(clock);
      continue;
    }
    const previousSpeed = groups[i - 1][1];
    let interval = speed;
    if (previousSpeed < walkSpeed) {
      interval += 1;
    }
    clock += interval;
    times.push(clock);
  }
  return times;
}

function formatClock(minutes) {
  const hours = Math.floor(minutes / 60);
  const rest = minutes % 60;
  const padded = String(rest).padStart(2, '0');
  return `${hours}:${padded}`;
}

function buildSchedule(groups, speed) {
  const times = spacing(groups, speed);
  return groups.map((group, index) => {
    const [name, walkSpeed] = group;
    return {
      name,
      speed: walkSpeed,
      minute: times[index],
      clock: formatClock(times[index]),
    };
  });
}

function renderSchedule(schedule) {
  const lines = schedule.map((row) => {
    const label = row.name.padEnd(6, ' ');
    return `${label} ${String(row.minute).padStart(3, ' ')} min  (${row.clock})  ${row.speed} m/min`;
  });
  const last = schedule[schedule.length - 1];
  lines.push(`Total dispatch window: ${last ? last.minute : 0} minutes`);
  return lines.join('\n');
}

function main() {
  const guests = [['A', 50], ['B', 40], ['C', 60], ['D', 60], ['E', 35]];
  const baseInterval = 2;
  const schedule = buildSchedule(guests, baseInterval);
  console.log(renderSchedule(schedule));
  const raw = spacing([['A', 50], ['B', 40], ['C', 60]], 2);
  console.log(`Example: [${raw.join(', ')}]`);
}

main();

module.exports = { spacing, buildSchedule, renderSchedule, formatClock };

