      throw new RangeError(`group "${entry[0]}" has an invalid speed: ${walkSpeed}`);
    }
    if (i === 0) {
      times.push(clock);
      continue;
    }
    var previousSpeed = groups[i - 1][1];
    var interval = speed;
    if (previousSpeed < walkSpeed) {
      interval += 1;
    }
    clock += interval;
    times.push(clock);
  }
  return times;
}

function formatClock(minutes) {
  var hours = Math.floor(minutes / 60);
  var rest = minutes % 60;
  var padded = String(rest).padStart(2, '0');
  return `${hours}:${padded}`;
}

function buildSchedule(groups, speed) {
  var times = spacing(groups, speed);
  return groups.map((group, index) => {
    var [name, walkSpeed] = group;
    return {
      name,
      speed: walkSpeed,
      minute: times[index],
      clock: formatClock(times[index]),
    };
  });
}

function renderSchedule(schedule) {
  var lines = schedule.map((row) => {
    var label = row.name.padEnd(6, ' ');
    return `${label} ${String(row.minute).padStart(3, ' ')} min  (${row.clock})  ${row.speed} m/min`;
  });
  var last = schedule[schedule.length - 1];
  lines.push(`Total dispatch window: ${last ? last.minute : 0} minutes`);
  return lines.join('\n');
}

function main() {
  var guests = [['A', 50], ['B', 40], ['C', 60], ['D', 60], ['E', 35]];
  var baseInterval = 2;
  var schedule = buildSchedule(guests, baseInterval);
  console.log(renderSchedule(schedule));
  var raw = spacing([['A', 50], ['B', 40], ['C', 60]], 2);
  console.log(`Example: [${raw.join(', ')}]`);
}

main();

module.exports = { spacing, buildSchedule, renderSchedule, formatClock };

