const COMMERCIAL_CLASS = 'commercial';
const COMMERCIAL_SURCHARGE = 0.2;

function buildRateTable(rates) {
  const table = new Map();
  for (const entry of rates) {
    const [vesselClass, unitRate] = entry;
    if (typeof unitRate !== 'number' || Number.isNaN(unitRate)) {
      throw new TypeError(`Invalid rate for vessel class "${vesselClass}"`);
    }
    table.set(vesselClass, unitRate);
  }
  return table;
}

function transitFee(transit, rateTable) {
  const [registration, distance, vesselClass] = transit;
  if (typeof distance !== 'number' || Number.isNaN(distance) || distance < 0) {
    throw new RangeError(`Invalid distance for vessel ${registration}`);
  }
  if (!rateTable.has(vesselClass)) {
    throw new Error(`No tariff rate defined for vessel class "${vesselClass}"`);
  }
  const unitRate = rateTable.get(vesselClass);
  const baseFee = distance * unitRate;
  if (vesselClass === COMMERCIAL_CLASS) {
    return baseFee * (1 + COMMERCIAL_SURCHARGE);
  }
  return baseFee;
}

function tariff(transits, rates) {
  const rateTable = buildRateTable(rates);
  let total = 0;
  for (const transit of transits) {
    total += transitFee(transit, rateTable);
  }
  return total;
}

function transitReport(transits, rates) {
  const rateTable = buildRateTable(rates);
  const lines = [];
  for (const transit of transits) {
    const [registration, distance, vesselClass] = transit;
    const fee = transitFee(transit, rateTable);
    lines.push(`${registration.padEnd(8)} ${vesselClass.padEnd(12)} ${distance} km  ${fee.toFixed(2)}`);
  }
  const grandTotal = tariff(transits, rates);
  lines.push(`${'TOTAL'.padEnd(8)} ${''.padEnd(12)} ${''.padStart(6)}  ${grandTotal.toFixed(2)}`);
  return lines.join('\n');
}

function main() {
  const rates = [['yacht', 2], ['commercial', 5], ['tug', 3.5]];
  const transits = [
    ['XYZ', 10, 'yacht'],
    ['MARLIN', 42, 'commercial'],
    ['HERCULES', 18, 'tug'],
  ];
  console.log(transitReport(transits, rates));
  const singleTransit = tariff([['XYZ', 10, 'yacht']], rates);
  console.log(`Sample single transit fee: ${singleTransit}`);
}

main();

module.exports = { tariff, transitReport, buildRateTable, transitFee };

