const BASE_LOTION_PER_KG = 0.6;
const WATER_PER_KG = 0.4;
const ESSENTIAL_OIL_PER_KG = 0.05;

function cosmetics(batches) {
  let totalLotion = 0;
  let totalWater = 0;
  let totalOil = 0;

  for (const batch of batches) {
    const [name, weight, needsFragrance] = batch;
    if (typeof weight !== "number" || !isFinite(weight) || weight < 0) {
      throw new RangeError(`Batch "${name}" has an invalid output weight: ${weight}`);
    }
    totalLotion += weight * BASE_LOTION_PER_KG;
    totalWater += weight * WATER_PER_KG;
    if (needsFragrance) {
      totalOil += weight * ESSENTIAL_OIL_PER_KG;
    }
  }

  return [totalLotion, totalWater, totalOil];
}

function batchRequirements(batch) {
  const [name, weight, needsFragrance] = batch;
  const [lotion, water, oil] = cosmetics([batch]);
  return { name, weight, needsFragrance, lotion, water, oil };
}

function formatKg(value) {
  const rounded = Math.round(value * 1000) / 1000;
  return `${rounded.toFixed(3)} kg`;
}

function productionReport(batches) {
  const lines = ["Batch breakdown:"];

  for (const batch of batches) {
    const row = batchRequirements(batch);
    const fragranceNote = row.needsFragrance ? "with fragrance" : "unscented";
    lines.push(
      `  ${row.name} (${row.weight} kg, ${fragranceNote}): ` +
        `lotion ${formatKg(row.lotion)}, water ${formatKg(row.water)}, oil ${formatKg(row.oil)}`
    );
  }

  const [lotion, water, oil] = cosmetics(batches);
  const grandTotal = lotion + water + oil;
  lines.push("Totals:");
  lines.push(`  base lotion:   ${formatKg(lotion)}`);
  lines.push(`  water:         ${formatKg(water)}`);
  lines.push(`  essential oil: ${formatKg(oil)}`);
  lines.push(`  bulk weight:   ${formatKg(grandTotal)}`);

  return lines.join("\n");
}

function main() {
  const schedule = [
    ["Rose Day Cream", 120, true],
    ["Sensitive Night Cream", 80, false],
    ["Citrus Hand Cream", 45.5, true],
  ];

  console.log(productionReport(schedule));

  const [lotion, water, oil] = cosmetics(schedule);
  const drumsOfLotion = Math.ceil(lotion / 25);
  console.log(`\nBase lotion drums needed (25 kg each): ${drumsOfLotion}`);
  console.log(`Water-to-lotion ratio: ${(water / lotion).toFixed(2)}`);
  console.log(`Essential oil share: ${((oil / (lotion + water + oil)) * 100).toFixed(2)}%`);
}

main();

module.exports = { cosmetics, batchRequirements, productionReport };

