function findBin(layout, itemId) {
  for (const bin of layout) {
    const [id] = bin;
    if (id === itemId) {
      return bin;
    }
  }
  return null;
}

function validateOrders(orders, layout) {
  const missing = [];
  for (const [itemId, quantity] of orders) {
    const bin = findBin(layout, itemId);
    if (bin === null) {
      missing.push(itemId);
    } else if (!Number.isFinite(quantity) || quantity < 0) {
      throw new Error(`invalid quantity for item ${itemId}: ${quantity}`);
    }
  }
  if (missing.length > 0) {
    throw new Error(`items not found in layout: ${missing.join(', ')}`);
  }
}

function picker(orders, layout) {
  validateOrders(orders, layout);

  let currentLocation = 0;
  let totalDistance = 0;
  let carriedWeight = 0;

  for (const [itemId, quantity] of orders) {
    const bin = findBin(layout, itemId);
    const binDistance = bin[1];
    const unitWeight = bin[2];
    const moved = Math.abs(binDistance - currentLocation);

    totalDistance += moved;
    currentLocation = binDistance;
    carriedWeight += quantity * unitWeight;
  }

  totalDistance += currentLocation;
  return [totalDistance, carriedWeight];
}

function formatReport(orders, layout) {
  const [distance, weight] = picker(orders, layout);
  const lines = [];
  for (const [itemId, quantity] of orders) {
    const bin = findBin(layout, itemId);
    lines.push(`  ${quantity} x ${itemId} @ ${bin[1]} m (${quantity * bin[2]} kg)`);
  }
  const header = `Pick list (${orders.length} line items):`;
  const footer = `Walked ${distance} m carrying ${weight} kg`;
  return [header, ...lines, footer].join('\n');
}

function main() {
  const layout = [
    ['bolt', 12, 0.25],
    ['nut', 30, 0.1],
    ['washer', 18, 0.05],
    ['bracket', 45, 1.5],
  ];
  const orders = [
    ['nut', 40],
    ['bolt', 40],
    ['bracket', 3],
    ['washer', 100],
  ];

  console.log(formatReport(orders, layout));

  const singleTrip = picker([['bracket', 2]], layout);
  console.log(`Single trip: ${singleTrip[0]} m, ${singleTrip[1]} kg`);
}

main();

