const BERRIES_PER_CLUSTER = 100;
const GRAMS_PER_KILOGRAM = 1000;
const JUICE_LITERS_PER_KILOGRAM = 0.7;

function validateBlock(block) {
  if (!Array.isArray(block) || block.length !== 4) {
    throw new TypeError('each block needs an id, vine count, clusters per vine and berry weight');
  }
  const [id, vines, clustersPerVine, berryWeight] = block;
  if (typeof id !== 'string' || id.trim() === '') {
    throw new TypeError('block identifier must be a non-empty string');
  }
  for (const value of [vines, clustersPerVine, berryWeight]) {
    if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) {
      throw new RangeError(`block ${id} has an invalid measurement: ${value}`);
    }
  }
  return { id, vines, clustersPerVine, berryWeight };
}

function blockJuice(block) {
  const { id, vines, clustersPerVine, berryWeight } = validateBlock(block);
  const totalClusters = vines * clustersPerVine;
  const totalGrams = totalClusters * BERRIES_PER_CLUSTER * berryWeight;
  const totalKilograms = totalGrams / GRAMS_PER_KILOGRAM;
  return [id, totalKilograms * JUICE_LITERS_PER_KILOGRAM];
}

function harvest(blocks) {
  if (!Array.isArray(blocks)) {
    throw new TypeError('harvest expects a list of vineyard blocks');
  }
  const yields = [];
  for (const block of blocks) {
    yields.push(blockJuice(block));
  }
  return yields;
}

function formatReport(yields) {
  let widest = 0;
  for (const [id] of yields) {
    widest = Math.max(widest, id.length);
  }
  const lines = yields.map(([id, liters]) => {
    const label = id.padEnd(widest, ' ');
    const amount = liters.toFixed(1).padStart(10, ' ');
    return `${label}  ${amount} L`;
  });
  let total = 0;
  for (const [, liters] of yields) {
    total += liters;
  }
  const footer = `${'TOTAL'.padEnd(widest, ' ')}  ${total.toFixed(1).padStart(10, ' ')} L`;
  lines.push('-'.repeat(footer.length));
  lines.push(footer);
  return lines.join('\n');
}

function main() {
  const vineyard = [
    ['Hillside Cabernet', 4200, 28, 1.15],
    ['River Flat Merlot', 3100, 34, 1.4],
    ['North Terrace Syrah', 1850, 22, 0.95],
    ['Old Vine Zinfandel', 640, 18, 1.6],
  ];
  const yields = harvest(vineyard);
  console.log(formatReport(yields));
  const best = yields.reduce((a, b) => (b[1] > a[1] ? b : a));
  console.log(`\nTop block: ${best[0]} (${best[1].toFixed(1)} L)`);
}

main();

module.exports = { harvest, blockJuice, formatReport };

