var MAX_BUG_DAMAGE = 30;
var SOIL_PENALTY = 5;
var FLAVOR_MULTIPLIERS = [5, 3, 2, 1];

function isSafe(mushroom) {
  var { toxicity, bugDamage } = mushroom;
  return toxicity <= MAX_TOXICITY && bugDamage <= MAX_BUG_DAMAGE;
}

function baseWeight(mushroom) {
  var { grossWeight, bugDamage } = mushroom;
  var damaged = grossWeight * (bugDamage / 100);
  var trimmed = grossWeight - damaged - SOIL_PENALTY;
  return trimmed < 0 ? 0 : trimmed;
}

function edibility(mushroom) {
  var multiplier = FLAVOR_MULTIPLIERS[mushroom.toxicity];
  return baseWeight(mushroom) * multiplier;
}

function score(mushrooms) {
  var totalWeight = 0;
  var totalScore = 0;
  for (var mushroom of mushrooms) {
    if (!isSafe(mushroom)) continue;
    totalWeight += baseWeight(mushroom);
    totalScore += edibility(mushroom);
  }
  return [totalWeight, totalScore];
}

function parseMushroom(record) {
  var [grossWeight, toxicity, bugDamage] = record;
  if (toxicity < 0 || toxicity > 10) {
    throw new RangeError(`toxicity out of range: ${toxicity}`);
  }
  if (bugDamage < 0 || bugDamage > 100) {
    throw new RangeError(`bug damage out of range: ${bugDamage}`);
  }
  return { grossWeight, toxicity, bugDamage };
}

function report(records) {
  var mushrooms = records.map(parseMushroom);
  var kept = mushrooms.filter(isSafe);
  var [weight, points] = score(mushrooms);
  var lines = kept.map((mushroom) => {
    var grams = baseWeight(mushroom).toFixed(1);
    return `  tox ${mushroom.toxicity}, ${mushroom.bugDamage}% bugs -> ${grams} g, ${edibility(mushroom).toFixed(1)} pts`;
  });
  var discarded = mushrooms.length - kept.length;
  lines.push(`  discarded: ${discarded}`);
  lines.push(`  totals: ${weight.toFixed(1)} g, ${points.toFixed(1)} pts`);
  return lines.join('\n');
}

var harvest = [
  [100, 0, 10],
  [80, 2, 25],
  [50, 4, 0],
  [120, 1, 45],
  [4, 3, 0],
];

console.log(report(harvest));

module.exports = { score, report, parseMushroom, baseWeight, edibility, isSafe };

