const LIFT_COEFFICIENT = 1.2;
const DRAG_COEFFICIENT = 0.8;
const SAG_FACTOR = 10;
const BREAKING_TENSION = 500;

function readConditions(conditions) {
  if (Array.isArray(conditions)) {
    const [windSpeed, airDensity, area] = conditions;
    return { windSpeed, airDensity, area };
  }
  if (conditions === null || typeof conditions !== 'object') {
    throw new TypeError('conditions must be an array or an object of readings');
  }
  const windSpeed = conditions.windSpeed;
  const airDensity = conditions.airDensity;
  const area = conditions.area;
  return { windSpeed, airDensity, area };
}

function validate(reading) {
  const names = ['windSpeed', 'airDensity', 'area'];
  for (const name of names) {
    const value = reading[name];
    if (typeof value !== 'number' || !Number.isFinite(value) || value <= 0) {
      throw new RangeError(`${name} must be a positive finite number`);
    }
  }
  return reading;
}

function aerodynamicForce(reading, coefficient) {
  const dynamicPressure = 0.5 * reading.airDensity * reading.windSpeed * reading.windSpeed;
  return dynamicPressure * reading.area * coefficient;
}

function lineSagForce(reading) {
  const sagRatio = (reading.airDensity * reading.area) / reading.windSpeed;
  return sagRatio * SAG_FACTOR;
}

function tension(conditions) {
  const reading = validate(readConditions(conditions));
  const lift = aerodynamicForce(reading, LIFT_COEFFICIENT);
  const drag = aerodynamicForce(reading, DRAG_COEFFICIENT);
  const resultant = Math.sqrt(lift * lift + drag * drag);
  const total = resultant + lineSagForce(reading);
  const holds = total <= BREAKING_TENSION;
  return [holds, Math.round(total)];
}

function formatReport(conditions) {
  const reading = readConditions(conditions);
  const [holds, newtons] = tension(conditions);
  const verdict = holds ? 'holds' : 'breaks';
  return `wind ${reading.windSpeed} m/s, density ${reading.airDensity}, area ${reading.area} m^2 ` +
    `-> ${newtons} N, string ${verdict}`;
}

module.exports = { tension, formatReport, lineSagForce };

