const BASE_CREASES = { bird: 16, frog: 24 };
const DEFAULT_BASE_CREASES = 8;
const BASE_THICKNESS_MM = 0.1;
const CREASES_PER_DOUBLING = 10;

function startingCreases(baseType) {
  const key = String(baseType).trim().toLowerCase();
  return Object.prototype.hasOwnProperty.call(BASE_CREASES, key)
    ? BASE_CREASES[key]
    : DEFAULT_BASE_CREASES;
}

function totalCreases(baseType, points, detailLevel) {
  const start = startingCreases(baseType);
  return start + points * points * detailLevel;
}

function maxThickness(creases) {
  const doublings = Math.floor(creases / CREASES_PER_DOUBLING);
  return BASE_THICKNESS_MM * Math.pow(2, doublings);
}

function foldingTime(creases, thickness) {
  return creases * 0.5 + thickness * 2;
}

function round2(value) {
  return Math.round(value * 100) / 100;
}

function normalizeDesign(design) {
  const points = Number(design.points);
  const detailLevel = Number(design.detailLevel);
  if (!Number.isFinite(points) || points < 0) {
    throw new RangeError(`invalid point count: ${design.points}`);
  }
  if (!Number.isInteger(detailLevel) || detailLevel < 0) {
    throw new RangeError(`invalid detail level: ${design.detailLevel}`);
  }
  return { baseType: design.baseType, points, detailLevel };
}

function fold(designs) {
  return designs.map((design) => {
    const plan = normalizeDesign(design);
    const creases = totalCreases(plan.baseType, plan.points, plan.detailLevel);
    const thickness = maxThickness(creases);
    return {
      maxThickness: round2(thickness),
      foldingTime: round2(foldingTime(creases, thickness)),
    };
  });
}

function report(designs) {
  const results = fold(designs);
  return designs.map((design, index) => {
    const result = results[index];
    const creases = totalCreases(design.baseType, design.points, design.detailLevel);
    return `${design.baseType} (${design.points} pts, detail ${design.detailLevel}): ` +
      `${creases} creases, ${result.maxThickness} mm, ${result.foldingTime} min`;
  }).join('\n');
}

function main() {
  const plans = [
    { baseType: 'bird', points: 4, detailLevel: 2 },
    { baseType: 'frog', points: 5, detailLevel: 1 },
    { baseType: 'kite', points: 3, detailLevel: 3 },
  ];
  console.log(report(plans));
}

main();

module.exports = { fold, report, totalCreases, maxThickness, foldingTime };

