const MONTHLY_LOSS_RATE = 0.015;
const MIN_AGING_MONTHS = 6;
const PRICE_PER_KG = 20;
const PREMIUM = 5;
const PREMIUM_MONTHS = 12;

function round2(value) {
  return Math.round(value * 100) / 100;
}

function finalWeight(initialWeight, months) {
  const retention = 1 - MONTHLY_LOSS_RATE;
  let weight = initialWeight;
  for (let month = 0; month < months; month += 1) {
    weight *= retention;
  }
  return weight;
}

function lossPercentage(initialWeight, months) {
  const remaining = finalWeight(initialWeight, months);
  return ((initialWeight - remaining) / initialWeight) * 100;
}

function isReady(wheel) {
  const loss = lossPercentage(wheel.weight, wheel.months);
  return loss >= wheel.target && wheel.months >= MIN_AGING_MONTHS;
}

function sellingPrice(wheel) {
  const base = finalWeight(wheel.weight, wheel.months) * PRICE_PER_KG;
  const premium = wheel.months > PREMIUM_MONTHS ? PREMIUM : 0;
  return round2(base + premium);
}

function normalize(wheel) {
  const weight = Number(wheel.weight);
  const months = Number(wheel.months);
  const target = Number(wheel.target);
  if (!(weight > 0) || !Number.isInteger(months) || months < 0 || !(target >= 0)) {
    throw new TypeError(`invalid cheese wheel: ${JSON.stringify(wheel)}`);
  }
  return { weight, months, target };
}

function inspect(wheels) {
  let readyCount = 0;
  let revenue = 0;
  for (const raw of wheels) {
    const wheel = normalize(raw);
    if (isReady(wheel)) {
      readyCount += 1;
      revenue += sellingPrice(wheel);
    }
  }
  return [readyCount, round2(revenue)];
}

function report(wheels) {
  const lines = wheels.map((raw) => {
    const wheel = normalize(raw);
    const remaining = round2(finalWeight(wheel.weight, wheel.months));
    const loss = round2(lossPercentage(wheel.weight, wheel.months));
    const status = isReady(wheel) ? `ready at $${sellingPrice(wheel).toFixed(2)}` : 'not ready';
    return `${wheel.weight}kg / ${wheel.months}mo -> ${remaining}kg (-${loss}%, target ${wheel.target}%): ${status}`;
  });
  const [count, total] = inspect(wheels);
  lines.push(`${count} wheel(s) ready, total $${total.toFixed(2)}`);
  return lines.join('\n');
}

const cellar = [
  { weight: 10, months: 8, target: 10 },
  { weight: 4.5, months: 18, target: 20 },
  { weight: 12, months: 4, target: 5 },
  { weight: 7, months: 10, target: 25 },
];

console.log(report(cellar));

module.exports = { inspect, finalWeight, lossPercentage, isReady, sellingPrice, report };

