const BASE_BURN_RATE = 0.5;
const BINDER_PENALTY = 0.2;
const CORE_DELAY_MINUTES = 10;
const THICK_STICK_MM = 3;
const PI = 3.14;

function quantizeRate(rate) {
  const scaled = Math.floor(rate * 100);
  return scaled / 100;
}

function adjustedBurnRate(thickness, binderRatio) {
  const thicknessRate = BASE_BURN_RATE / thickness;
  const binderFactor = 1 - binderRatio * BINDER_PENALTY;
  return quantizeRate(thicknessRate * binderFactor);
}

function burnTimeMinutes(length, thickness, binderRatio) {
  const rate = adjustedBurnRate(thickness, binderRatio);
  let minutes = length / rate;
  if (thickness > THICK_STICK_MM) {
    minutes += CORE_DELAY_MINUTES;
  }
  return Math.round(minutes);
}

function smokeVolume(length, thickness) {
  const volume = length * thickness * thickness * PI;
  return Math.round(volume);
}

function validateStick(stick, index) {
  const { length, thickness, binderRatio } = stick;
  if (!(length > 0) || !(thickness > 0)) {
    throw new RangeError(`stick ${index}: length and thickness must be positive`);
  }
  if (binderRatio < 0 || binderRatio >= 5) {
    throw new RangeError(`stick ${index}: binder ratio ${binderRatio} is out of range`);
  }
}

function burn(sticks) {
  return sticks.map((stick, index) => {
    validateStick(stick, index);
    const { length, thickness, binderRatio } = stick;
    return {
      burnTime: burnTimeMinutes(length, thickness, binderRatio),
      smokeVolume: smokeVolume(length, thickness)
    };
  });
}

function formatReport(sticks, results) {
  const lines = results.map((result, index) => {
    const stick = sticks[index];
    const label = `${stick.length}cm x ${stick.thickness}mm (binder ${stick.binderRatio})`;
    return `${label}: ${result.burnTime} min, smoke ${result.smokeVolume}`;
  });
  const totalTime = results.reduce((sum, result) => sum + result.burnTime, 0);
  lines.push(`total burn time: ${totalTime} min`);
  return lines.join('\n');
}

const inventory = [
  { length: 20, thickness: 2, binderRatio: 0.1 },
  { length: 30, thickness: 4, binderRatio: 0.25 },
  { length: 12, thickness: 1.5, binderRatio: 0 }
];

const burned = burn(inventory);
console.log(formatReport(inventory, burned));

