const SOAK_FACTOR = 2;
const OPAQUE_TINT_THRESHOLD = 5;
const OPAQUE_EXTRA_SOAK = 1;
const BASE_COOLING_RATE = 20;
const SOAK_POWER_KW = 15;
const COOL_POWER_KW = 5;
const START_TEMP = 900;
const END_TEMP = 400;

function roundTenth(value) {
  return Math.round(value * 10) / 10;
}

function soakTime(thickness, tint) {
  const base = thickness * thickness * SOAK_FACTOR;
  const extra = tint > OPAQUE_TINT_THRESHOLD ? OPAQUE_EXTRA_SOAK : 0;
  return base + extra;
}

function coolingRate(thickness) {
  return BASE_COOLING_RATE / thickness;
}

function coolingTime(thickness) {
  const span = START_TEMP - END_TEMP;
  return span / coolingRate(thickness);
}

function energyCost(soak, cooling) {
  return soak * SOAK_POWER_KW + cooling * COOL_POWER_KW;
}

function anneal(pieces) {
  return pieces.map((piece, index) => {
    const { thickness, tint } = piece;
    if (!(thickness > 0)) {
      throw new RangeError(`piece ${index}: thickness must be positive`);
    }
    if (!Number.isInteger(tint)) {
      throw new TypeError(`piece ${index}: tint must be an integer`);
    }
    const soak = soakTime(thickness, tint);
    const cooling = coolingTime(thickness);
    const total = soak + cooling;
    return [roundTenth(total), roundTenth(energyCost(soak, cooling))];
  });
}

function formatSchedule(pieces) {
  const results = anneal(pieces);
  const lines = results.map(([time, energy], index) => {
    const piece = pieces[index];
    const label = `${piece.thickness}" tint ${piece.tint}`;
    return `${label.padEnd(16)} ${time} h   ${energy} kWh`;
  });
  const totalEnergy = results.reduce((sum, [, energy]) => sum + energy, 0);
  lines.push(`Total energy: ${roundTenth(totalEnergy)} kWh`);
  return lines.join('\n');
}

const batch = [
  { thickness: 1, tint: 3 },
  { thickness: 0.5, tint: 7 },
  { thickness: 2, tint: 6 },
  { thickness: 1.25, tint: 0 },
];

console.log(formatSchedule(batch));

module.exports = { anneal, formatSchedule, soakTime, coolingTime, coolingRate };

