const MIN_TARGET_DISTANCE = 5;

function distance(a, b) {
  const dx = a[0] - b[0];
  const dy = a[1] - b[1];
  return Math.sqrt(dx * dx + dy * dy);
}

function distancesTo(target, balls) {
  return balls.map((ball) => distance(ball, target));
}

function minDistance(distances) {
  return distances.reduce((best, d) => (d < best ? d : best), Infinity);
}

function scoreRound(round) {
  const { target, red, blue } = round;
  const targetDistance = distance(target, [0, 0]);
  if (targetDistance < MIN_TARGET_DISTANCE) {
    return [0, 0];
  }
  const redDistances = distancesTo(target, red);
  const blueDistances = distancesTo(target, blue);
  const redBest = minDistance(redDistances);
  const blueBest = minDistance(blueDistances);
  if (redBest < blueBest) {
    return [redDistances.filter((d) => d < blueBest).length, 0];
  }
  if (blueBest < redBest) {
    return [0, blueDistances.filter((d) => d < redBest).length];
  }
  return [0, 0];
}

function normalizeRound(round) {
  if (Array.isArray(round)) {
    const [target, red, blue] = round;
    return { target, red: red || [], blue: blue || [] };
  }
  const red = round.red || round.redBalls || [];
  const blue = round.blue || round.blueBalls || [];
  return { target: round.target || round.ball, red, blue };
}

function score(rounds) {
  let redTotal = 0;
  let blueTotal = 0;
  for (const round of rounds) {
    const [redPoints, bluePoints] = scoreRound(normalizeRound(round));
    redTotal += redPoints;
    blueTotal += bluePoints;
  }
  return [redTotal, blueTotal];
}

function formatScore(rounds) {
  const [red, blue] = score(rounds);
  const leader = red === blue ? 'a draw' : red > blue ? 'red leads' : 'blue leads';
  return `red ${red} - blue ${blue} (${leader})`;
}

const sampleRounds = [
  { target: [0, 10], red: [[0, 8], [0, 14], [3, 10]], blue: [[0, 13], [5, 10]] },
  { target: [3, 3], red: [[3, 4]], blue: [[9, 9]] },
  [[6, 8], [[6, 9], [7, 8]], [[6, 12]]],
];

console.log(formatScore(sampleRounds));

module.exports = { score, scoreRound, distance, formatScore };

