const ABV_FACTOR = 131.25;
const SUGAR_FACTOR = 1000;
const CARBONATION_FACTOR = 0.5;
const MAX_CARBONATION = 3;
const STRESS_THRESHOLD = 8;
const REFERENCE_TEMPERATURE = 10;

function round2(value) {
  const scaled = Math.round(value * 100);
  return scaled / 100;
}

function validateVat(vat, index) {
  const label = `vat ${index + 1}`;
  if (vat === null || typeof vat !== 'object') {
    throw new TypeError(`${label}: expected an object with gravity readings`);
  }
  const fields = ['initialGravity', 'currentGravity', 'temperature'];
  for (const field of fields) {
    const reading = vat[field];
    if (typeof reading !== 'number' || !Number.isFinite(reading)) {
      throw new TypeError(`${label}: ${field} must be a finite number`);
    }
  }
  if (vat.temperature === REFERENCE_TEMPERATURE) {
    throw new RangeError(`${label}: temperature must differ from ${REFERENCE_TEMPERATURE}`);
  }
}

function analyseVat(vat) {
  const gravityDrop = vat.initialGravity - vat.currentGravity;
  const abv = gravityDrop * ABV_FACTOR;
  const rawSpeed = gravityDrop / (vat.temperature - REFERENCE_TEMPERATURE);
  const speed = abv > STRESS_THRESHOLD ? rawSpeed / 2 : rawSpeed;
  const residualSugar = (vat.currentGravity - 1) * SUGAR_FACTOR;
  const carbonation = Math.min(residualSugar * CARBONATION_FACTOR, MAX_CARBONATION);
  return { abv, carbonation, speed, residualSugar };
}

function ferment(vats) {
  if (!Array.isArray(vats)) {
    throw new TypeError('ferment expects a list of cider batches');
  }
  return vats.map((vat, index) => {
    validateVat(vat, index);
    const analysis = analyseVat(vat);
    return { abv: round2(analysis.abv), carbonation: round2(analysis.carbonation) };
  });
}

function fermentReport(vats) {
  const lines = [];
  vats.forEach((vat, index) => {
    validateVat(vat, index);
    const { abv, carbonation, speed, residualSugar } = analyseVat(vat);
    const stressed = abv > STRESS_THRESHOLD ? ' (yeast stressed)' : '';
    lines.push(
      `Batch ${index + 1}: ${round2(abv)}% ABV, ${round2(carbonation)} vols CO2, ` +
        `${round2(residualSugar)} g/L sugar, speed ${speed.toFixed(5)}/deg${stressed}`
    );
  });
  return lines.join('\n');
}

const cellar = [
  { initialGravity: 1.05, currentGravity: 1.01, temperature: 20 },
  { initialGravity: 1.08, currentGravity: 1.0, temperature: 18 },
  { initialGravity: 1.045, currentGravity: 1.002, temperature: 15 }
];

console.log(fermentReport(cellar));
const results = ferment(cellar);
for (const result of results) {
  console.log(`${result.abv}% / ${result.carbonation} vols`);
}

