const GARGOYLE_CAPACITY = 15;
const GRAVITY = 9.8;
const FALL_HEIGHT = 10;

function collectedPerMinute(area, intensity) {
  return (area * intensity) / 60;
}

function totalCapacity(spouts) {
  return spouts * GARGOYLE_CAPACITY;
}

function excessWater(collected, capacity) {
  const overflow = collected - capacity;
  return overflow > 0 ? overflow : 0;
}

function expelledPerSpout(collected, spouts) {
  if (spouts <= 0) {
    return 0;
  }
  const share = collected / spouts;
  return Math.min(share, GARGOYLE_CAPACITY);
}

function kineticEnergy(volume) {
  return volume * GRAVITY * FALL_HEIGHT;
}

function validate(building, index) {
  const { area, intensity, spouts } = building;
  const numbers = [area, intensity, spouts];
  for (const value of numbers) {
    if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) {
      throw new RangeError(`building ${index}: area, intensity and spouts must be non-negative numbers`);
    }
  }
  return { area, intensity, spouts };
}

function flow(buildings) {
  const results = [];
  buildings.forEach((building, index) => {
    const { area, intensity, spouts } = validate(building, index);
    const collected = collectedPerMinute(area, intensity);
    const capacity = totalCapacity(spouts);
    const excess = excessWater(collected, capacity);
    const expelled = expelledPerSpout(collected, spouts);
    results.push({
      collected,
      capacity,
      excess,
      flooded: excess > 0,
      expelledPerSpout: expelled,
      spoutKineticEnergy: kineticEnergy(expelled),
    });
  });
  return results;
}

function report(buildings) {
  const rows = flow(buildings);
  const lines = rows.map((row, index) => {
    const state = row.flooded ? `flooded by ${row.excess.toFixed(1)} L/min` : 'draining freely';
    const energy = row.spoutKineticEnergy.toFixed(1);
    return `roof ${index + 1}: ${row.collected.toFixed(1)} L/min collected, ${state}, ` +
      `each spout expels ${row.expelledPerSpout.toFixed(1)} L/min at ${energy} J`;
  });
  return lines.join('\n');
}

const cityBlock = [
  { area: 100, intensity: 60, spouts: 5 },
  { area: 240, intensity: 25, spouts: 8 },
  { area: 80, intensity: 12, spouts: 0 },
];

console.log(report(cityBlock));

module.exports = { flow, report, collectedPerMinute, totalCapacity, kineticEnergy };

