const JUNIPER_WINTER_PENALTY = 0.1;
const FERTILIZER_GRAMS_PER_LEAF = 0.01;

function effectiveGrowthRate(tree) {
  const species = String(tree.species).trim().toLowerCase();
  if (species === 'juniper') {
    return tree.growthRate * (1 - JUNIPER_WINTER_PENALTY);
  }
  return tree.growthRate;
}

function weeksUntilPruning(tree) {
  const headroom = tree.maxLeaves - tree.leaves;
  if (headroom <= 0) {
    return 0;
  }
  const rate = effectiveGrowthRate(tree);
  if (rate <= 0) {
    return Infinity;
  }
  return Math.ceil(headroom / rate);
}

function fertilizerPerWeek(tree) {
  return tree.leaves * FERTILIZER_GRAMS_PER_LEAF;
}

function validateTree(tree, index) {
  const numericFields = ['leaves', 'growthRate', 'maxLeaves'];
  for (const field of numericFields) {
    const value = tree[field];
    if (typeof value !== 'number' || !Number.isFinite(value)) {
      throw new TypeError(`tree at index ${index} has an invalid ${field}`);
    }
  }
  if (typeof tree.species !== 'string' || tree.species.trim() === '') {
    throw new TypeError(`tree at index ${index} is missing a species name`);
  }
}

function prune(trees) {
  if (!Array.isArray(trees) || trees.length === 0) {
    throw new Error('prune requires a non-empty list of trees');
  }
  trees.forEach(validateTree);

  let urgent = trees[0];
  let urgentWeeks = weeksUntilPruning(trees[0]);
  for (let i = 1; i < trees.length; i += 1) {
    const candidateWeeks = weeksUntilPruning(trees[i]);
    if (candidateWeeks < urgentWeeks) {
      urgent = trees[i];
      urgentWeeks = candidateWeeks;
    }
  }
  return [urgent.species, urgentWeeks, fertilizerPerWeek(urgent)];
}

function describeSchedule(trees) {
  const [species, weeks, fertilizer] = prune(trees);
  const timing = weeks === Infinity ? 'never' : `in ${weeks} week(s)`;
  return `Prune the ${species} ${timing}; feed it ${fertilizer.toFixed(2)} g/week.`;
}

const nursery = [
  { species: 'pine', leaves: 50, growthRate: 10, maxLeaves: 90 },
  { species: 'juniper', leaves: 120, growthRate: 20, maxLeaves: 200 },
  { species: 'maple', leaves: 80, growthRate: 5, maxLeaves: 150 }
];

console.log(describeSchedule(nursery));

