const RIDER_WEIGHT_KG = 80;
const FLOAT_MARGIN_KG = 10;

function normalizeBoard(board) {
  if (Array.isArray(board)) {
    const [length, width, thickness, density] = board;
    return { length, width, thickness, density };
  }
  return board;
}

function validateBoard(board, index) {
  const fields = ['length', 'width', 'thickness', 'density'];
  for (const field of fields) {
    const value = board[field];
    if (typeof value !== 'number' || !Number.isFinite(value) || value <= 0) {
      throw new TypeError(`board ${index}: ${field} must be a positive finite number`);
    }
  }
  return board;
}

function volumeInLiters(board) {
  const cubicCentimeters = board.length * board.width * board.thickness;
  return cubicCentimeters / 1000;
}

function dragCoefficient(board) {
  return board.width / board.length + board.thickness * 0.1;
}

function analyzeBoard(board, index) {
  const spec = validateBoard(normalizeBoard(board), index);
  const volume = volumeInLiters(spec);
  const buoyantForce = volume;
  const boardWeight = volume * spec.density;
  const totalWeight = RIDER_WEIGHT_KG + boardWeight;
  return {
    volume,
    drag: dragCoefficient(spec),
    buoyantForce,
    totalWeight,
    floatsPerfectly: buoyantForce > totalWeight + FLOAT_MARGIN_KG,
  };
}

function float(boards) {
  const perfect = [];
  boards.forEach((board, index) => {
    const result = analyzeBoard(board, index);
    if (result.floatsPerfectly) {
      perfect.push({ volume: result.volume, drag: result.drag });
    }
  });
  return perfect;
}

function formatReport(boards) {
  const lines = boards.map((board, index) => {
    const result = analyzeBoard(board, index);
    const verdict = result.floatsPerfectly ? 'floats perfectly' : 'sinks under load';
    const volume = result.volume.toFixed(2);
    const drag = result.drag.toFixed(2);
    return `board ${index}: ${volume} L, drag ${drag}, needs ${result.totalWeight.toFixed(2)} kg -> ${verdict}`;
  });
  return lines.join('\n');
}

function main() {
  const catalogue = [
    { length: 200, width: 50, thickness: 5, density: 0.04 },
    { length: 305, width: 60, thickness: 10, density: 0.03 },
    [240, 55, 7, 0.05],
  ];
  console.log(formatReport(catalogue));
  const floating = float(catalogue);
  console.log(`boards that float perfectly: ${floating.length}`);
  for (const board of floating) {
    console.log(`  ${board.volume.toFixed(2)} L / drag ${board.drag.toFixed(2)}`);
  }
}

main();

module.exports = { float, analyzeBoard, volumeInLiters, dragCoefficient, formatReport };

