      throw new TypeError(`board ${index}: ${field} must be a positive finite number`);
    }
  }
  return board;
}

function volumeInLiters(board) {
  var cubicCentimeters = board.length * board.width * board.thickness;
  return cubicCentimeters / 1000;
}

function dragCoefficient(board) {
  return board.width / board.length + board.thickness * 0.1;
}

function analyzeBoard(board, index) {
  var spec = validateBoard(normalizeBoard(board), index);
  var volume = volumeInLiters(spec);
  var buoyantForce = volume;
  var boardWeight = volume * spec.density;
  var totalWeight = RIDER_WEIGHT_KG + boardWeight;
  return {
    volume,
    drag: dragCoefficient(spec),
    buoyantForce,
    totalWeight,
    floatsPerfectly: buoyantForce > totalWeight + FLOAT_MARGIN_KG,
  };
}

function float(boards) {
  var perfect = [];
  boards.forEach((board, index) => {
    var result = analyzeBoard(board, index);
    if (result.floatsPerfectly) {
      perfect.push({ volume: result.volume, drag: result.drag });
    }
  });
  return perfect;
}

function formatReport(boards) {
  var lines = boards.map((board, index) => {
    var result = analyzeBoard(board, index);
    var verdict = result.floatsPerfectly ? 'floats perfectly' : 'sinks under load';
    var volume = result.volume.toFixed(2);
    var drag = result.drag.toFixed(2);
    return `board ${index}: ${volume} L, drag ${drag}, needs ${result.totalWeight.toFixed(2)} kg -> ${verdict}`;
  });
  return lines.join('\n');
}

function main() {
  var catalogue = [
    { length: 200, width: 50, thickness: 5, density: 0.04 },
    { length: 305, width: 60, thickness: 10, density: 0.03 },
    [240, 55, 7, 0.05],
  ];
  console.log(formatReport(catalogue));
  var floating = float(catalogue);
  console.log(`boards that float perfectly: ${floating.length}`);
  for (var board of floating) {
    console.log(`  ${board.volume.toFixed(2)} L / drag ${board.drag.toFixed(2)}`);
  }
}

main();

module.exports = { float, analyzeBoard, volumeInLiters, dragCoefficient, formatReport };

