const OVERHANG_THRESHOLD = 10;
const ANGLE_PENALTY_PER_DEGREE = 2;
const MINUTES_PER_METER = 2;
const MINUTES_PER_OVERHANG_DEGREE = 5;
const LONG_REACH_THRESHOLD = 20;
const LONG_REACH_FACTOR = 1.5;

function averageHoldSize(holds) {
  let total = 0;
  for (const size of holds) {
    if (!Number.isFinite(size) || size < 1 || size > 10) {
      throw new RangeError(`hold size must be between 1 and 10, got ${size}`);
    }
    total += size;
  }
  return total / holds.length;
}

function overhangDegrees(angle) {
  const excess = angle - OVERHANG_THRESHOLD;
  return excess > 0 ? excess : 0;
}

function difficultyScore(height, angle, holds) {
  const avgSize = averageHoldSize(holds);
  const base = height / avgSize;
  const penalty = ANGLE_PENALTY_PER_DEGREE * overhangDegrees(angle);
  let difficulty = base + penalty;
  if (holds.length < LONG_REACH_THRESHOLD) {
    difficulty *= LONG_REACH_FACTOR;
  }
  return Math.round(difficulty);
}

function climbTime(height, angle) {
  const walking = height * MINUTES_PER_METER;
  return walking + MINUTES_PER_OVERHANG_DEGREE * overhangDegrees(angle);
}

function grade(routes) {
  const graded = [];
  for (const route of routes) {
    const { height, angle, holds } = route;
    if (!Array.isArray(holds) || holds.length === 0) {
      throw new TypeError('each route needs at least one hold size');
    }
    if (!Number.isFinite(height) || height <= 0) {
      throw new RangeError(`route height must be positive, got ${height}`);
    }
    graded.push([difficultyScore(height, angle, holds), climbTime(height, angle)]);
  }
  return graded;
}

function report(routes) {
  const results = grade(routes);
  const lines = results.map(([score, time], index) => {
    const name = routes[index].name ?? `route ${index + 1}`;
    return `${name}: grade ${score}, about ${time} min`;
  });
  return lines.join('\n');
}

const testRoutes = [
  { name: 'Slab Warmup', height: 20, angle: 0, holds: new Array(24).fill(2) },
  { name: 'Crimp Cave', height: 18, angle: 25, holds: [1, 2, 1, 3, 2, 1, 2, 2] },
  { name: 'Jug Highway', height: 40, angle: 12, holds: new Array(30).fill(8) },
];

console.log(report(testRoutes));

module.exports = { grade, report, difficultyScore, climbTime };

