  var counter = 0;

  for (var i = integerDigits - 1; i >= 0; i--) {
    var char = integerPart[i];
    buffer.unshift(char);
    counter++;
    if (counter % 3 === 0 && i !== 0) {
      buffer.unshift(',');
    }
  }

  var resultInteger = buffer.join('');
  var finalString = `${currencySymbol}${resultInteger}.${decimalPart}`;
  return finalString;
}

