const formatCountdown = (totalSeconds) => {
  const SECONDS_IN_MINUTE = 60;
  let minutes = Math.floor(totalSeconds / SECONDS_IN_MINUTE);
  let remainingSeconds = totalSeconds % SECONDS_IN_MINUTE;

  const padZero = (num) => {
    let numString = String(num);
    const PADDING_LENGTH = 2;
    return numString.padStart(PADDING_LENGTH, '0');
  };

  let formattedMinutes = padZero(minutes);
  let formattedSeconds = padZero(remainingSeconds);

  const SEPARATOR = ':';
  let result = formattedMinutes + SEPARATOR + formattedSeconds;
  return result;
};

