    var numString = String(num);
    var PADDING_LENGTH = 2;
    return numString.padStart(PADDING_LENGTH, '0');
  };

  var formattedMinutes = padZero(minutes);
  var formattedSeconds = padZero(remainingSeconds);

  var SEPARATOR = ':';
  var result = formattedMinutes + SEPARATOR + formattedSeconds;
  return result;
};

