function formatDateToDMY(dateObj) {
  const day = dateObj.getDate();
  const month = dateObj.getMonth() + 1;
  const year = dateObj.getFullYear();

  let formattedDay;
  if (day < 10) {
    formattedDay = '0' + day;
  } else {
    formattedDay = day.toString();
  }

  let formattedMonth;
  if (month < 10) {
    formattedMonth = '0' + month;
  } else {
    formattedMonth = month.toString();
  }

  const yearString = year.toString();
  const separator = '/';

  let result = formattedDay + separator + formattedMonth + separator + yearString;
  return result;
}

