var WORD_PATTERN = /[A-Za-z0-9]+(?:'[A-Za-z]+)*/g;

function tokenize(text) {
  if (typeof text !== 'string') {
    throw new TypeError('extractUniqueWords expects a string');
  }
  var matches = text.match(WORD_PATTERN);
  return matches === null ? [] : matches;
}

function extractUniqueWords(text) {
  var seen = new Set();
  var unique = [];
  for (var token of tokenize(text)) {
    var word = token.toLowerCase();
    if (!seen.has(word)) {
      seen.add(word);
      unique.push(word);
    }
  }
  return unique;
}

function countWords(text) {
  var counts = new Map();
  for (var token of tokenize(text)) {
    var word = token.toLowerCase();
    var current = counts.get(word) || 0;
    counts.set(word, current + 1);
  }
  return counts;
}

function formatReport(text) {
  var words = extractUniqueWords(text);
  var counts = countWords(text);
  var total = 0;
  for (var count of counts.values()) {
    total += count;
