function rotateArray(nums, k) {
  let n = nums.length;
  let effectiveK = k % n;

  if (effectiveK === 0) {
    return nums;
  }

  const tempArray = [];
  let i = 0;
  let copyIndex = n - effectiveK;

  while (copyIndex < n) {
    tempArray[i] = nums[copyIndex];
    i++;
    copyIndex++;
  }

  let originalStart = 0;
  let shiftIndex = 0;

  while (originalStart < n - effectiveK) {
    tempArray[i + shiftIndex] = nums[originalStart];
    shiftIndex++;
    originalStart++;
  }

  let finalArray = [];
  for (let j = 0; j < n; j++) {
    finalArray[j] = tempArray[j];
  }

  return finalArray;
}

