var longestPalindromeSubstring = (s) => {
  var maxLength = 0;
  var start = 0;
  var n = s.length;

  if (n < 2) {
    return s;
  }

  for (var i = 0; i < n; i++) {
    var left = i;
    var right = i;

    while (left >= 0 && right < n && s[left] === s[right]) {
      var currentLength = right - left + 1;
      if (currentLength > maxLength) {
        maxLength = currentLength;
        start = left;
      }
      left--;
      right++;
    }

    left = i;
    right = i + 1;
    while (left >= 0 && right < n && s[left] === s[right]) {
      var currentLength = right - left + 1;
      if (currentLength > maxLength) {
        maxLength = currentLength;
        start = left;
      }
      left--;
      right++;
    }
  }

  var result = s.substring(start, start + maxLength);
  return result;
};

