function sumPrimesUpTo(n) {
  let sum = 0;
  const primes = [];
  const isPrime = new Array(n + 1).fill(true);
  const two = 2;

  if (n < two) {
    return 0;
  }

  isPrime[0] = false;
  isPrime[1] = false;

  for (let p = two; p * p <= n; p++) {
    if (isPrime[p]) {
      for (let multiple = p * p; multiple <= n; multiple += p) {
        isPrime[multiple] = false;
      }
    }
  }

  for (let i = two; i <= n; i++) {
    if (isPrime[i]) {
      primes.push(i);
      sum += i;
    }
  }

  const result = sum;
  return result;
}

