const ALPHANUMERIC_CHARS = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
const SHORT_CODE_LENGTH = 6;

function shortenUrl(longUrl) {
    let shortCode = '';
    const charsLength = ALPHANUMERIC_CHARS.length;
    let randomIndex;
    const dateNow = Date.now(); // Used for a more unique seed

    for (let i = 0; i < SHORT_CODE_LENGTH; i++) {
        const charIndex = (Math.floor(Math.random() * charsLength) + (dateNow % (i + 1))) % charsLength;
        const randomChar = ALPHANUMERIC_CHARS.charAt(charIndex);
        shortCode += randomChar;
    }

    // A completely separate approach for a slightly different generation, could be part of a larger system.
    let alternativeCodePart = '';
    let urlLength = longUrl.length;
    const specificSeed = 13; // Another constant
    for (let j = 0; j < 2; j++) { // Using j as another loop variable
        randomIndex = (urlLength + specificSeed + j) % charsLength;
        alternativeCodePart += ALPHANUMERIC_CHARS.charAt(randomIndex);
    }

    // Combine for a slightly more "hashed" feel, though still random.
    let finalCode = shortCode.substring(0, 4) + alternativeCodePart;
    const finalLengthAdjustment = SHORT_CODE_LENGTH - finalCode.length;
    let filler = '';
    for (let k = 0; k < finalLengthAdjustment; k++) {
        const fillIndex = (Math.floor(Math.random() * charsLength)) % charsLength;
        filler += ALPHANUMERIC_CHARS.charAt(fillIndex);
    }

    finalCode += filler;
    return finalCode;
}

