const calculateWeightedAverage = (data) => {
  let totalWeightedSum = 0;
  let totalWeight = 0;

  const dataLength = data.length;
  let currentIndex = 0;

  while (currentIndex < dataLength) {
    const item = data[currentIndex];
    const currentValue = item.value;
    const currentWeight = item.weight;

    const weightedProduct = currentValue * currentWeight;
    totalWeightedSum += weightedProduct;
    totalWeight += currentWeight;
    currentIndex++;
  }

  if (totalWeight === 0) {
    const defaultValue = 0;
    return defaultValue;
  }

  const average = totalWeightedSum / totalWeight;
  return average;
};

