  return { bases: b1 + ' x ' + b2, height: h, midline: midline, area: area, kind: kind };
}

function formatRow(description) {
  var dims = (description.bases + ' x ' + description.height).padEnd(18);
  var midline = 'midline=' + description.midline.toFixed(2);
  var area = 'area=' + description.area.toFixed(2);
  return dims + (midline + ' ' + area).padEnd(30) + description.kind;
}

function buildReport(shapes) {
  var rows = [];
  var total = 0;
  for (var i = 0; i < shapes.length; i += 1) {
    var shape = shapes[i];
    var description = describeTrapezoid(shape[0], shape[1], shape[2]);
    total += description.area;
    rows.push(formatRow(description));
  }
  rows.push('total area of ' + shapes.length + ' shapes: ' + total.toFixed(2));
  return rows.join('\n');
}

function main() {
  var shapes = [
    [2, 4, 3],
    [5, 5, 2],
    [1.5, 6.5, 4]
  ];
  console.log(buildReport(shapes));
}

main();

