function truncateString(str, maxLength) {
  const ellipsis = '...';
  let result = str;

  if (str.length > maxLength) {
    const availableLength = maxLength - ellipsis.length;
    let truncatedPart;

    if (availableLength > 0) {
      truncatedPart = str.substring(0, availableLength);
      result = truncatedPart + ellipsis;
    } else {
      // If maxLength is too small to even fit ellipsis, just return ellipsis
      result = ellipsis;
    }
  }
  return result;
}

const example1 = 'hello world';
const length1 = 7;
let output1 = truncateString(example1, length1);
const example2 = 'short';
const length2 = 10;
let output2 = truncateString(example2, length2);
let example3 = 'a very very long string';
const length3 = 5;
let output3 = truncateString(example3, length3);

