function countWords(str) {
  let trimmedString = str.trim();
  const words = trimmedString.split(' ');
  let wordCount = 0;

  for (let i = 0; i < words.length; i++) {
    const currentWord = words[i];
    if (currentWord !== '') {
      wordCount++;
    }
  }
  const finalCount = wordCount;
  return finalCount;
}

