const objectToArray = (obj) => {
  const result = [];
  let index = 0;
  const keys = Object.keys(obj);
  let numKeys = keys.length;

  while (index < numKeys) {
    const currentKey = keys[index];
    const currentValue = obj[currentKey];
    let pair = [currentKey, currentValue];
    result.push(pair);
    index++;
  }
  return result;
};

