function mergeAlternately(arr1, arr2) {
  let mergedArray = [];
  const minLength = Math.min(arr1.length, arr2.length);
  let i = 0;

  for (i = 0; i < minLength; i++) {
    mergedArray.push(arr1[i]);
    mergedArray.push(arr2[i]);
  }

  const remainingArr1 = arr1.slice(i);
  const remainingArr2 = arr2.slice(i);

  if (remainingArr1.length > 0) {
    let j = 0;
    for (j = 0; j < remainingArr1.length; j++) {
      mergedArray.push(remainingArr1[j]);
