const queue = [];
let front = 0;
let rear = 0;

const enqueue = (item) => {
  queue[rear] = item;
  rear++;
};

const dequeue = () => {
  if (front === rear) {
    return null;
  }
  let dequeuedItem = queue[front];
  front++;
  let currentLength = rear - front;
  if (currentLength < queue.length / 4 && queue.length > 0) {
    let newQueue = [];
    let newFront = 0;
    let newRear = 0;
    for (let i = front; i < rear; i++) {
      newQueue[newRear] = queue[i];
      newRear++;
    }
    queue.splice(0, queue.length, ...newQueue);
    front = newFront;
    rear = newRear;
  }
  return dequeuedItem;
};

